export default LoginScreen;

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { AppState, ItemStatus, Sector, VaseType, ProductionItem, ChangelogEntry, ChangeType } from './types';
import { INITIAL_EMPLOYEES, INITIAL_VASES, DEFAULT_SUPERVISOR_PASS } from './constants';
import { v4 as uuidv4 } from 'uuid';

// Initial Version Seed - Keep at 1.4.1 so App.tsx triggers the update to 1.5.0
const INITIAL_VERSION = '1.4.1';

export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDarkMode: false,
      supervisorPassword: DEFAULT_SUPERVISOR_PASS,
      currentUser: null,
      currentSector: null,

      // Versioning Defaults
      systemVersion: INITIAL_VERSION,
      changelog: [],

      rawMaterialCostPerKg: 0.26, // Default per requirement

      employees: INITIAL_EMPLOYEES,
      vaseModels: INITIAL_VASES,
      productionItems: [],
      payments: [],
      drafts: [],

      toggleTheme: () => set((state) => ({ isDarkMode: !state.isDarkMode })),

      setSector: (sector) => set({ currentSector: sector }),

      loginUser: (user) => set({ currentUser: user }),

      logout: () => set({ currentUser: null, currentSector: null }),

      addProductionItems: (items) => set((state) => {
        // Hydrate items with current production costs from models
        const hydratedItems = items.map(item => {
          const model = state.vaseModels.find(v => v.id === item.modelId);
          return {
            ...item,
            productionValue: model ? model.costProduction : 0,
            // Calculate Raw Material Cost Snapshot: Weight * Current Rate
            rawMaterialCost: model ? (model.weightKg * state.rawMaterialCostPerKg) : 0
          };
        });
        return { productionItems: [...state.productionItems, ...hydratedItems] };
      }),

      processStageItems: (itemIds, workerId, stage, timestamp) => set((state) => {
        // Use the passed timestamp instead of Date.now()
        const updatedItems = state.productionItems.map((item) => {
          if (itemIds.includes(item.id)) {
            const model = state.vaseModels.find(v => v.id === item.modelId);

            if (stage === 'finishing') {
              return {
                ...item,
                status: ItemStatus.AWAITING_PAINTING,
                updatedAt: timestamp,
                finishedBy: workerId,
                finishingValue: model?.costFinishing || 0
              };
            }

            if (stage === 'painting') {
               // Calculate 10% commission
               const salePrice = model?.priceSale || 0;
               const commission = salePrice * 0.10;

               return {
                ...item,
                status: ItemStatus.FINISHED,
                updatedAt: timestamp,
                paintedBy: workerId,
                paintingValue: commission
              };
            }
          }
          return item;
        });
        return { productionItems: updatedItems };
      }),

      // --- DRAFT ACTIONS ---

      addDraft: (draft) => set((state) => ({ drafts: [draft, ...state.drafts] })),

      removeDraft: (id) => set((state) => ({ drafts: state.drafts.filter(d => d.id !== id) })),

      confirmDraft: (draftId) => {
        const state = get();
        const draft = state.drafts.find(d => d.id === draftId);
        if (!draft) return;

        // Logic based on Draft Type
        if (draft.type === 'PRODUCTION' && draft.productionData) {
          const newItems: ProductionItem[] = [];

          draft.productionData.forEach(({ modelId, quantity }) => {
            const model = state.vaseModels.find(v => v.id === modelId);
            if (model) {
               for (let i = 0; i < quantity; i++) {
                newItems.push({
                  id: uuidv4(),
                  modelId: model.id,
                  modelName: model.name,
                  type: model.type,
                  status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
                  createdAt: draft.selectedDate, // Use Draft Date
                  updatedAt: draft.selectedDate, // Use Draft Date
                  producedBy: draft.userId,
                  productionValue: 0, // Placeholder, calculated in addProductionItems
                  rawMaterialCost: 0 // Placeholder
                });
               }
            }
          });

          if (newItems.length > 0) {
            get().addProductionItems(newItems);
          }
        } else if ((draft.type === 'FINISHING' || draft.type === 'PAINTING') && draft.processingIds) {
           const stage = draft.type === 'FINISHING' ? 'finishing' : 'painting';
           get().processStageItems(draft.processingIds, draft.userId, stage, draft.selectedDate);
        }

        // Remove draft after processing
        get().removeDraft(draftId);
      },

      // --- SUPERVISOR ACTIONS ---

      updateSupervisorPassword: (pass) => set({ supervisorPassword: pass }),

      updateRawMaterialCostPerKg: (value) => set({ rawMaterialCostPerKg: value }),

      addVaseModel: (model) => set((state) => ({ vaseModels: [...state.vaseModels, model] })),

      updateVaseModel: (model) => set((state) => ({
        vaseModels: state.vaseModels.map((v) => (v.id === model.id ? model : v))
      })),

      deleteVaseModel: (id) => set((state) => ({
        vaseModels: state.vaseModels.filter((v) => v.id !== id)
      })),

      addEmployee: (emp) => set((state) => ({ employees: [...state.employees, emp] })),

      updateEmployee: (emp) => set((state) => ({
        employees: state.employees.map((e) => (e.id === emp.id ? emp : e))
      })),

      addPayment: (payment) => set((state) => ({ payments: [payment, ...state.payments] })),

      resetData: () => set({
        productionItems: [],
        payments: [],
        employees: INITIAL_EMPLOYEES,
        vaseModels: INITIAL_VASES,
        supervisorPassword: DEFAULT_SUPERVISOR_PASS,
        rawMaterialCostPerKg: 0.26,
        drafts: [],
        // Reset version info
        systemVersion: INITIAL_VERSION,
        changelog: []
      }),

      // --- VERSION CONTROL ACTIONS ---
      registerSystemUpdate: (type: ChangeType, description: string) => set((state) => {
        // 1. Parse current version
        const parts = state.systemVersion.split('.').map(Number);
        if (parts.length !== 3) return state; // Safety check

        let [major, minor, patch] = parts;

        // 2. Increment based on type
        switch (type) {
          case 'MAJOR':
            major++;
            minor = 0;
            patch = 0;
            break;
          case 'FEATURE':
            minor++;
            patch = 0;
            break;
          case 'IMPROVEMENT':
          case 'FIX':
            patch++;
            break;
        }

        const newVersion = `${major}.${minor}.${patch}`;

        // 3. Create new Entry
        const newEntry: ChangelogEntry = {
          version: newVersion,
          date: Date.now(),
          type,
          description
        };

        // 4. Check for duplication based on description to avoid spamming on re-renders
        if (state.changelog.length > 0 && state.changelog[0].description === description) {
           return state;
        }

        return {
          systemVersion: newVersion,
          changelog: [newEntry, ...state.changelog]
        };
      })

    }),
    {
      name: 'home-pots-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

import React, { useEffect, useRef } from 'react';
import { useStore } from './store';
import { Sector } from './types';
import LoginScreen from './screens/LoginScreen';
import ProductionScreen from './screens/ProductionScreen';
import ProcessingScreen from './screens/ProcessingScreen';
import SupervisorDashboard from './screens/SupervisorDashboard';
import InstallPWA from './components/InstallPWA';

const App: React.FC = () => {
  const { isDarkMode, currentUser, currentSector, registerSystemUpdate, systemVersion } = useStore();
  const initRef = useRef(false);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  // AUTOMATIC VERSION CONTROL TRIGGER
  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;

    // Trigger update to 1.5.0 (Feature Update)
    if (systemVersion === '1.4.1') {
       registerSystemUpdate('FEATURE', 'Revisão geral da interface para eliminar sobreposição de elementos e ajuste do fluxo de registro de produção para telas dedicadas.');
    }
  }, [systemVersion, registerSystemUpdate]);

  // Routing Logic based on State (Auth Guard)
  const renderScreen = () => {
    if (!currentUser || !currentSector) {
      return <LoginScreen />;
    }

    switch (currentSector) {
      case Sector.PRODUCTION:
        return <ProductionScreen />;
      case Sector.FINISHING:
        return <ProcessingScreen stage="finishing" />;
      case Sector.PAINTING:
        return <ProcessingScreen stage="painting" />;
      case Sector.SUPERVISOR:
        return <SupervisorDashboard />;
      default:
        return <LoginScreen />;
    }
  };

  return (
    <div className="min-h-screen bg-background text-on-background transition-colors duration-200">
      {renderScreen()}
      <InstallPWA />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { VaseType, VaseModel, Draft, DraftItemContent } from '../types';
import { Button, Modal } from '../components/UI';
import { Plus, Minus, Check, ClipboardList, ArrowLeft, TrendingUp, Wallet, FileText, Trash2, Edit, Send, Calendar, Save } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import HistoryModal from '../components/HistoryModal';

type ViewMode = 'DASHBOARD' | 'REGISTER';

const ProductionScreen: React.FC = () => {
  const { vaseModels, addDraft, removeDraft, confirmDraft, drafts, currentUser, productionItems, payments, logout } = useStore();

  // View State
  const [viewMode, setViewMode] = useState<ViewMode>('DASHBOARD');

  // Register State
  const [draftItems, setDraftItems] = useState<{model: VaseModel, quantity: number}[]>([]);
  const [selectedType, setSelectedType] = useState<VaseType>(VaseType.WITH_SHELL);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  // Dashboard & Feedback State
  const [feedback, setFeedback] = useState<string | null>(null);
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Calculations ---
  const today = new Date().toDateString();

  const myDrafts = useMemo(() => 
    drafts.filter(d => d.type === 'PRODUCTION' && d.userId === currentUser?.id)
          .sort((a,b) => b.createdAt - a.createdAt),
  [drafts, currentUser]);

  const myAllTimeProduction = useMemo(() => 
    productionItems.filter(p => p.producedBy === currentUser?.id),
  [productionItems, currentUser]);

  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  const myTodaysProduction = myAllTimeProduction.filter(p => 
    new Date(p.createdAt).toDateString() === today
  );

  const dailyTotalQty = myTodaysProduction.length;
  const dailyEarnings = myTodaysProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);

  const totalProducedValue = myAllTimeProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);
  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  const availableModels = useMemo(() => {
    return vaseModels.filter(v => v.type === selectedType);
  }, [selectedType, vaseModels]);

  // --- Handlers ---

  const startNewProduction = () => {
    setDraftItems([]);
    setSelectedDate(new Date().toISOString().split('T')[0]);
    setViewMode('REGISTER');
  };

  const addToDraft = (model: VaseModel) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === model.id);
      if (existing) {
        return prev.map(i => i.model.id === model.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { model, quantity: 1 }];
    });
  };

  const removeFromDraft = (modelId: string) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === modelId);
      if (existing && existing.quantity > 1) {
        return prev.map(i => i.model.id === modelId ? { ...i, quantity: i.quantity - 1 } : i);
      }
      return prev.filter(i => i.model.id !== modelId);
    });
  };

  const handleSaveAsDraft = () => {
    if (draftItems.length === 0 || !currentUser) return;

    const productionDate = new Date(selectedDate + 'T12:00:00').getTime();

    const productionData: DraftItemContent[] = draftItems.map(d => ({
       modelId: d.model.id,
       quantity: d.quantity
    }));

    const newDraft: Draft = {
       id: uuidv4(),
       type: 'PRODUCTION',
       sector: currentUser.sector as any,
       userId: currentUser.id,
       selectedDate: productionDate,
       createdAt: Date.now(),
       productionData: productionData
    };

    addDraft(newDraft);
    setFeedback('Rascunho salvo!');
    setTimeout(() => setFeedback(null), 2000);
    setViewMode('DASHBOARD');
  };

  const handleEditDraft = (draft: Draft) => {
    if (!draft.productionData) return;

    const reconstructed: {model: VaseModel, quantity: number}[] = [];
    draft.productionData.forEach(item => {
      const model = vaseModels.find(v => v.id === item.modelId);
      if (model) {
        reconstructed.push({ model, quantity: item.quantity });
      }
    });

    setDraftItems(reconstructed);
    setSelectedDate(new Date(draft.selectedDate).toISOString().split('T')[0]);

    if (reconstructed.length > 0) {
      setSelectedType(reconstructed[0].model.type);
    }

    removeDraft(draft.id); // Remove old draft to "update" it
    setViewMode('REGISTER');
  };

  const handleConfirmDraft = (draftId: string) => {
    confirmDraft(draftId);
    setFeedback('Produção confirmada!');
    setTimeout(() => setFeedback(null), 2000);
  };

  // --- RENDERERS ---

  if (viewMode === 'REGISTER') {
    const totalItems = draftItems.reduce((a, b) => a + b.quantity, 0);
    const totalValue = draftItems.reduce((a, b) => a + (b.quantity * b.model.costProduction), 0);

    return (
      <div className="bg-background min-h-screen flex flex-col">
        {/* Header */}
        <div className="bg-surface p-4 sticky top-0 z-20 shadow-sm flex items-center justify-between border-b border-outline-variant">
          <Button variant="ghost" onClick={() => setViewMode('DASHBOARD')} className="text-on-surface-variant -ml-2">
            <ArrowLeft className="w-6 h-6 mr-1" /> Voltar
          </Button>
          <h1 className="text-lg font-medium text-on-surface">Nova Produção</h1>
          <div className="w-10"></div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 p-4 pb-32 space-y-6">

          {/* Date Picker Card */}
          <div className="bg-surface p-4 rounded-2xl border border-outline-variant shadow-sm">
            <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-2 flex items-center gap-2">
              <Calendar className="w-4 h-4" /> Data da Produção
            </label>
            <input 
              type="date" 
              className="w-full p-3 bg-surface-variant text-on-surface border border-outline-variant rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-lg"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
            />
          </div>

          {/* Type Selector */}
          <div className="flex bg-surface-variant p-1 rounded-xl border border-outline-variant">
            <button 
              onClick={() => setSelectedType(VaseType.WITH_SHELL)}
              className={`flex-1 py-3 px-4 rounded-lg text-sm font-bold transition-all ${
                selectedType === VaseType.WITH_SHELL 
                  ? 'bg-primary text-on-primary shadow-sm' 
                  : 'text-on-surface-variant hover:text-on-surface'
              }`}
            >
              Com Casca
            </button>
            <button 
              onClick={() => setSelectedType(VaseType.WITHOUT_SHELL)}
              className={`flex-1 py-3 px-4 rounded-lg text-sm font-bold transition-all ${
                selectedType === VaseType.WITHOUT_SHELL 
                  ? 'bg-secondary text-on-secondary shadow-sm' 
                  : 'text-on-surface-variant hover:text-on-surface'
              }`}
            >
              Sem Casca
            </button>
          </div>

          {/* Models List */}
          <div className="space-y-3">
            <p className="text-sm font-medium text-on-surface-variant ml-2 uppercase tracking-wide">Modelos Disponíveis</p>
            {availableModels.map(model => {
              const inDraft = draftItems.find(i => i.model.id === model.id)?.quantity || 0;
              return (
                <div key={model.id} className="bg-surface border border-outline-variant rounded-2xl p-4 flex items-center justify-between shadow-sm">
                  <div>
                    <p className="font-bold text-lg text-on-surface">{model.name}</p>
                    <p className="text-sm text-on-surface-variant mt-0.5">Mão de obra: <span className="font-bold text-success">R$ {model.costProduction.toFixed(2)}</span></p>
                  </div>

                  <div className="flex items-center gap-4">
                    <button 
                      onClick={() => removeFromDraft(model.id)}
                      disabled={inDraft === 0}
                      className="w-10 h-10 rounded-full bg-surface-variant border border-outline-variant flex items-center justify-center text-on-surface-variant disabled:opacity-30 active:scale-95 transition-all"
                    >
                      <Minus className="w-5 h-5" />
                    </button>

                    <span className={`w-6 text-center text-xl font-bold ${inDraft > 0 ? 'text-primary' : 'text-on-surface-variant'}`}>
                      {inDraft}
                    </span>

                    <button 
                      onClick={() => addToDraft(model)}
                      className="w-10 h-10 rounded-full bg-primary-container border border-primary/20 flex items-center justify-center text-on-primary-container active:scale-95 transition-all hover:brightness-110"
                    >
                      <Plus className="w-5 h-5" />
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Fixed Footer */}
        <div className="bg-surface border-t border-outline-variant p-4 fixed bottom-0 left-0 right-0 z-30 shadow-[0_-4px_20px_rgba(0,0,0,0.1)]">
           <div className="max-w-3xl mx-auto flex items-center justify-between gap-4">
              <div>
                 <p className="text-xs text-on-surface-variant uppercase font-bold">Resumo</p>
                 <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-bold text-on-surface">{totalItems}</span>
                    <span className="text-sm text-on-surface-variant">itens</span>
                 </div>
                 <p className="text-xs text-success font-medium">Est. R$ {totalValue.toFixed(2)}</p>
              </div>

              <Button 
                onClick={handleSaveAsDraft} 
                disabled={totalItems === 0}
                className="flex-1 h-12 bg-secondary-container text-on-secondary-container rounded-xl font-bold text-base shadow-none"
              >
                 <Save className="w-5 h-5 mr-2" />
                 Adicionar ao Rascunho
              </Button>
           </div>
        </div>
      </div>
    );
  }

  // DASHBOARD VIEW
  return (
    <div className="pb-32 bg-background min-h-screen">
      {/* Top App Bar */}
      <div className="bg-surface p-4 sticky top-0 z-10 shadow-sm flex items-center justify-between border-b border-outline-variant">
         <Button variant="ghost" onClick={logout} className="text-on-surface-variant">
            <ArrowLeft className="w-6 h-6" />
         </Button>
         <h1 className="text-xl font-medium text-on-surface">Setor de Produção</h1>
         <div className="w-10"></div>
      </div>

      <div className="p-4 max-w-3xl mx-auto space-y-6">
        {/* Financial Dashboard - Solid Background */}
        <div className="bg-primary rounded-3xl p-6 text-on-primary shadow-lg relative overflow-hidden">
          <div className="flex justify-between items-start mb-6 relative z-10">
             <div>
               <p className="text-on-primary font-medium opacity-90">Olá, {currentUser?.name}</p>
               <h2 className="text-2xl font-bold">Seu desempenho</h2>
             </div>
             <div className="bg-primary-container p-2 rounded-xl text-on-primary-container">
               <TrendingUp className="w-5 h-5" />
             </div>
          </div>

          <div className="grid grid-cols-2 gap-4 relative z-10">
             {/* Card 1: Daily Production */}
             <button 
                onClick={() => setHistoryMode('items')}
                className="bg-primary-container text-on-primary-container rounded-2xl p-4 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-primary outline-none shadow-sm"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <ClipboardList className="w-4 h-4" />
                   <span className="text-sm font-medium">Hoje</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">{dailyTotalQty}</div>
                <div className="text-xs opacity-90 mt-1 flex items-center font-medium">
                   R$ {dailyEarnings.toFixed(2)}
                </div>
             </button>

             {/* Card 2: Current Balance */}
             <button 
                onClick={() => setHistoryMode('financial')} 
                className="bg-primary-container text-on-primary-container rounded-2xl p-4 active:scale-95 transition-all text-left group cursor-pointer ring-offset-2 focus:ring-2 ring-primary outline-none shadow-sm"
             >
                <div className="flex items-center gap-2 mb-1 opacity-80">
                   <Wallet className="w-4 h-4" />
                   <span className="text-sm font-medium">Saldo Atual</span>
                </div>
                <div className="text-3xl font-bold group-hover:scale-105 transition-transform origin-left">R$ {currentBalance.toFixed(2)}</div>
                <div className="text-xs opacity-90 mt-1 flex items-center font-medium">
                  Clique para detalhes
                </div>
             </button>
          </div>
        </div>

        {/* --- DRAFTS SECTION --- */}
        {myDrafts.length > 0 && (
          <div className="animate-in slide-in-from-bottom-2 duration-500">
             <div className="flex items-center gap-2 mb-3 px-2">
                <FileText className="w-5 h-5 text-secondary" />
                <h3 className="text-lg font-medium text-on-background">Rascunhos Pendentes</h3>
                <span className="bg-secondary-container text-on-secondary-container text-xs font-bold px-2 py-0.5 rounded-full">{myDrafts.length}</span>
             </div>

             <div className="space-y-3">
               {myDrafts.map(draft => {
                 const totalQty = draft.productionData?.reduce((a,b) => a + b.quantity, 0) || 0;
                 const draftDate = new Date(draft.selectedDate).toLocaleDateString();

                 return (
                   <div key={draft.id} className="bg-surface border border-outline-variant p-5 rounded-2xl relative shadow-sm">
                      <div className="flex justify-between items-start mb-4">
                         <div>
                            <div className="flex items-center gap-2">
                               <p className="font-bold text-lg text-on-surface">Produção de {draftDate}</p>
                            </div>
                            <p className="text-xs text-on-surface-variant mt-0.5">Criado em {new Date(draft.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                         </div>
                         <div className="flex items-center gap-1">
                            <button onClick={() => handleEditDraft(draft)} className="p-2 text-on-surface-variant hover:text-primary hover:bg-primary-container rounded-full transition-colors" title="Editar">
                               <Edit className="w-5 h-5" />
                            </button>
                            <button onClick={() => removeDraft(draft.id)} className="p-2 text-on-surface-variant hover:text-error hover:bg-error-container rounded-full transition-colors" title="Excluir">
                               <Trash2 className="w-5 h-5" />
                            </button>
                         </div>
                      </div>

                      <div className="flex flex-wrap gap-2 mb-5">
                         {draft.productionData?.map((item, idx) => {
                           const model = vaseModels.find(v => v.id === item.modelId);
                           if (!model) return null;
                           return (
                             <span key={idx} className="text-xs bg-surface-variant text-on-surface-variant font-medium px-3 py-1.5 rounded-lg border border-outline-variant">
                               {item.quantity}x {model.name}
                             </span>
                           )
                         })}
                      </div>

                      <Button onClick={() => handleConfirmDraft(draft.id)} variant="primary" className="w-full gap-2 h-12 text-base font-bold">
                         <Send className="w-5 h-5" /> Confirmar Produção
                      </Button>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      {/* Floating Action Button - Opens New View */}
      <div className="fixed bottom-6 right-6 z-20">
        <Button 
           variant="fab" 
           size="lg" 
           onClick={startNewProduction}
           className="h-16 pl-6 pr-8 rounded-[24px] shadow-xl hover:shadow-2xl transition-all active:scale-95"
        >
          <Plus className="w-6 h-6 mr-3" />
          <span className="text-lg font-medium">Registrar Produção</span>
        </Button>
      </div>

      {/* Snackbar Feedback */}
      {feedback && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 animate-in slide-in-from-bottom fade-in duration-300 w-full px-4 flex justify-center">
           <div className="bg-on-surface text-surface px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 border border-outline-variant">
              <Check className="w-5 h-5 text-success" />
              <span className="font-medium">{feedback}</span>
           </div>
        </div>
      )}

      {/* History Modal Logic */}
      {historyMode === 'financial' ? (
        <Modal isOpen={true} onClose={() => setHistoryMode('none')} title="Detalhes Financeiros" footer={
          <Button variant="ghost" onClick={() => setHistoryMode('none')}>Fechar</Button>
        }>
           <div className="space-y-3 py-2">
             <button onClick={() => setHistoryMode('items')} className="w-full p-4 rounded-2xl bg-surface border border-outline-variant flex justify-between items-center hover:bg-primary-container hover:text-on-primary-container transition-colors group">
               <div className="flex items-center gap-3">
                  <div className="bg-primary-container text-on-primary-container p-2 rounded-full group-hover:bg-primary group-hover:text-on-primary transition-colors"><ClipboardList className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold">Histórico de Produção</p>
                     <p className="text-xs opacity-80">Veja tudo que você produziu</p>
                  </div>
               </div>
               <span className="font-bold text-primary group-hover:text-on-primary-container">R$ {totalProducedValue.toFixed(2)}</span>
             </button>

             <button onClick={() => setHistoryMode('payments')} className="w-full p-4 rounded-2xl bg-surface border border-outline-variant flex justify-between items-center hover:bg-success-container hover:text-on-success-container transition-colors group">
               <div className="flex items-center gap-3">
                  <div className="bg-success-container text-on-success-container p-2 rounded-full group-hover:bg-success group-hover:text-on-success transition-colors"><Wallet className="w-5 h-5"/></div>
                  <div className="text-left">
                     <p className="font-bold">Pagamentos Recebidos</p>
                     <p className="text-xs opacity-80">Extrato de valores pagos</p>
                  </div>
               </div>
               <span className="font-bold text-success group-hover:text-on-success-container">R$ {totalReceivedValue.toFixed(2)}</span>
             </button>

             <div className="mt-4 pt-4 border-t border-outline-variant flex justify-between items-center">
               <span className="text-on-surface-variant font-medium">Saldo a Receber</span>
               <span className="text-xl font-bold text-on-surface">R$ {currentBalance.toFixed(2)}</span>
             </div>
           </div>
        </Modal>
      ) : (
        <HistoryModal 
          isOpen={historyMode !== 'none'}
          onClose={() => setHistoryMode('none')}
          mode={historyMode === 'items' ? 'items' : historyMode === 'payments' ? 'payments' : 'financial'}
          items={myAllTimeProduction}
          payments={myAllTimePayments}
          vaseModels={vaseModels}
          valueKey="productionValue"
          title={historyMode === 'items' ? 'Histórico de Produção' : historyMode === 'payments' ? 'Pagamentos Recebidos' : 'Extrato'}
        />
      )}
    </div>
  );
};

export default ProductionScreen;

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { ItemStatus, Draft } from '../types';
import { Button } from '../components/UI';
import { Check, ArrowLeft, PaintBucket, Brush, TrendingUp, Wallet, Hammer, FileText, Trash2, Edit, Send, Calendar, Save, X } from 'lucide-react';
import HistoryModal from '../components/HistoryModal';
import { v4 as uuidv4 } from 'uuid';

interface Props {
  stage: 'finishing' | 'painting';
}

type ViewMode = 'DASHBOARD' | 'REVIEW';

const ProcessingScreen: React.FC<Props> = ({ stage }) => {
  const { productionItems, addDraft, removeDraft, confirmDraft, drafts, currentUser, logout, vaseModels, payments } = useStore();

  // View State
  const [viewMode, setViewMode] = useState<ViewMode>('DASHBOARD');

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  const [feedback, setFeedback] = useState<string | null>(null);
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Calculations ---
  const today = new Date().toDateString();

  const myDrafts = useMemo(() => {
    const draftType = stage === 'finishing' ? 'FINISHING' : 'PAINTING';
    return drafts.filter(d => d.type === draftType && d.userId === currentUser?.id)
          .sort((a,b) => b.createdAt - a.createdAt);
  }, [drafts, currentUser, stage]);

  const itemsInDrafts = useMemo(() => {
     const ids = new Set<string>();
     myDrafts.forEach(d => d.processingIds?.forEach(id => ids.add(id)));
     return ids;
  }, [myDrafts]);

  const myAllTimeItems = useMemo(() => productionItems.filter(p => {
    if (stage === 'finishing') return p.finishedBy === currentUser?.id;
    if (stage === 'painting') return p.paintedBy === currentUser?.id;
    return false;
  }), [productionItems, currentUser, stage]);

  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  const myTodaysItems = myAllTimeItems.filter(p => 
     new Date(p.updatedAt).toDateString() === today
  );

  const dailyTotalQty = myTodaysItems.length;
  const dailyEarnings = myTodaysItems.reduce<number>((acc, item) => {
    if (stage === 'finishing') return acc + (item.finishingValue || 0);
    if (stage === 'painting') return acc + (item.paintingValue || 0);
    return acc;
  }, 0);

  const totalProducedValue = myAllTimeItems.reduce<number>((acc, item) => {
     if (stage === 'finishing') return acc + (item.finishingValue || 0);
     if (stage === 'painting') return acc + (item.paintingValue || 0);
     return acc;
  }, 0);

  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  // Config
  const config = stage === 'finishing' ? {
    inputStatus: ItemStatus.AWAITING_FINISHING,
    title: 'Setor de Acabamento',
    icon: <Brush className="w-6 h-6 text-on-secondary-container" />,
    actionLabel: 'Confirmar Acabamento',
    emptyMsg: 'Sem vasos para acabamento.',
    themeColor: 'secondary'
  } : {
    inputStatus: ItemStatus.AWAITING_PAINTING,
    title: 'Setor de Pintura',
    icon: <PaintBucket className="w-6 h-6 text-on-primary-container" />,
    actionLabel: 'Confirmar Pintura',
    emptyMsg: 'Sem vasos para pintura.',
    themeColor: 'primary'
  };

  const pendingItems = useMemo(() => 
    productionItems.filter(i => 
      i.status === config.inputStatus && !itemsInDrafts.has(i.id)
    )
    .sort((a,b) => b.createdAt - a.createdAt),
  [productionItems, config.inputStatus, itemsInDrafts]);

  // Earnings for current selection
  const selectionEarnings = Array.from(selectedIds).reduce<number>((acc, id) => {
    const item = pendingItems.find(i => i.id === id);
    if (!item) return acc;
    const model = vaseModels.find(v => v.id === item.modelId);
    if (!model) return acc;

    if (stage === 'finishing') return acc + (model.costFinishing || 0);
    if (stage === 'painting') return acc + ((model.priceSale || 0) * 0.10);
    return acc;
  }, 0);

  // Theme Classes
  const themeClasses = config.themeColor === 'secondary' ? {
     bg: 'bg-secondary',
     container: 'bg-secondary-container',
     text: 'text-secondary',
     border: 'border-secondary',
     onContainer: 'text-on-secondary-container',
     onBg: 'text-on-secondary'
  } : {
     bg: 'bg-primary',
     container: 'bg-primary-container',
     text: 'text-primary',
     border: 'border-primary',
     onContainer: 'text-on-primary-container',
     onBg: 'text-on-primary'
  };

  // --- Handlers ---

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const proceedToReview = () => {
    if (selectedIds.size > 0) {
      setViewMode('REVIEW');
    }
  };

  const handleSaveAsDraft = () => {
    if (!currentUser) return;

    const processDate = new Date(selectedDate + 'T12:00:00').getTime();

    const newDraft: Draft = {
        id: uuidv4(),
        type: stage === 'finishing' ? 'FINISHING' : 'PAINTING',
        sector: currentUser.sector as any,
        userId: currentUser.id,
        selectedDate: processDate,
        createdAt: Date.now(),
        processingIds: Array.from(selectedIds)
    };

    addDraft(newDraft);

    setSelectedIds(new Set());
    setViewMode('DASHBOARD');
    setFeedback('Rascunho salvo!');
    setTimeout(() => setFeedback(null), 2000);
  };

  const handleEditDraft = (draft: Draft) => {
      removeDraft(draft.id);
      const restoredIds = new Set<string>(draft.processingIds);
      setSelectedIds(restoredIds);
      setSelectedDate(new Date(draft.selectedDate).toISOString().split('T')[0]);
      setViewMode('REVIEW'); // Jump straight to review when editing
  };

  const handleConfirmDraft = (draftId: string) => {
      confirmDraft(draftId);
      setFeedback('Processamento confirmado!');
      setTimeout(() => setFeedback(null), 2000);
  };

  const getUnitValueDisplay = (modelId: string) => {
    const model = vaseModels.find(v => v.id === modelId);
    if (!model) return 'R$ 0.00';
    if (stage === 'finishing') return `R$ ${model.costFinishing?.toFixed(2)}`;
    if (stage === 'painting') return `R$ ${((model.priceSale || 0) * 0.10).toFixed(2)}`;
    return 'R$ 0.00';
  };

  // --- REVIEW VIEW ---
  if (viewMode === 'REVIEW') {
    return (
       <div className="bg-background min-h-screen flex flex-col">
          {/* Header */}
          <div className="bg-surface p-4 sticky top-0 z-20 shadow-sm flex items-center justify-between border-b border-outline-variant">
            <Button variant="ghost" onClick={() => setViewMode('DASHBOARD')} className="text-on-surface-variant -ml-2">
              <ArrowLeft className="w-6 h-6 mr-1" /> Voltar
            </Button>
            <h1 className="text-lg font-medium text-on-surface">Confirmar Serviço</h1>
            <div className="w-10"></div>
          </div>

          <div className="flex-1 p-4 pb-32 space-y-6">
             {/* Review Card */}
             <div className="bg-surface p-6 rounded-3xl border border-outline-variant shadow-sm text-center">
                <div className={`w-16 h-16 mx-auto rounded-full flex items-center justify-center mb-4 ${themeClasses.container} ${themeClasses.onContainer}`}>
                   {config.icon}
                </div>
                <h2 className="text-2xl font-bold text-on-surface mb-1">{selectedIds.size} Vasos</h2>
                <p className="text-on-surface-variant">Selecionados para {stage === 'finishing' ? 'Acabamento' : 'Pintura'}</p>

                <div className="mt-6 p-4 bg-surface-variant rounded-2xl border border-outline-variant flex justify-between items-center">
                   <span className="text-sm font-medium text-on-surface-variant uppercase tracking-wider">Valor Total</span>
                   <span className={`text-2xl font-bold ${stage === 'finishing' ? 'text-secondary' : 'text-primary'}`}>
                      R$ {selectionEarnings.toFixed(2)}
                   </span>
                </div>
             </div>

             {/* Date Picker */}
             <div className="bg-surface p-4 rounded-2xl border border-outline-variant shadow-sm">
                <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-2 flex items-center gap-2">
                  <Calendar className="w-4 h-4" /> Data de Execução
                </label>
                <input 
                  type="date" 
                  className="w-full p-3 bg-surface-variant text-on-surface border border-outline-variant rounded-xl focus:outline-none focus:ring-2 focus:ring-primary text-lg"
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                />
             </div>

             {/* Warning */}
             <div className="bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200 p-4 rounded-2xl border border-yellow-200 dark:border-yellow-800 text-sm leading-relaxed">
               <p className="font-bold mb-1">Atenção</p>
               Este lote será salvo como <strong>Rascunho</strong>. Você precisará confirmá-lo na tela inicial para receber o pagamento.
             </div>
          </div>

          {/* Footer Action */}
          <div className="bg-surface border-t border-outline-variant p-4 fixed bottom-0 left-0 right-0 z-30 shadow-[0_-4px_20px_rgba(0,0,0,0.1)]">
             <div className="max-w-3xl mx-auto flex gap-3">
                <Button variant="ghost" onClick={() => setViewMode('DASHBOARD')} className="flex-1 h-12">
                   Cancelar
                </Button>
                <Button onClick={handleSaveAsDraft} className={`flex-[2] h-12 rounded-xl font-bold text-base ${themeClasses.bg} text-on-primary`}>
                   <Save className="w-5 h-5 mr-2" />
                   Salvar Rascunho
                </Button>
             </div>
          </div>
       </div>
