               <p className="text-xs text-on-surface-variant mt-2">O setor define quais telas o funcionário pode acessar e como sua produção é calculada.</p>
             </div>
             <div className="flex items-center gap-3 pt-2">
                <input 
                  type="checkbox" 
                  id="activeCheck" 
                  className="w-5 h-5 rounded border-outline text-primary focus:ring-primary"
                  checked={editingEmp.active}
                  onChange={e => setEditingEmp({...editingEmp, active: e.target.checked})}
                />
                <label htmlFor="activeCheck" className="text-on-surface font-medium">Cadastro Ativo</label>
             </div>
          </div>
        </Modal>
       </div>
    )
  };

  const PaymentsTab = () => {
    const [selectedEmpId, setSelectedEmpId] = useState<string>('');
    const [amount, setAmount] = useState<string>('');
    const [obs, setObs] = useState('');
    const [feedback, setFeedback] = useState('');
    const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

    const activeEmployees = useMemo(() => employees.filter(e => e.active), [employees]);
    const selectedEmployee = activeEmployees.find(e => e.id === selectedEmpId);

    const handleRegisterPayment = () => {
       if (!selectedEmployee || !amount) return;
       const val = parseFloat(amount);
       if (isNaN(val) || val <= 0) return;
       const paymentDate = new Date(selectedDate + 'T12:00:00').getTime();
       const record: PaymentRecord = {
         id: uuidv4(),
         employeeId: selectedEmployee.id,
         employeeName: selectedEmployee.name,
         sector: selectedEmployee.sector,
         amount: val,
         date: paymentDate,
         observation: obs
       };
       addPayment(record);
       setAmount('');
       setObs('');
       setFeedback('Pagamento registrado!');
       setTimeout(() => setFeedback(''), 3000);
    };

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
        <h2 className="text-2xl font-normal text-on-background px-1">Gestão de Pagamentos</h2>
        <Card className="border-primary/20 bg-surface shadow-md">
           <div className="flex items-center gap-2 mb-4 text-primary">
              <Wallet className="w-5 h-5" />
              <span className="font-bold uppercase text-xs tracking-wider">Novo Pagamento</span>
           </div>
           <div className="space-y-4">
              <div>
                <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Funcionário</label>
                <select 
                  className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                  value={selectedEmpId}
                  onChange={e => setSelectedEmpId(e.target.value)}
                >
                  <option value="">Selecione...</option>
                  {activeEmployees.map(e => (
                    <option key={e.id} value={e.id}>{e.name} - {e.sector}</option>
                  ))}
                </select>
              </div>
              {selectedEmployee && (
                 <div className="flex items-center gap-2 px-1">
                    <span className="text-sm text-on-surface-variant">Setor:</span>
                    <Badge color="blue">{selectedEmployee.sector}</Badge>
                 </div>
              )}
              <div>
                 <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block flex items-center gap-2">
                    <CalendarIcon className="w-3 h-3" /> Data
                 </label>
                 <input 
                   type="date" 
                   className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                   value={selectedDate}
                   onChange={(e) => setSelectedDate(e.target.value)}
                   required
                 />
              </div>
              <div>
                <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Valor (R$)</label>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-on-surface-variant font-bold">R$</span>
                  <input 
                    type="number" 
                    className="w-full pl-12 pr-4 py-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary text-lg font-bold"
                    value={amount}
                    onChange={e => setAmount(e.target.value)}
                    placeholder="0.00"
                  />
                </div>
              </div>
              <div>
                <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Observação (Opcional)</label>
                <input 
                   className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                   value={obs}
                   onChange={e => setObs(e.target.value)}
                   placeholder="Ex: Adiantamento, Vale, Salário..."
                />
              </div>
              <Button onClick={handleRegisterPayment} className="w-full h-12 text-base shadow-lg" disabled={!selectedEmployee || !amount}>
                 Registrar Pagamento
              </Button>
              {feedback && <p className="text-success text-center font-bold text-sm">{feedback}</p>}
           </div>
        </Card>
        <div>
           <h3 className="font-bold text-on-surface mb-3 px-1">Histórico Recente</h3>
           <div className="space-y-3">
              {payments.length === 0 ? (
                 <div className="text-center py-8 text-on-surface-variant bg-surface rounded-2xl border border-outline-variant">
                    Nenhum pagamento registrado.
                 </div>
              ) : (
                payments.sort((a,b) => b.date - a.date).map(p => (
                   <div key={p.id} className="bg-surface p-4 rounded-2xl border border-outline-variant flex justify-between items-center shadow-sm">
                      <div>
                         <p className="font-bold text-on-surface">{p.employeeName}</p>
                         <div className="flex items-center gap-2 mt-1">
                            <span className="text-xs text-on-surface-variant">{new Date(p.date).toLocaleDateString()}</span>
                            <span className="w-1 h-1 bg-outline-variant rounded-full"></span>
                            <span className="text-xs text-on-surface-variant">{p.sector}</span>
                         </div>
                         {p.observation && <p className="text-xs text-on-surface-variant italic mt-1">"{p.observation}"</p>}
                      </div>
                      <span className="text-lg font-bold text-success bg-success-container text-on-success-container px-3 py-1 rounded-lg">
                         R$ {p.amount.toFixed(2)}
                      </span>
                   </div>
                ))
              )}
           </div>
        </div>
      </div>
    );
  };

  const ConfigTab = () => {
    const [confirmReset, setConfirmReset] = useState(false);
    const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
    const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
    const [filterEmployeeId, setFilterEmployeeId] = useState<string>('');

    const handleExportReport = (type: 'production' | 'financial') => {
      const start = new Date(startDate + 'T00:00:00').getTime();
      const end = new Date(endDate + 'T23:59:59').getTime();
      let filteredItems = productionItems.filter(i => i.createdAt >= start && i.createdAt <= end);
      let filteredPayments = payments.filter(p => p.date >= start && p.date <= end);

      if (filterEmployeeId) {
        filteredItems = filteredItems.filter(i => i.producedBy === filterEmployeeId || i.finishedBy === filterEmployeeId || i.paintedBy === filterEmployeeId);
        filteredPayments = filteredPayments.filter(p => p.employeeId === filterEmployeeId);
      }
      const contextLabel = `supervisor_${startDate}_${endDate}`;
      if (type === 'production') {
        exportFullSupervisorReport(filteredItems, filteredPayments, vaseModels, contextLabel);
      } else {
        exportPaymentReport(filteredPayments, contextLabel);
      }
    };

    return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
        <h2 className="text-2xl font-normal text-on-background px-1">Configurações</h2>

        <Card className="p-5 border border-outline-variant bg-surface">
           <div className="flex items-center gap-3 mb-4 text-secondary">
             <div className="bg-secondary-container p-2 rounded-full"><FileDown className="w-5 h-5 text-on-secondary-container" /></div>
             <h3 className="font-bold text-on-surface">Relatórios & Exportação</h3>
           </div>
           <div className="space-y-4 bg-surface-variant p-4 rounded-xl border border-outline-variant">
              <div className="grid grid-cols-2 gap-3">
                 <div>
                   <label className="text-xs font-bold text-on-surface-variant uppercase mb-1 block">Início</label>
                   <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-2 rounded-lg border border-outline-variant bg-surface text-sm" />
                 </div>
                 <div>
                   <label className="text-xs font-bold text-on-surface-variant uppercase mb-1 block">Fim</label>
                   <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-2 rounded-lg border border-outline-variant bg-surface text-sm" />
                 </div>
              </div>
              <div>
                 <label className="text-xs font-bold text-on-surface-variant uppercase mb-1 block">Filtrar por Funcionário (Opcional)</label>
                 <select value={filterEmployeeId} onChange={e => setFilterEmployeeId(e.target.value)} className="w-full p-2 rounded-lg border border-outline-variant bg-surface text-sm">
                   <option value="">Todos</option>
                   {employees.map(e => <option key={e.id} value={e.id}>{e.name} - {e.sector}</option>)}
                 </select>
              </div>
              <div className="grid grid-cols-2 gap-3 pt-2">
                 <Button onClick={() => handleExportReport('production')} variant="secondary" className="text-xs h-10">Exportar Produção</Button>
                 <Button onClick={() => handleExportReport('financial')} variant="outline" className="text-xs h-10 border-primary text-primary hover:bg-primary-container">Exportar Pagamentos</Button>
              </div>
           </div>
        </Card>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
           <Card className="p-5 border border-outline-variant bg-surface">
              <div className="flex items-center gap-3 mb-3 text-primary">
                <div className="bg-primary-container p-2 rounded-full"><Scale className="w-5 h-5 text-on-primary-container" /></div>
                <h3 className="font-bold text-on-surface">Matéria-Prima</h3>
              </div>
              <div className="relative">
                 <span className="absolute left-4 top-1/2 -translate-y-1/2 text-on-surface-variant font-bold">R$</span>
                 <input type="number" step="0.01" className="w-full pl-12 pr-4 py-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary font-bold text-lg" value={rawMaterialCostPerKg} onChange={(e) => updateRawMaterialCostPerKg(parseFloat(e.target.value))} />
                 <p className="text-xs text-on-surface-variant mt-2">Custo do Traço (por Kg)</p>
              </div>
           </Card>

           <Card className="flex items-center justify-between p-5 cursor-pointer hover:bg-surface-variant transition-colors bg-surface border-outline-variant" onClick={toggleTheme}>
              <div className="flex items-center gap-3">
                <div className="bg-surface-variant p-2 rounded-full"><Moon className="w-5 h-5 text-on-surface-variant" /></div>
                <span className="font-medium text-on-surface">Modo Escuro</span>
              </div>
              <div className={`w-12 h-7 rounded-full p-1 transition-colors ${isDarkMode ? 'bg-primary' : 'bg-surface-variant border border-outline-variant'}`}>
                 <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${isDarkMode ? 'translate-x-5' : 'translate-x-0'}`} />
              </div>
           </Card>
        </div>

        <Card className="p-5 border-error/50 bg-error-container text-on-error-container">
           <h3 className="font-bold mb-2 flex items-center gap-2"><Trash className="w-4 h-4" /> Zona de Perigo</h3>
           {!confirmReset ? (
              <Button variant="danger" className="w-full bg-surface text-error border border-error/20 hover:bg-surface-variant shadow-sm" onClick={() => setConfirmReset(true)}>Resetar Dados do Sistema</Button>
           ) : (
             <div className="flex gap-2">
               <Button variant="ghost" onClick={() => setConfirmReset(false)} className="flex-1 bg-surface/50">Cancelar</Button>
               <Button variant="danger" onClick={() => { resetData(); setConfirmReset(false); }} className="flex-1">Confirmar Reset</Button>
             </div>
           )}
        </Card>

        <Button variant="outline" className="w-full mt-4 text-on-surface-variant border-outline bg-surface" onClick={logout}>
          <LogOut className="mr-2 h-4 w-4" /> Encerrar Sessão
        </Button>
      </div>
    );
  };

  const UpdatesTab = () => {
    const getTypeConfig = (type: string) => {
        switch(type) {
        case 'FIX': return { icon: <Bug className="w-4 h-4" />, color: 'bg-error-container text-on-error-container', label: 'Correção' };
        case 'FEATURE': return { icon: <Star className="w-4 h-4" />, color: 'bg-success-container text-on-success-container', label: 'Nova Função' };
        case 'IMPROVEMENT': return { icon: <Zap className="w-4 h-4" />, color: 'bg-primary-container text-on-primary-container', label: 'Melhoria' };
        case 'MAJOR': return { icon: <Activity className="w-4 h-4" />, color: 'bg-tertiary-container text-on-tertiary-container', label: 'Versão Principal' };
        default: return { icon: <History className="w-4 h-4" />, color: 'bg-surface-variant text-on-surface-variant', label: 'Info' };
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <h2 className="text-2xl font-normal text-on-background px-1">Atualizações do Sistema</h2>
            <Card className="bg-surface border-outline-variant p-0 overflow-hidden">
                {changelog.length === 0 ? (
                    <div className="p-8 text-center text-on-surface-variant">
                        Nenhum registro de atualização encontrado.
                    </div>
                ) : (
                    <div>
                        {changelog.map((entry, idx) => {
                            const config = getTypeConfig(entry.type);
                            return (
                                <div key={idx} className="p-4 border-b border-outline-variant last:border-0 hover:bg-surface-variant/30 transition-colors">
                                    <div className="flex justify-between items-start mb-2">
                                        <div className="flex items-center gap-3">
                                            <span className="text-xl font-bold text-primary">v{entry.version}</span>
                                            <span className={`flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] uppercase font-bold ${config.color}`}>
                                                {config.icon} {config.label}
                                            </span>
                                        </div>
                                        <span className="text-xs text-on-surface-variant">{new Date(entry.date).toLocaleDateString()}</span>
                                    </div>
                                    <p className="text-on-surface opacity-90 leading-relaxed">
                                        {entry.description}
                                    </p>
                                </div>
                            )
                        })}
                    </div>
                )}
            </Card>
            <div className="text-center text-on-surface-variant text-xs p-4">
                Versão Atual: <span className="font-bold">{systemVersion}</span>
            </div>
        </div>
    );
  };

  // --- NEW AUDIT TAB ---
  const AuditTab = () => {
    return (
       <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
          <h2 className="text-2xl font-normal text-on-background px-1">Auditoria (Logs)</h2>
          <Card className="bg-surface border-outline-variant p-0 overflow-hidden">
             {systemLogs.length === 0 ? (
                <div className="p-8 text-center text-on-surface-variant">
                   Nenhum log de sistema encontrado.
                </div>
             ) : (
                <div className="divide-y divide-outline-variant">
                   {systemLogs.slice(0, 50).map((log) => (
                      <div key={log.id} className="p-4 hover:bg-surface-variant/30 transition-colors">
                         <div className="flex justify-between items-start mb-1">
                            <div className="flex items-center gap-2">
                               <Badge color={log.action === 'PAYMENT' ? 'green' : log.action === 'PRODUCTION' ? 'blue' : 'yellow'}>
                                  {log.action}
                               </Badge>
                               <span className="text-xs font-bold text-on-surface">{new Date(log.timestamp).toLocaleString()}</span>
                            </div>
                            {log.value && <span className="text-sm font-bold text-primary">R$ {log.value.toFixed(2)}</span>}
                         </div>
                         <p className="text-sm text-on-surface mt-1">{log.details}</p>
                         <div className="flex justify-between items-center mt-2 text-xs text-on-surface-variant">
                            <span>Actor: {log.actorName}</span>
                            <span>Setor: {log.sector}</span>
                         </div>
                      </div>
                   ))}
                </div>
             )}
          </Card>
          <p className="text-center text-xs text-on-surface-variant">Exibindo os últimos 50 registros</p>
       </div>
    );
  };

  const tabs = [
    { Icon: LayoutDashboard, label: 'Dash' },
    { Icon: BoxIcon, label: 'Modelos' },
    { Icon: Users, label: 'Func.' },
    { Icon: DollarSign, label: 'Pag.' },
    { Icon: FileSearch, label: 'Audit.' }, // Changed Icon to FileSearch for Audit
    { Icon: Settings, label: 'Config' },
    { Icon: History, label: 'Atual.' }, // Moved Updates to end
  ];

  return (
    <div className="h-screen flex flex-col bg-background">
      <div className="bg-surface p-4 shadow-sm z-10 flex justify-between items-center px-6 border-b border-outline-variant">
         <h1 className="text-xl font-medium text-on-surface">Painel Supervisor</h1>
         <div className="w-8 h-8 bg-primary-container rounded-full flex items-center justify-center text-on-primary-container font-bold text-xs">SV</div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 pb-24">
        {activeTab === 0 && <DashboardTab />}
        {activeTab === 1 && <ModelsTab />}
        {activeTab === 2 && <EmployeesTab />}
        {activeTab === 3 && <PaymentsTab />}
        {activeTab === 4 && <AuditTab />}
        {activeTab === 5 && <ConfigTab />}
        {activeTab === 6 && <UpdatesTab />}
      </div>

      <div className="bg-surface border-t border-outline-variant flex justify-around p-2 pb-6 shadow-md z-20 overflow-x-auto">
        {tabs.map((tab, idx) => {
          const isActive = activeTab === idx;
          return (
            <button 
              key={idx}
              onClick={() => setActiveTab(idx)}
              className="flex flex-col items-center justify-center min-w-[60px] gap-1 group"
            >
              <div className={`px-5 py-1.5 rounded-full transition-all duration-300 ${isActive ? 'bg-primary-container' : 'bg-transparent group-hover:bg-surface-variant'}`}>
                <tab.Icon size={20} className={`transition-colors ${isActive ? 'text-on-primary-container' : 'text-on-surface-variant'}`} />
              </div>
              <span className={`text-[10px] font-medium transition-colors ${isActive ? 'text-on-surface' : 'text-on-surface-variant'}`}>
                {tab.label}
              </span>
            </button>
          )
        })}
      </div>
    </div>
  );
};

export default SupervisorDashboard;

export enum Sector {
  PRODUCTION = 'Produção',
  FINISHING = 'Acabamento',
  PAINTING = 'Pintura',
  SUPERVISOR = 'Supervisor',
}

export enum VaseType {
  WITH_SHELL = 'Com Casca',
  WITHOUT_SHELL = 'Sem Casca',
}

export enum ItemStatus {
  DRAFT = 'Rascunho', // Local UI state mostly, but good to have
  PRODUCED = 'Produzido',
  STOCK_NO_SHELL = 'Estoque (Sem Casca)',
  AWAITING_FINISHING = 'Aguardando Acabamento',
  AWAITING_PAINTING = 'Aguardando Pintura',
  FINISHED = 'Finalizado',
}

export interface VaseModel {
  id: string;
  name: string;
  type: VaseType;
  weightKg: number; // New field for raw material calculation
  costProduction: number; // Labor cost for molding
  costFinishing?: number; // Only With Shell
  priceSale?: number; // Only With Shell
  // Commission is calculated dynamically (10% of sale price)
}

export interface Employee {
  id: string;
  name: string;
  sector: Sector | 'General';
  active: boolean;
}

export interface PaymentRecord {
  id: string;
  employeeId: string;
  employeeName: string;
  sector: Sector | 'General';
  amount: number;
  date: number; // Timestamp
  observation?: string;
}

export interface ProductionItem {
  id: string;
  modelId: string;
  modelName: string; // Denormalized for easier display if model is deleted
  type: VaseType;
  status: ItemStatus;
  createdAt: number; // Timestamp
  updatedAt: number; // Timestamp

  // Worker Tracking
  producedBy: string; // Employee ID
  finishedBy?: string; // Employee ID
  paintedBy?: string; // Employee ID

  // Value Tracking (Frozen at moment of execution)
  productionValue: number; // How much the producer earned (Labor)
  rawMaterialCost: number; // Cost of raw material (weight * rate) at time of production
  finishingValue?: number; // How much the finisher earned
  paintingValue?: number;  // How much the painter earned
}

// --- LOGGING & AUDIT SYSTEM ---
export type AuditAction = 'PRODUCTION' | 'FINISHING' | 'PAINTING' | 'PAYMENT' | 'ADMIN_UPDATE' | 'GOAL_UPDATE';

export interface SystemLog {
  id: string;
  timestamp: number;
  action: AuditAction;
  sector: Sector | 'System';
  actorId: string; // ID of the user performing the action
  actorName: string;
  targetId?: string; // ID of the employee affected (e.g. receiving payment)
  details: string; // Human readable summary
  value?: number; // Financial value involved
}

// --- DRAFT SYSTEM TYPES ---
export type DraftType = 'PRODUCTION' | 'FINISHING' | 'PAINTING';

export interface DraftItemContent {
  modelId: string;
  quantity: number;
}

export interface Draft {
  id: string;
  type: DraftType;
  sector: Sector;
  userId: string;
  selectedDate: number; // The date selected by the user
  createdAt: number; // System timestamp

  // Data payload depends on type
  // Production: list of models and quantities
  productionData?: DraftItemContent[]; 

  // Processing: list of existing ProductionItem IDs
  processingIds?: string[]; 
}

// --- GOALS SYSTEM TYPES ---
export type GoalPeriod = 'DAILY' | 'WEEKLY' | 'MONTHLY';

export interface GoalModelTarget {
  modelId: string;
  targetQuantity: number;
}

export interface Goal {
  id: string;
  employeeId: string;
  sector: Sector;
  period: GoalPeriod;
  startDate: number; // Timestamp start of validity
  endDate: number;   // Timestamp end of validity

  totalQuantityTarget: number; // General quantity target
  modelTargets?: GoalModelTarget[]; // Specific targets

  createdAt: number;
  createdBy: string; // Supervisor ID
}

// --- VERSION CONTROL TYPES ---
export type ChangeType = 'FIX' | 'FEATURE' | 'IMPROVEMENT' | 'MAJOR';

export interface ChangelogEntry {
  version: string;
  date: number; // Timestamp
  type: ChangeType;
  description: string;
}

export interface AppState {
  isDarkMode: boolean;
  supervisorPassword: string; // In real app, hash this.
  currentUser: Employee | null;
  currentSector: Sector | null;

  // System Versioning
  systemVersion: string;
  changelog: ChangelogEntry[];

  // Configs
  rawMaterialCostPerKg: number; // Default 0.26

  employees: Employee[];
  vaseModels: VaseModel[];
  productionItems: ProductionItem[];
  payments: PaymentRecord[];
  drafts: Draft[]; 
  systemLogs: SystemLog[];
  goals: Goal[]; // New Goals State

  // Actions
  toggleTheme: () => void;
  setSector: (sector: Sector | null) => void;
  loginUser: (user: Employee) => void;
  logout: () => void;

  // Core Actions
  addProductionItems: (items: ProductionItem[]) => void;
  processStageItems: (itemIds: string[], workerId: string, stage: 'finishing' | 'painting', timestamp: number) => void;

  // Draft Actions
  addDraft: (draft: Draft) => void;
  removeDraft: (id: string) => void;
  confirmDraft: (draftId: string) => void;

  // Goal Actions
  addGoal: (goal: Goal) => void;
  deleteGoal: (id: string) => void;

  // Supervisor Actions
  updateSupervisorPassword: (pass: string) => void;
  updateRawMaterialCostPerKg: (value: number) => void;
  addVaseModel: (model: VaseModel) => void;
  updateVaseModel: (model: VaseModel) => void;
  deleteVaseModel: (id: string) => void;
  addEmployee: (emp: Employee) => void;
  updateEmployee: (emp: Employee) => void;
  addPayment: (payment: PaymentRecord) => void;
  resetData: () => void;

  // Version Control Actions
  registerSystemUpdate: (type: ChangeType, description: string) => void;
}

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { AppState, ItemStatus, Sector, VaseType, ProductionItem, ChangelogEntry, ChangeType, SystemLog, Goal } from './types';
import { INITIAL_EMPLOYEES, INITIAL_VASES, DEFAULT_SUPERVISOR_PASS } from './constants';
import { v4 as uuidv4 } from 'uuid';

// Initial Version Seed - Set to 1.6.0 for Goals Feature
const INITIAL_VERSION = '1.6.0';

export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDarkMode: false,
      supervisorPassword: DEFAULT_SUPERVISOR_PASS,
      currentUser: null,
      currentSector: null,

      // Versioning Defaults
      systemVersion: INITIAL_VERSION,
      changelog: [],

      rawMaterialCostPerKg: 0.26, // Default per requirement

      employees: INITIAL_EMPLOYEES,
      vaseModels: INITIAL_VASES,
      productionItems: [],
      payments: [],
      drafts: [],
      systemLogs: [],
      goals: [],

      toggleTheme: () => set((state) => ({ isDarkMode: !state.isDarkMode })),

      setSector: (sector) => set({ currentSector: sector }),

      loginUser: (user) => set({ currentUser: user }),

      logout: () => set({ currentUser: null, currentSector: null }),

      addProductionItems: (items) => set((state) => {
        // Hydrate items with current production costs from models
        const hydratedItems = items.map(item => {
          const model = state.vaseModels.find(v => v.id === item.modelId);
          return {
            ...item,
            productionValue: model ? model.costProduction : 0,
            // Calculate Raw Material Cost Snapshot: Weight * Current Rate
            rawMaterialCost: model ? (model.weightKg * state.rawMaterialCostPerKg) : 0
          };
        });

        // AUDIT LOG GENERATION
        const currentUser = state.currentUser;
        const totalValue = hydratedItems.reduce((acc, i) => acc + i.productionValue, 0);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PRODUCTION',
          sector: Sector.PRODUCTION,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: hydratedItems[0]?.producedBy,
          details: `Registro de produção: ${hydratedItems.length} itens.`,
          value: totalValue
        };

        return { 
          productionItems: [...state.productionItems, ...hydratedItems],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      processStageItems: (itemIds, workerId, stage, timestamp) => set((state) => {
        // Use the passed timestamp instead of Date.now()
        let totalProcessedValue = 0;

        const updatedItems = state.productionItems.map((item) => {
          if (itemIds.includes(item.id)) {
            const model = state.vaseModels.find(v => v.id === item.modelId);

            if (stage === 'finishing') {
              const val = model?.costFinishing || 0;
              totalProcessedValue += val;
              return {
                ...item,
                status: ItemStatus.AWAITING_PAINTING,
                updatedAt: timestamp,
                finishedBy: workerId,
                finishingValue: val
              };
            }

            if (stage === 'painting') {
               // Calculate 10% commission
               const salePrice = model?.priceSale || 0;
               const commission = salePrice * 0.10;
               totalProcessedValue += commission;

               return {
                ...item,
                status: ItemStatus.FINISHED,
                updatedAt: timestamp,
                paintedBy: workerId,
                paintingValue: commission
              };
            }
          }
          return item;
        });

        // AUDIT LOG GENERATION
        const currentUser = state.currentUser;
        const actionType = stage === 'finishing' ? 'FINISHING' : 'PAINTING';
        const sector = stage === 'finishing' ? Sector.FINISHING : Sector.PAINTING;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: actionType,
          sector: sector,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: workerId,
          details: `Processamento de ${itemIds.length} itens no setor ${sector}.`,
          value: totalProcessedValue
        };

        return { 
          productionItems: updatedItems,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- DRAFT ACTIONS ---

      addDraft: (draft) => set((state) => ({ drafts: [draft, ...state.drafts] })),

      removeDraft: (id) => set((state) => ({ drafts: state.drafts.filter(d => d.id !== id) })),

      confirmDraft: (draftId) => {
        const state = get();
        const draft = state.drafts.find(d => d.id === draftId);
        if (!draft) return;

        // Logic based on Draft Type
        if (draft.type === 'PRODUCTION' && draft.productionData) {
          const newItems: ProductionItem[] = [];

          draft.productionData.forEach(({ modelId, quantity }) => {
            const model = state.vaseModels.find(v => v.id === modelId);
            if (model) {
               for (let i = 0; i < quantity; i++) {
                newItems.push({
                  id: uuidv4(),
                  modelId: model.id,
                  modelName: model.name,
                  type: model.type,
                  status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
                  createdAt: draft.selectedDate, // Use Draft Date
                  updatedAt: draft.selectedDate, // Use Draft Date
                  producedBy: draft.userId,
                  productionValue: 0, // Placeholder, calculated in addProductionItems
                  rawMaterialCost: 0 // Placeholder
                });
               }
            }
          });

          if (newItems.length > 0) {
            get().addProductionItems(newItems);
          }
        } else if ((draft.type === 'FINISHING' || draft.type === 'PAINTING') && draft.processingIds) {
           const stage = draft.type === 'FINISHING' ? 'finishing' : 'painting';
           get().processStageItems(draft.processingIds, draft.userId, stage, draft.selectedDate);
        }

        // Remove draft after processing
        get().removeDraft(draftId);
      },

      // --- GOALS ACTIONS ---

      addGoal: (goal) => set((state) => {
        // Log the creation
        const currentUser = state.currentUser;
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal.employeeId,
          details: `Meta ${goal.period} definida: ${goal.totalQuantityTarget} un. (${new Date(goal.startDate).toLocaleDateString()} - ${new Date(goal.endDate).toLocaleDateString()})`,
        };

        // Replace any existing goal for the same employee, sector, and period overlap? 
        // For simplicity, we just add it. The UI filters active ones.
        return {
          goals: [...state.goals, goal],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      deleteGoal: (id) => set((state) => {
        const goal = state.goals.find(g => g.id === id);
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal?.employeeId,
          details: `Meta removida.`,
        };

        return {
          goals: state.goals.filter(g => g.id !== id),
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- SUPERVISOR ACTIONS ---

      updateSupervisorPassword: (pass) => set({ supervisorPassword: pass }),

      updateRawMaterialCostPerKg: (value) => set({ rawMaterialCostPerKg: value }),

      addVaseModel: (model) => set((state) => ({ vaseModels: [...state.vaseModels, model] })),

      updateVaseModel: (model) => set((state) => ({
        vaseModels: state.vaseModels.map((v) => (v.id === model.id ? model : v))
      })),

      deleteVaseModel: (id) => set((state) => ({
        vaseModels: state.vaseModels.filter((v) => v.id !== id)
      })),

      addEmployee: (emp) => set((state) => ({ employees: [...state.employees, emp] })),

      updateEmployee: (emp) => set((state) => ({
        employees: state.employees.map((e) => (e.id === emp.id ? emp : e))
      })),

      addPayment: (payment) => set((state) => {
        // AUDIT LOG GENERATION
        const currentUser = state.currentUser;
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PAYMENT',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: payment.employeeId,
          details: `Pagamento registrado para ${payment.employeeName}. Obs: ${payment.observation || '-'}`,
          value: payment.amount
        };

        return { 
          payments: [payment, ...state.payments],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      resetData: () => set({
        productionItems: [],
        payments: [],
        employees: INITIAL_EMPLOYEES,
        vaseModels: INITIAL_VASES,
        supervisorPassword: DEFAULT_SUPERVISOR_PASS,
        rawMaterialCostPerKg: 0.26,
        drafts: [],
        systemLogs: [],
        goals: [],
        // Reset version info
        systemVersion: INITIAL_VERSION,
        changelog: []
      }),

      // --- VERSION CONTROL ACTIONS ---
      registerSystemUpdate: (type: ChangeType, description: string) => set((state) => {
        // 1. Parse current version
        const parts = state.systemVersion.split('.').map(Number);
        if (parts.length !== 3) return state; // Safety check

        let [major, minor, patch] = parts;

        // 2. Increment based on type
        switch (type) {
          case 'MAJOR':
            major++;
            minor = 0;
            patch = 0;
            break;
          case 'FEATURE':
            minor++;
            patch = 0;
            break;
          case 'IMPROVEMENT':
          case 'FIX':
            patch++;
            break;
        }

        const newVersion = `${major}.${minor}.${patch}`;

        // 3. Create new Entry
        const newEntry: ChangelogEntry = {
          version: newVersion,
          date: Date.now(),
          type,
          description
        };

        // 4. Check for duplication based on description to avoid spamming on re-renders
        if (state.changelog.length > 0 && state.changelog[0].description === description) {
           return state;
        }

        return {
          systemVersion: newVersion,
          changelog: [newEntry, ...state.changelog]
        };
      })

    }),
    {
      name: 'home-pots-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

import React, { useEffect, useRef } from 'react';
import { useStore } from './store';
import { Sector } from './types';
import LoginScreen from './screens/LoginScreen';
import ProductionScreen from './screens/ProductionScreen';
import ProcessingScreen from './screens/ProcessingScreen';
import SupervisorDashboard from './screens/SupervisorDashboard';
import InstallPWA from './components/InstallPWA';

const App: React.FC = () => {
  const { isDarkMode, currentUser, currentSector, registerSystemUpdate, systemVersion } = useStore();
  const initRef = useRef(false);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  // AUTOMATIC VERSION CONTROL TRIGGER
  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;

    // Trigger update to 1.5.0 (Feature Update) - Previous trigger
    if (systemVersion === '1.4.1') {
       registerSystemUpdate('FEATURE', 'Revisão geral da interface para eliminar sobreposição de elementos e ajuste do fluxo de registro de produção para telas dedicadas.');
    }

    // Trigger update to 1.5.1 (Fix Update) - Critical Fix for Painting Sector and Logs
    if (systemVersion === '1.5.0') {
      registerSystemUpdate('FIX', 'Correção de inconsistência no setor de pintura, garantindo sincronização entre produção, histórico, financeiro e implementação obrigatória de logs para todas as operações.');
    }

    // Trigger update to 1.6.0 (New Feature) - Goals System
    if (systemVersion === '1.5.1') {
      registerSystemUpdate('FEATURE', 'Implementação do sistema de metas produtivas com barra progressiva no painel dos funcionários, tela dedicada de metas, gestão centralizada pelo supervisor e integração automática com produção por setor e por modelo de vaso.');
    }
  }, [systemVersion, registerSystemUpdate]);

  // Routing Logic based on State (Auth Guard)
  const renderScreen = () => {
    if (!currentUser || !currentSector) {
      return <LoginScreen />;
    }

    switch (currentSector) {
      case Sector.PRODUCTION:
        return <ProductionScreen />;
      case Sector.FINISHING:
        return <ProcessingScreen stage="finishing" />;
      case Sector.PAINTING:
        return <ProcessingScreen stage="painting" />;
      case Sector.SUPERVISOR:
        return <SupervisorDashboard />;
      default:
        return <LoginScreen />;
    }
  };

  return (
    <div className="min-h-screen bg-background text-on-background transition-colors duration-200">
      {renderScreen()}
      <InstallPWA />
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { Target, Trophy, Calendar, ChevronRight, BarChart3, AlertCircle } from 'lucide-react';
