      { name: 'Mão de Obra', value: financials.laborProduction, fill: '#0061a4' },
      { name: 'Acabamento', value: financials.laborFinishing, fill: '#6b5e0f' },
      { name: 'Pintura', value: financials.laborPainting, fill: '#9a4058' },
    ];

    const prodData = [
      { name: 'Produzidos', qtd: operational.produced },
      { name: 'Acabados', qtd: operational.finished },
