const INITIAL_VERSION = '1.6.1';

// Pre-populated history for fresh installs - FULL HISTORY KEPT
const INITIAL_CHANGELOG: ChangelogEntry[] = [
  {
    version: '1.6.1',
    date: Date.now(),
    type: 'FIX',
    description: 'Ajuste de layout na tela de login: Correção de sobreposição entre o painel de avisos e o rodapé de versão.'
  },
  {
    version: '1.6.0',
    date: Date.now() - 86400000, // 1 day ago
    type: 'FEATURE',
    description: 'Implementação do sistema de metas produtivas com barra progressiva no painel dos funcionários, tela dedicada de metas, gestão centralizada pelo supervisor e integração automática com produção por setor e por modelo de vaso.'
