export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDarkMode: false,
      supervisorPassword: DEFAULT_SUPERVISOR_PASS,
      currentUser: null,
      currentSector: null,

      // Versioning Defaults
      systemVersion: INITIAL_VERSION,
      changelog: INITIAL_CHANGELOG,

      rawMaterialCostPerKg: 0.26, // Default per requirement

      employees: INITIAL_EMPLOYEES,
      vaseModels: INITIAL_VASES,
      productionItems: [],
      payments: [],
      drafts: [],
      systemLogs: [],
      goals: [],

      toggleTheme: () => set((state) => ({ isDarkMode: !state.isDarkMode })),

      setSector: (sector) => set({ currentSector: sector }),

      loginUser: (user) => set({ currentUser: user }),

      logout: () => set({ currentUser: null, currentSector: null }),

      addProductionItems: (items) => set((state) => {
        // Hydrate items with current production costs from models
        const hydratedItems = items.map(item => {
          const model = state.vaseModels.find(v => v.id === item.modelId);
          return {
            ...item,
            productionValue: model ? model.costProduction : 0,
            // Calculate Raw Material Cost Snapshot: Weight * Current Rate
            rawMaterialCost: model ? (model.weightKg * state.rawMaterialCostPerKg) : 0
          };
        });

        // AUDIT LOG GENERATION
        const currentUser = state.currentUser;
        const totalValue = hydratedItems.reduce((acc, i) => acc + i.productionValue, 0);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PRODUCTION',
          sector: Sector.PRODUCTION,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: hydratedItems[0]?.producedBy,
          details: `Registro de produção: ${hydratedItems.length} itens.`,
          value: totalValue
        };

        return { 
          productionItems: [...state.productionItems, ...hydratedItems],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      processStageItems: (itemIds, workerId, stage, timestamp) => set((state) => {
        // Use the passed timestamp instead of Date.now()
        let totalProcessedValue = 0;

        const updatedItems = state.productionItems.map((item) => {
          if (itemIds.includes(item.id)) {
            const model = state.vaseModels.find(v => v.id === item.modelId);

            if (stage === 'finishing') {
              const val = model?.costFinishing || 0;
              totalProcessedValue += val;
              return {
                ...item,
                status: ItemStatus.AWAITING_PAINTING,
                updatedAt: timestamp,
                finishedBy: workerId,
                finishingValue: val
              };
            }

            if (stage === 'painting') {
               // Calculate 10% commission
               const salePrice = model?.priceSale || 0;
               const commission = salePrice * 0.10;
               totalProcessedValue += commission;

               return {
                ...item,
                status: ItemStatus.FINISHED,
                updatedAt: timestamp,
                paintedBy: workerId,
                paintingValue: commission
              };
            }
          }
          return item;
        });

        // AUDIT LOG GENERATION
        const currentUser = state.currentUser;
        const actionType = stage === 'finishing' ? 'FINISHING' : 'PAINTING';
        const sector = stage === 'finishing' ? Sector.FINISHING : Sector.PAINTING;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: actionType,
          sector: sector,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: workerId,
          details: `Processamento de ${itemIds.length} itens no setor ${sector}.`,
          value: totalProcessedValue
        };

        return { 
          productionItems: updatedItems,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- DRAFT ACTIONS ---

      addDraft: (draft) => set((state) => ({ drafts: [draft, ...state.drafts] })),

      removeDraft: (id) => set((state) => ({ drafts: state.drafts.filter(d => d.id !== id) })),

      confirmDraft: (draftId) => {
        const state = get();
        const draft = state.drafts.find(d => d.id === draftId);
        if (!draft) return;

        // Logic based on Draft Type
        if (draft.type === 'PRODUCTION' && draft.productionData) {
          const newItems: ProductionItem[] = [];

          draft.productionData.forEach(({ modelId, quantity }) => {
            const model = state.vaseModels.find(v => v.id === modelId);
            if (model) {
               for (let i = 0; i < quantity; i++) {
                newItems.push({
                  id: uuidv4(),
                  modelId: model.id,
                  modelName: model.name,
                  type: model.type,
                  status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
                  createdAt: draft.selectedDate, // Use Draft Date
                  updatedAt: draft.selectedDate, // Use Draft Date
                  producedBy: draft.userId,
                  productionValue: 0, // Placeholder, calculated in addProductionItems
                  rawMaterialCost: 0 // Placeholder
                });
               }
            }
          });

          if (newItems.length > 0) {
            get().addProductionItems(newItems);
          }
        } else if ((draft.type === 'FINISHING' || draft.type === 'PAINTING') && draft.processingIds) {
           const stage = draft.type === 'FINISHING' ? 'finishing' : 'painting';
           get().processStageItems(draft.processingIds, draft.userId, stage, draft.selectedDate);
        }

        // Remove draft after processing
        get().removeDraft(draftId);
      },

      // --- GOALS ACTIONS ---

      addGoal: (goal) => set((state) => {
        // Log the creation
        const currentUser = state.currentUser;
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal.employeeId,
          details: `Meta ${goal.period} definida: ${goal.totalQuantityTarget} un. (${new Date(goal.startDate).toLocaleDateString()} - ${new Date(goal.endDate).toLocaleDateString()})`,
        };

        return {
          goals: [...state.goals, goal],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      deleteGoal: (id) => set((state) => {
        const goal = state.goals.find(g => g.id === id);
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal?.employeeId,
          details: `Meta removida.`,
        };

        return {
          goals: state.goals.filter(g => g.id !== id),
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- SUPERVISOR ACTIONS ---

      updateSupervisorPassword: (pass) => set({ supervisorPassword: pass }),

      updateRawMaterialCostPerKg: (value) => set({ rawMaterialCostPerKg: value }),

      addVaseModel: (model) => set((state) => ({ vaseModels: [...state.vaseModels, model] })),

      updateVaseModel: (model) => set((state) => ({
        vaseModels: state.vaseModels.map((v) => (v.id === model.id ? model : v))
      })),

      deleteVaseModel: (id) => set((state) => ({
        vaseModels: state.vaseModels.filter((v) => v.id !== id)
      })),

      addEmployee: (emp) => set((state) => ({ employees: [...state.employees, emp] })),

      updateEmployee: (emp) => set((state) => ({
        employees: state.employees.map((e) => (e.id === emp.id ? emp : e))
      })),

      addPayment: (payment) => set((state) => {
        // AUDIT LOG GENERATION
        const currentUser = state.currentUser;
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PAYMENT',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: payment.employeeId,
          details: `Pagamento registrado para ${payment.employeeName}. Obs: ${payment.observation || '-'}`,
          value: payment.amount
        };

        return { 
          payments: [payment, ...state.payments],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      resetData: () => set({
        productionItems: [],
        payments: [],
        employees: INITIAL_EMPLOYEES,
        vaseModels: INITIAL_VASES,
        supervisorPassword: DEFAULT_SUPERVISOR_PASS,
        rawMaterialCostPerKg: 0.26,
        drafts: [],
        systemLogs: [],
        goals: [],
        // Reset version info but keep seed data
        systemVersion: INITIAL_VERSION,
        changelog: INITIAL_CHANGELOG
      }),

      // --- VERSION CONTROL ACTIONS ---
      registerSystemUpdate: (type: ChangeType, description: string) => set((state) => {
        // 1. Parse current version
        const parts = state.systemVersion.split('.').map(Number);
        if (parts.length !== 3) return state; // Safety check

        let [major, minor, patch] = parts;

        // 2. Increment based on type
        switch (type) {
          case 'MAJOR':
            major++;
            minor = 0;
            patch = 0;
            break;
          case 'FEATURE':
            minor++;
            patch = 0;
            break;
          case 'IMPROVEMENT':
          case 'FIX':
            patch++;
            break;
        }

        const newVersion = `${major}.${minor}.${patch}`;

        // 3. Create new Entry
        const newEntry: ChangelogEntry = {
          version: newVersion,
          date: Date.now(),
          type,
          description
        };

        // 4. Check for duplication based on description to avoid spamming on re-renders
        if (state.changelog.length > 0 && state.changelog[0].description === description) {
           return state;
        }

        return {
          systemVersion: newVersion,
          changelog: [newEntry, ...state.changelog]
        };
      })

    }),
    {
      name: 'home-pots-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

import React, { useEffect, useRef } from 'react';
import { useStore } from './store';
import { Sector } from './types';
import LoginScreen from './screens/LoginScreen';
import ProductionScreen from './screens/ProductionScreen';
import ProcessingScreen from './screens/ProcessingScreen';
import SupervisorDashboard from './screens/SupervisorDashboard';
import InstallPWA from './components/InstallPWA';

const App: React.FC = () => {
  const { isDarkMode, currentUser, currentSector, registerSystemUpdate, systemVersion } = useStore();
  const initRef = useRef(false);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  // AUTOMATIC VERSION CONTROL TRIGGER
  useEffect(() => {
    if (initRef.current) return;
    initRef.current = true;

    // Trigger update to 1.5.0 (Feature Update) - Previous trigger
    if (systemVersion === '1.4.1') {
       registerSystemUpdate('FEATURE', 'Revisão geral da interface para eliminar sobreposição de elementos e ajuste do fluxo de registro de produção para telas dedicadas.');
    }

    // Trigger update to 1.5.1 (Fix Update) - Critical Fix for Painting Sector and Logs
    if (systemVersion === '1.5.0') {
      registerSystemUpdate('FIX', 'Correção de inconsistência no setor de pintura, garantindo sincronização entre produção, histórico, financeiro e implementação obrigatória de logs para todas as operações.');
    }

    // Trigger update to 1.6.0 (New Feature) - Goals System
    if (systemVersion === '1.5.1') {
      registerSystemUpdate('FEATURE', 'Implementação do sistema de metas produtivas com barra progressiva no painel dos funcionários, tela dedicada de metas, gestão centralizada pelo supervisor e integração automática com produção por setor e por modelo de vaso.');
    }

    // Trigger update to 1.6.1 (UI Fix) - Login Screen Layout
    if (systemVersion === '1.6.0') {
      registerSystemUpdate('FIX', 'Ajuste de layout na tela de login: Correção de sobreposição entre o painel de avisos e o rodapé de versão.');
    }
  }, [systemVersion, registerSystemUpdate]);

  // Routing Logic based on State (Auth Guard)
  const renderScreen = () => {
    if (!currentUser || !currentSector) {
      return <LoginScreen />;
    }

    switch (currentSector) {
      case Sector.PRODUCTION:
        return <ProductionScreen />;
      case Sector.FINISHING:
        return <ProcessingScreen stage="finishing" />;
      case Sector.PAINTING:
        return <ProcessingScreen stage="painting" />;
      case Sector.SUPERVISOR:
        return <SupervisorDashboard />;
      default:
        return <LoginScreen />;
    }
  };

  return (
    <div className="min-h-screen bg-background text-on-background transition-colors duration-200">
      {renderScreen()}
      <InstallPWA />
    </div>
  );
};

