                   <Info className="w-5 h-5" />
                </div>
                <div>
                   <h3 className="text-sm font-bold text-on-surface mb-1">Informações da Fábrica</h3>
                   <p className="text-xs text-on-surface-variant leading-relaxed">
                      Esta área será usada para avisos, comunicados e informações importantes.
                   </p>
                </div>
             </div>
          </div>
        </div>

        {/* Version Footer */}
        <div className="absolute bottom-4 flex flex-col items-center gap-1">
          <p className="text-xs font-medium text-on-surface-variant opacity-70">
            Versão {systemVersion}
          </p>
          <button onClick={() => setShowChangelog(true)} className="text-[10px] text-primary hover:underline font-medium">
             Ver novidades
          </button>
        </div>

        {/* Changelog Modal */}
        <Modal 
          isOpen={showChangelog} 
          onClose={() => setShowChangelog(false)} 
          title="Novidades do Sistema"
          footer={<Button variant="ghost" onClick={() => setShowChangelog(false)}>Fechar</Button>}
        >
           <div className="space-y-4">
              {changelog.length === 0 ? (
                <p className="text-on-surface-variant text-center py-4">Nenhum histórico registrado.</p>
              ) : (
                changelog.map((entry, idx) => {
                   const config = getTypeConfig(entry.type);
                   return (
                     <div key={idx} className="border-b border-outline-variant pb-4 last:border-0 last:pb-0">
                        <div className="flex justify-between items-start mb-1">
                           <div className="flex items-center gap-2">
                             <span className="font-bold text-lg text-on-surface">v{entry.version}</span>
                             <span className={`flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] uppercase font-bold ${config.color}`}>
                                {config.icon} {config.label}
                             </span>
                           </div>
                           <span className="text-xs text-on-surface-variant">{new Date(entry.date).toLocaleDateString()}</span>
                        </div>
                        <p className="text-sm text-on-surface-variant leading-relaxed">
                          {entry.description}
                        </p>
                     </div>
                   );
                })
              )}
           </div>
        </Modal>
      </div>
    );
  }

  // Step 2 & 3: Profile & Auth
  const sectorEmployees = employees.filter(e => e.sector === selectedSector || (selectedSector === Sector.SUPERVISOR && e.sector === Sector.SUPERVISOR));

  return (
    <div className="min-h-screen bg-background flex items-center justify-center p-4 relative">
      <div className="w-full max-w-md">
        <div className="mb-6">
          <Button variant="ghost" size="sm" onClick={() => { setSelectedSector(null); setSelectedUser(null); setError(''); }}>
            <ArrowLeft className="mr-2 h-5 w-5" /> Voltar
          </Button>
        </div>

        <h2 className="text-3xl font-normal text-on-background mb-2">Identificação</h2>
        <p className="text-on-surface-variant mb-8">Quem é você em <span className="font-bold text-primary">{selectedSector}</span>?</p>

        {!selectedUser ? (
          <div className="space-y-3">
            {sectorEmployees.map(emp => (
              <div 
                key={emp.id}
                onClick={() => handleUserSelect(emp)}
                className="bg-surface p-4 rounded-2xl shadow-sm border border-outline-variant flex items-center cursor-pointer hover:bg-surface-variant active:scale-[0.98] transition-all"
              >
                <div className="w-12 h-12 bg-primary-container rounded-full flex items-center justify-center text-on-primary-container mr-4">
                  <User className="h-6 w-6" />
                </div>
                <span className="text-lg font-medium text-on-surface">{emp.name}</span>
              </div>
            ))}
            {sectorEmployees.length === 0 && (
              <div className="text-center py-10 bg-surface rounded-2xl border border-outline-variant">
                <p className="text-on-surface-variant">Nenhum funcionário encontrado.</p>
              </div>
            )}
          </div>
        ) : (
          <Card className="flex flex-col gap-6 p-8 bg-surface border border-outline-variant shadow-lg">
            <div className="flex flex-col items-center mb-2">
               <div className="w-20 h-20 bg-primary-container rounded-full flex items-center justify-center text-on-primary-container mb-4">
                 <ShieldCheck className="w-10 h-10" />
               </div>
               <h3 className="text-2xl font-bold text-on-surface">{selectedUser.name}</h3>
               <p className="text-on-surface-variant">Acesso Supervisor</p>
            </div>

            <div>
              <div className="relative">
                <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-on-surface-variant" />
                <input 
                  type="password"
                  className="w-full pl-12 pr-4 py-4 bg-surface border border-outline-variant rounded-xl focus:ring-2 focus:ring-primary focus:outline-none transition-all text-lg text-on-surface placeholder-on-surface-variant"
                  value={inputPassword}
                  onChange={(e) => { setInputPassword(e.target.value); setError(''); }}
                  placeholder="Senha de acesso"
                />
              </div>
              {error && <p className="text-error text-sm mt-2 ml-1">{error}</p>}
            </div>

            <Button size="lg" onClick={handleSupervisorLogin} className="w-full">
              Entrar no Painel
            </Button>

            <Button variant="ghost" onClick={() => setSelectedUser(null)} className="w-full">
              Trocar Usuário
            </Button>
          </Card>
        )}
      </div>

      {/* Version Footer */}
      <div className="absolute bottom-4 flex flex-col items-center gap-1">
          <p className="text-xs font-medium text-on-surface-variant opacity-70">
            Versão {systemVersion}
          </p>
      </div>
    </div>
  );
};

export default LoginScreen;

export enum Sector {
  PRODUCTION = 'Produção',
  FINISHING = 'Acabamento',
  PAINTING = 'Pintura',
  SUPERVISOR = 'Supervisor',
}

export enum VaseType {
  WITH_SHELL = 'Com Casca',
  WITHOUT_SHELL = 'Sem Casca',
}

export enum ItemStatus {
  DRAFT = 'Rascunho', // Local UI state mostly, but good to have
  PRODUCED = 'Produzido',
  STOCK_NO_SHELL = 'Estoque (Sem Casca)',
  AWAITING_FINISHING = 'Aguardando Acabamento',
  AWAITING_PAINTING = 'Aguardando Pintura',
  FINISHED = 'Finalizado',
}

export interface VaseModel {
  id: string;
  name: string;
  type: VaseType;
  weightKg: number; // New field for raw material calculation
  costProduction: number; // Labor cost for molding
  costFinishing?: number; // Only With Shell
  priceSale?: number; // Only With Shell
  // Commission is calculated dynamically (10% of sale price)
}

export interface Employee {
  id: string;
  name: string;
  sector: Sector | 'General';
  active: boolean;
  joinedAt?: number; // Optional: When they were added
}

export interface PaymentRecord {
  id: string;
  employeeId: string;
  employeeName: string;
  sector: Sector | 'General';
  amount: number;
  date: number; // Timestamp
  observation?: string;
}

export interface ProductionItem {
  id: string;
  modelId: string;
  modelName: string; // Denormalized for easier display if model is deleted
  type: VaseType;
  status: ItemStatus;
  createdAt: number; // Timestamp
  updatedAt: number; // Timestamp

  // Worker Tracking
  producedBy: string; // Employee ID
  finishedBy?: string; // Employee ID
  paintedBy?: string; // Employee ID

  // Value Tracking (Frozen at moment of execution)
  productionValue: number; // How much the producer earned (Labor)
  rawMaterialCost: number; // Cost of raw material (weight * rate) at time of production
  finishingValue?: number; // How much the finisher earned
  paintingValue?: number;  // How much the painter earned
}

// --- USER PREFERENCES (NEW) ---
export interface UserPreferences {
  userId: string;
  darkMode: boolean;

  // Notification Toggles (UI Only for now)
  notifySystem: boolean;
  notifyGoals: boolean;
  notifyPayments: boolean;

  // Dashboard Visibility
  showFinancials: boolean;
  showProductionQty: boolean;
  showGoalsBar: boolean;
}

// --- LOGGING & AUDIT SYSTEM ---
export type AuditAction = 'PRODUCTION' | 'FINISHING' | 'PAINTING' | 'PAYMENT' | 'ADMIN_UPDATE' | 'GOAL_UPDATE' | 'SETTINGS_UPDATE' | 'LOGOUT';

export interface SystemLog {
  id: string;
  timestamp: number;
  action: AuditAction;
  sector: Sector | 'System';
  actorId: string; // ID of the user performing the action
  actorName: string;
  targetId?: string; // ID of the employee affected (e.g. receiving payment)
  details: string; // Human readable summary
  value?: number; // Financial value involved
}

// --- DRAFT SYSTEM TYPES ---
export type DraftType = 'PRODUCTION' | 'FINISHING' | 'PAINTING';

export interface DraftItemContent {
  modelId: string;
  quantity: number;
}

export interface Draft {
  id: string;
  type: DraftType;
  sector: Sector;
  userId: string;
  selectedDate: number; // The date selected by the user
  createdAt: number; // System timestamp

  // Data payload depends on type
  // Production: list of models and quantities
  productionData?: DraftItemContent[]; 

  // Processing: list of existing ProductionItem IDs
  processingIds?: string[]; 
}

// --- GOALS SYSTEM TYPES ---
export type GoalPeriod = 'DAILY' | 'WEEKLY' | 'MONTHLY';

export interface GoalModelTarget {
  modelId: string;
  targetQuantity: number;
}

export interface Goal {
  id: string;
  employeeId: string;
  sector: Sector;
  period: GoalPeriod;
  startDate: number; // Timestamp start of validity
  endDate: number;   // Timestamp end of validity

  totalQuantityTarget: number; // General quantity target
  modelTargets?: GoalModelTarget[]; // Specific targets

  createdAt: number;
  createdBy: string; // Supervisor ID
}

// --- VERSION CONTROL TYPES ---
export type ChangeType = 'FIX' | 'FEATURE' | 'IMPROVEMENT' | 'MAJOR';

export interface ChangelogEntry {
  version: string;
  date: number; // Timestamp
  type: ChangeType;
  description: string;
}

export interface AppState {
  isDarkMode: boolean;
  supervisorPassword: string; // In real app, hash this.
  currentUser: Employee | null;
  currentSector: Sector | null;

  // System Versioning
  systemVersion: string;
  changelog: ChangelogEntry[];

  // Configs
  rawMaterialCostPerKg: number; // Default 0.26

  employees: Employee[];
  vaseModels: VaseModel[];
  productionItems: ProductionItem[];
  payments: PaymentRecord[];
  drafts: Draft[]; 
  systemLogs: SystemLog[];
  goals: Goal[];
  userPreferences: Record<string, UserPreferences>; // Map userId -> Prefs

  // Actions
  toggleTheme: () => void; // Global toggle (deprecated for user action, used for supervisor)
  setSector: (sector: Sector | null) => void;
  loginUser: (user: Employee) => void;
  logout: () => void;

  // Core Actions
  addProductionItems: (items: ProductionItem[]) => void;
  processStageItems: (itemIds: string[], workerId: string, stage: 'finishing' | 'painting', timestamp: number) => void;

  // Draft Actions
  addDraft: (draft: Draft) => void;
  removeDraft: (id: string) => void;
  confirmDraft: (draftId: string) => void;

  // Goal Actions
  addGoal: (goal: Goal) => void;
  deleteGoal: (id: string) => void;

  // Settings Actions
  updateUserPreferences: (userId: string, prefs: Partial<UserPreferences>) => void;

  // Supervisor Actions
  updateSupervisorPassword: (pass: string) => void;
  updateRawMaterialCostPerKg: (value: number) => void;
  addVaseModel: (model: VaseModel) => void;
  updateVaseModel: (model: VaseModel) => void;
  deleteVaseModel: (id: string) => void;
  addEmployee: (emp: Employee) => void;
  updateEmployee: (emp: Employee) => void;
  addPayment: (payment: PaymentRecord) => void;
  resetData: () => void;

  // Version Control Actions
  registerSystemUpdate: (type: ChangeType, description: string) => void;
}

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { AppState, ItemStatus, Sector, VaseType, ProductionItem, ChangelogEntry, ChangeType, SystemLog, Goal, UserPreferences } from './types';
import { INITIAL_EMPLOYEES, INITIAL_VASES, DEFAULT_SUPERVISOR_PASS } from './constants';
import { v4 as uuidv4 } from 'uuid';

// Initial Version Seed - Set to 1.7.0 for User Settings Feature
const INITIAL_VERSION = '1.7.0';

// Pre-populated history for fresh installs - FULL HISTORY KEPT
