        <div className="bg-surface p-1 rounded-xl flex gap-1 border border-outline-variant">
           {(['today', 'week', 'month', 'all'] as const).map((r) => (
             <button
               key={r}
               onClick={() => setTimeRange(r)}
               className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                 timeRange === r 
                 ? 'bg-primary text-on-primary shadow-sm' 
                 : 'text-on-surface-variant hover:bg-surface-variant'
               }`}
             >
               {r === 'today' && 'Hoje'}
               {r === 'week' && '7 Dias'}
               {r === 'month' && '30 Dias'}
               {r === 'all' && 'Tudo'}
             </button>
           ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
         <Card className="md:col-span-2 lg:col-span-4 bg-primary text-on-primary border-none shadow-lg relative overflow-hidden">
            <div className="relative z-10 flex justify-between items-center">
               <div>
                  <p className="text-on-primary font-medium mb-1 flex items-center gap-2 opacity-90">
