// --- SUB-COMPONENTS DEFINED OUTSIDE TO PREVENT RE-RENDER FOCUS LOSS ---

const DashboardTab = () => {
  const { productionItems, rawMaterialCostPerKg, paintingCommissionPercentage } = useStore();
  const [timeRange, setTimeRange] = useState<'today' | 'week' | 'month' | 'all'>('month');

  const filteredItems = useMemo(() => {
    const now = new Date();
    let startTime = 0;

    if (timeRange === 'today') {
      startTime = new Date(now.setHours(0,0,0,0)).getTime();
    } else if (timeRange === 'week') {
      const d = new Date();
      d.setDate(d.getDate() - 7);
      startTime = d.setHours(0,0,0,0);
    } else if (timeRange === 'month') {
      const d = new Date();
      d.setDate(d.getDate() - 30);
      startTime = d.setHours(0,0,0,0);
    }

    return productionItems.filter(item => item.createdAt >= startTime);
  }, [productionItems, timeRange]);

  const financials = useMemo(() => {
    let rawMaterial = 0;
    let laborProduction = 0;
    let laborFinishing = 0;
    let laborPainting = 0;

    filteredItems.forEach(item => {
      rawMaterial += (item.rawMaterialCost || 0);
      laborProduction += (item.productionValue || 0);
      laborFinishing += (item.finishingValue || 0);
      laborPainting += (item.paintingValue || 0);
    });

    return {
      rawMaterial,
      laborProduction,
      laborFinishing,
      laborPainting,
      total: rawMaterial + laborProduction + laborFinishing + laborPainting
    };
  }, [filteredItems]);

  const operational = useMemo(() => {
    const produced = filteredItems.length;
    const finished = filteredItems.filter(i => (i.finishingValue || 0) > 0 || i.status === ItemStatus.AWAITING_PAINTING || i.status === ItemStatus.FINISHED).length;
    const painted = filteredItems.filter(i => (i.paintingValue || 0) > 0 || i.status === ItemStatus.FINISHED).length;

    return { produced, finished, painted };
  }, [filteredItems]);

  const costData = [
    { name: 'Matéria-Prima', value: financials.rawMaterial, fill: '#535f70' },
    { name: 'Mão de Obra', value: financials.laborProduction, fill: '#0061a4' },
    { name: 'Acabamento', value: financials.laborFinishing, fill: '#6b5e0f' },
    { name: 'Pintura', value: financials.laborPainting, fill: '#9a4058' },
  ];

  const prodData = [
    { name: 'Produzidos', qtd: operational.produced },
    { name: 'Acabados', qtd: operational.finished },
    { name: 'Pintados', qtd: operational.painted },
  ];

  const formatCurrency = (val: number) => `R$ ${val.toFixed(2)}`;

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500 pb-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 px-1">
        <div>
          <h2 className="text-2xl font-normal text-on-background">Visão Geral</h2>
          <p className="text-sm text-on-surface-variant">Indicadores operacionais e financeiros</p>
        </div>
        <div className="bg-surface p-1 rounded-xl flex gap-1 border border-outline-variant">
           {(['today', 'week', 'month', 'all'] as const).map((r) => (
             <button
               key={r}
               onClick={() => setTimeRange(r)}
               className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                 timeRange === r 
                 ? 'bg-primary text-on-primary shadow-sm' 
                 : 'text-on-surface-variant hover:bg-surface-variant'
               }`}
             >
               {r === 'today' && 'Hoje'}
               {r === 'week' && '7 Dias'}
               {r === 'month' && '30 Dias'}
               {r === 'all' && 'Tudo'}
             </button>
           ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
         <Card className="md:col-span-2 lg:col-span-4 bg-primary text-on-primary border-none shadow-lg relative overflow-hidden">
            <div className="relative z-10 flex justify-between items-center">
               <div>
                  <p className="text-on-primary font-medium mb-1 flex items-center gap-2 opacity-90">
                     <TrendingUp className="w-4 h-4" /> Custo Total do Período
                  </p>
                  <p className="text-4xl font-bold">{formatCurrency(financials.total)}</p>
               </div>
               <div className="bg-primary-container p-3 rounded-full">
                  <DollarSign className="w-8 h-8 text-on-primary-container" />
               </div>
            </div>
            <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-primary-container rounded-full opacity-20"></div>
         </Card>

         <Card className="bg-surface border-outline-variant flex flex-col justify-between">
            <div className="flex justify-between items-start mb-4">
               <div className="bg-secondary-container p-2 rounded-lg text-on-secondary-container">
                  <Scale className="w-5 h-5" />
               </div>
               <span className="text-xs font-bold text-on-surface-variant bg-surface-variant px-2 py-1 rounded">Matéria-Prima</span>
            </div>
            <div>
               <p className="text-2xl font-bold text-on-surface">{formatCurrency(financials.rawMaterial)}</p>
               <p className="text-xs text-on-surface-variant mt-1">Baseado no peso</p>
            </div>
         </Card>

         <Card className="bg-surface border-outline-variant flex flex-col justify-between">
            <div className="flex justify-between items-start mb-4">
               <div className="bg-primary-container p-2 rounded-lg text-on-primary-container">
                  <Hammer className="w-5 h-5" />
               </div>
               <span className="text-xs font-bold text-on-surface-variant bg-surface-variant px-2 py-1 rounded">Mão de Obra</span>
