            <div>
               <p className="text-2xl font-bold text-on-surface">{formatCurrency(financials.laborProduction)}</p>
               <p className="text-xs text-on-surface-variant mt-1">Produção bruta</p>
            </div>
         </Card>

         <Card className="bg-surface border-outline-variant flex flex-col justify-between">
