               <div className="bg-error-container p-2 rounded-lg text-on-error-container">
                  <PaintBucket className="w-5 h-5" />
               </div>
               <span className="text-xs font-bold text-on-surface-variant bg-surface-variant px-2 py-1 rounded">Pintura</span>
            </div>
            <div>
               <p className="text-2xl font-bold text-on-surface">{formatCurrency(financials.laborPainting)}</p>
               <p className="text-xs text-on-surface-variant mt-1">Comissões ({paintingCommissionPercentage}%)</p>
            </div>
         </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
         <Card className="h-80 flex flex-col pt-6 px-2 bg-surface border-outline-variant">
            <h3 className="text-lg font-medium text-on-surface px-4 mb-2">Composição de Custos</h3>
            <div className="flex-1 w-full min-h-0">
              <ResponsiveContainer width="100%" height="100%">
                 <BarChart data={costData} layout="vertical" margin={{ top: 5, right: 30, left: 20, bottom: 5 }}>
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="var(--color-outline-variant)" opacity={0.3} />
                    <XAxis type="number" hide />
                    <YAxis dataKey="name" type="category" width={90} tick={{fontSize: 11, fill: 'var(--color-on-surface-variant)'}} axisLine={false} tickLine={false} />
                    <Tooltip 
                      cursor={{fill: 'transparent'}}
                      contentStyle={{ 
                         borderRadius: '12px', 
                         border: '1px solid var(--color-outline-variant)', 
                         backgroundColor: 'rgb(var(--color-surface))',
                         color: 'rgb(var(--color-on-surface))',
                         boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' 
                       }}
