const PaymentsTab = () => {
  const { employees, payments, addPayment } = useStore();
  const [selectedEmpId, setSelectedEmpId] = useState<string>('');
  const [amount, setAmount] = useState<string>('');
  const [obs, setObs] = useState('');
  const [feedback, setFeedback] = useState('');
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  const activeEmployees = useMemo(() => employees.filter(e => e.active), [employees]);
  const selectedEmployee = activeEmployees.find(e => e.id === selectedEmpId);

  const handleRegisterPayment = () => {
     if (!selectedEmployee || !amount) return;
     const val = parseFloat(amount);
     if (isNaN(val) || val <= 0) return;
     const paymentDate = new Date(selectedDate + 'T12:00:00').getTime();
     const record: PaymentRecord = {
       id: uuidv4(),
       employeeId: selectedEmployee.id,
       employeeName: selectedEmployee.name,
       sector: selectedEmployee.sector,
       amount: val,
       date: paymentDate,
       observation: obs
     };
     addPayment(record);
     setAmount('');
     setObs('');
     setFeedback('Pagamento registrado!');
     setTimeout(() => setFeedback(''), 3000);
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
      <h2 className="text-2xl font-normal text-on-background px-1">Gestão de Pagamentos</h2>
      <Card className="border-primary/20 bg-surface shadow-md">
         <div className="flex items-center gap-2 mb-4 text-primary">
            <Wallet className="w-5 h-5" />
            <span className="font-bold uppercase text-xs tracking-wider">Novo Pagamento</span>
         </div>
         <div className="space-y-4">
            <div>
              <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Colaborador</label>
              <select 
                className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                value={selectedEmpId}
                onChange={e => setSelectedEmpId(e.target.value)}
              >
                <option value="">Selecione...</option>
                {activeEmployees.map(e => (
                  <option key={e.id} value={e.id}>{e.name} - {e.sector}</option>
                ))}
              </select>
            </div>
            {selectedEmployee && (
               <div className="flex items-center gap-2 px-1">
                  <span className="text-sm text-on-surface-variant">Setor:</span>
                  <Badge color="blue">{selectedEmployee.sector}</Badge>
               </div>
            )}
            <div>
               <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block flex items-center gap-2">
                  <CalendarIcon className="w-3 h-3" /> Data
               </label>
               <input 
                 type="date" 
                 className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                 value={selectedDate}
                 onChange={(e) => setSelectedDate(e.target.value)}
                 required
               />
            </div>
            <div>
              <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Valor (R$)</label>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-on-surface-variant font-bold">R$</span>
                <input 
                  type="number" 
                  className="w-full pl-12 pr-4 py-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary text-lg font-bold"
                  value={amount}
                  onChange={e => setAmount(e.target.value)}
                  placeholder="0.00"
                />
              </div>
            </div>
            <div>
              <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Observação (Opcional)</label>
              <input 
                 className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                 value={obs}
                 onChange={e => setObs(e.target.value)}
                 placeholder="Ex: Adiantamento, Vale, Salário..."
              />
            </div>
            <Button onClick={handleRegisterPayment} className="w-full h-12 text-base shadow-lg" disabled={!selectedEmployee || !amount}>
               Registrar Pagamento
            </Button>
            {feedback && <p className="text-success text-center font-bold text-sm">{feedback}</p>}
         </div>
      </Card>
      <div>
         <h3 className="font-bold text-on-surface mb-3 px-1">Histórico Recente</h3>
         <div className="space-y-3">
            {payments.length === 0 ? (
               <div className="text-center py-8 text-on-surface-variant bg-surface rounded-2xl border border-outline-variant">
                  Nenhum pagamento registrado.
               </div>
            ) : (
              payments.sort((a,b) => b.date - a.date).map(p => (
                 <div key={p.id} className="bg-surface p-4 rounded-2xl border border-outline-variant flex justify-between items-center shadow-sm">
                    <div>
                       <p className="font-bold text-on-surface">{p.employeeName}</p>
                       <div className="flex items-center gap-2 mt-1">
                          <span className="text-xs text-on-surface-variant">{new Date(p.date).toLocaleDateString()}</span>
                          <span className="w-1 h-1 bg-outline-variant rounded-full"></span>
                          <span className="text-xs text-on-surface-variant">{p.sector}</span>
                       </div>
                       {p.observation && <p className="text-xs text-on-surface-variant italic mt-1">"{p.observation}"</p>}
                    </div>
                    <span className="text-lg font-bold text-success bg-success-container text-on-success-container px-3 py-1 rounded-lg">
                       R$ {p.amount.toFixed(2)}
                    </span>
                 </div>
              ))
            )}
         </div>
      </div>
    </div>
  );
};

const ConfigTab = () => {
  const { 
    productionItems, payments, employees, vaseModels, 
    rawMaterialCostPerKg, updateRawMaterialCostPerKg, 
    paintingCommissionPercentage, updatePaintingCommissionPercentage,
    isDarkMode, toggleTheme, resetData, logout 
  } = useStore();
  const [confirmReset, setConfirmReset] = useState(false);
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);
  const [filterEmployeeId, setFilterEmployeeId] = useState<string>('');

  const handleExportReport = (type: 'production' | 'financial') => {
    const start = new Date(startDate + 'T00:00:00').getTime();
    const end = new Date(endDate + 'T23:59:59').getTime();
    let filteredItems = productionItems.filter(i => i.createdAt >= start && i.createdAt <= end);
    let filteredPayments = payments.filter(p => p.date >= start && p.date <= end);

    if (filterEmployeeId) {
      filteredItems = filteredItems.filter(i => i.producedBy === filterEmployeeId || i.finishedBy === filterEmployeeId || i.paintedBy === filterEmployeeId);
      filteredPayments = filteredPayments.filter(p => p.employeeId === filterEmployeeId);
    }
    const contextLabel = `supervisor_${startDate}_${endDate}`;
    if (type === 'production') {
      exportFullSupervisorReport(filteredItems, filteredPayments, vaseModels, contextLabel);
    } else {
      exportPaymentReport(filteredPayments, contextLabel);
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
      <h2 className="text-2xl font-normal text-on-background px-1">Configurações</h2>

