const GoalsTab = () => {
  const { employees, goals, addGoal, deleteGoal, vaseModels, currentUser } = useStore();
  const [selectedEmpId, setSelectedEmpId] = useState<string>('');
  const [period, setPeriod] = useState<GoalPeriod>('WEEKLY');
  const [totalTarget, setTotalTarget] = useState<string>('');
  const [selectedModelId, setSelectedModelId] = useState<string>('');
  const [modelTargetQty, setModelTargetQty] = useState<string>('');
  const [modelTargets, setModelTargets] = useState<GoalModelTarget[]>([]);
  const [feedback, setFeedback] = useState('');

  // Dates defaults to current week
  const now = new Date();
  const startOfWeek = new Date(now.setDate(now.getDate() - now.getDay()));
  const endOfWeek = new Date(now.setDate(now.getDate() - now.getDay() + 6));
  const [startDate, setStartDate] = useState(startOfWeek.toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(endOfWeek.toISOString().split('T')[0]);

  const activeEmployees = useMemo(() => employees.filter(e => e.active), [employees]);
  const selectedEmployee = activeEmployees.find(e => e.id === selectedEmpId);

  const handleAddModelTarget = () => {
    if (!selectedModelId || !modelTargetQty) return;
    const qty = parseInt(modelTargetQty);
    if (isNaN(qty) || qty <= 0) return;

    setModelTargets(prev => [...prev, { modelId: selectedModelId, targetQuantity: qty }]);
    setSelectedModelId('');
    setModelTargetQty('');
  };

  const handleRemoveModelTarget = (idx: number) => {
    setModelTargets(prev => prev.filter((_, i) => i !== idx));
  };

  const handleSaveGoal = () => {
    if (!selectedEmployee || !totalTarget) return;
    const total = parseInt(totalTarget);
    if (isNaN(total) || total <= 0) return;

    const newGoal: Goal = {
      id: uuidv4(),
      employeeId: selectedEmployee.id,
      sector: selectedEmployee.sector as Sector,
      period,
      startDate: new Date(startDate + 'T00:00:00').getTime(),
      endDate: new Date(endDate + 'T23:59:59').getTime(),
      totalQuantityTarget: total,
      modelTargets,
      createdAt: Date.now(),
      createdBy: currentUser?.id || 'system'
    };

    addGoal(newGoal);
    setFeedback('Meta definida com sucesso!');

    // Reset form partially
    setTotalTarget('');
    setModelTargets([]);
    setTimeout(() => setFeedback(''), 3000);
  };

  // Filter goals for selected employee to show history
  const employeeGoals = goals.filter(g => g.employeeId === selectedEmpId).sort((a,b) => b.createdAt - a.createdAt);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
       <div className="flex justify-between items-center px-1">
          <h2 className="text-2xl font-normal text-on-background">Gestão de Metas</h2>
       </div>

       <Card className="bg-surface border-outline-variant shadow-md">
          <div className="flex items-center gap-2 mb-4 text-primary">
            <Target className="w-5 h-5" />
            <span className="font-bold uppercase text-xs tracking-wider">Definir Nova Meta</span>
         </div>

         <div className="space-y-4">
            <div>
              <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Colaborador</label>
              <select 
                className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                value={selectedEmpId}
                onChange={e => setSelectedEmpId(e.target.value)}
              >
                <option value="">Selecione...</option>
                {activeEmployees.map(e => (
                  <option key={e.id} value={e.id}>{e.name} - {e.sector}</option>
                ))}
              </select>
            </div>

            {selectedEmployee && (
               <div className="grid grid-cols-2 gap-4">
                  <div>
                     <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Período</label>
                     <select 
                        className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary"
                        value={period}
                        onChange={e => setPeriod(e.target.value as GoalPeriod)}
                     >
                        <option value="DAILY">Diária</option>
                        <option value="WEEKLY">Semanal</option>
                        <option value="MONTHLY">Mensal</option>
                     </select>
                  </div>
                  <div>
                     <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Alvo Total (Qtd)</label>
                     <input 
                        type="number" 
                        className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary font-bold"
                        value={totalTarget}
                        onChange={e => setTotalTarget(e.target.value)}
                        placeholder="Ex: 50"
                     />
                  </div>
               </div>
            )}

            <div className="grid grid-cols-2 gap-4">
               <div>
                 <label className="text-xs font-bold text-on-surface-variant uppercase mb-1 block">Início</label>
                 <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-sm" />
               </div>
               <div>
                 <label className="text-xs font-bold text-on-surface-variant uppercase mb-1 block">Fim</label>
                 <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-sm" />
               </div>
            </div>

            {/* Model Specific Targets */}
            <div className="bg-surface-variant/30 p-4 rounded-xl border border-outline-variant">
               <p className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-3">Metas Específicas (Opcional)</p>

               <div className="flex gap-2 mb-3">
                  <select 
                     className="flex-1 p-2 bg-surface border border-outline-variant rounded-lg text-sm"
                     value={selectedModelId}
                     onChange={e => setSelectedModelId(e.target.value)}
                  >
                     <option value="">Modelo...</option>
                     {vaseModels.map(v => <option key={v.id} value={v.id}>{v.name} ({v.type})</option>)}
                  </select>
                  <input 
                     type="number" 
                     className="w-20 p-2 bg-surface border border-outline-variant rounded-lg text-sm"
                     placeholder="Qtd"
                     value={modelTargetQty}
                     onChange={e => setModelTargetQty(e.target.value)}
                  />
                  <Button type="button" size="sm" onClick={handleAddModelTarget} className="rounded-lg h-auto px-3"><Plus className="w-4 h-4" /></Button>
               </div>

               {modelTargets.length > 0 && (
                  <div className="space-y-2">
                     {modelTargets.map((mt, idx) => {
                        const modelName = vaseModels.find(v => v.id === mt.modelId)?.name || 'Unknown';
                        return (
                           <div key={idx} className="flex justify-between items-center bg-surface p-2 rounded-lg border border-outline-variant text-sm">
                              <span>{modelName}</span>
                              <div className="flex items-center gap-3">
                                 <span className="font-bold">{mt.targetQuantity} un.</span>
                                 <button onClick={() => handleRemoveModelTarget(idx)} className="text-error"><Trash className="w-3 h-3" /></button>
                              </div>
                           </div>
                        )
                     })}
                  </div>
               )}
            </div>

            <Button onClick={handleSaveGoal} className="w-full h-12 text-base shadow-lg" disabled={!selectedEmployee || !totalTarget}>
               Salvar Meta
            </Button>
            {feedback && <p className="text-success text-center font-bold text-sm">{feedback}</p>}
         </div>
       </Card>

       {/* Active Goals List */}
       {selectedEmployee && (
          <div>
             <h3 className="font-bold text-on-surface mb-3 px-1">Metas Definidas para {selectedEmployee.name}</h3>
             {employeeGoals.length === 0 ? (
                <p className="text-on-surface-variant text-sm px-1">Nenhuma meta encontrada.</p>
             ) : (
                <div className="space-y-3">
                   {employeeGoals.map(goal => (
                      <div key={goal.id} className="bg-surface p-4 rounded-2xl border border-outline-variant shadow-sm relative">
                         <button onClick={() => deleteGoal(goal.id)} className="absolute top-4 right-4 text-on-surface-variant hover:text-error">
                            <Trash className="w-4 h-4" />
                         </button>

                         <div className="flex items-center gap-2 mb-2">
                            <Badge color="blue">{goal.period}</Badge>
                            <span className="text-xs text-on-surface-variant">
                               {new Date(goal.startDate).toLocaleDateString()} - {new Date(goal.endDate).toLocaleDateString()}
                            </span>
                         </div>

                         <p className="font-bold text-lg text-on-surface mb-1">
                            Alvo Total: {goal.totalQuantityTarget} unidades
                         </p>

                         {goal.modelTargets && goal.modelTargets.length > 0 && (
                            <div className="mt-2 flex flex-wrap gap-2">
                               {goal.modelTargets.map((mt, i) => {
                                  const mName = vaseModels.find(v => v.id === mt.modelId)?.name;
                                  return (
                                     <span key={i} className="text-xs bg-surface-variant px-2 py-1 rounded border border-outline-variant">
                                        {mName}: <b>{mt.targetQuantity}</b>
                                     </span>
                                  )
                               })}
