                <div>
                  <h3 className={`font-medium text-lg ${emp.active ? 'text-on-surface' : 'text-on-surface-variant'}`}>{emp.name}</h3>
                  <div className="flex items-center gap-2">
                     <span className="text-xs text-on-surface-variant">{emp.sector}</span>
                     {!emp.active && <span className="text-xs bg-error-container text-on-error-container px-2 py-0.5 rounded-full font-bold">Inativo</span>}
