             </div>
             <div className="flex items-center gap-2">
               <button onClick={() => { setEditingEmp(emp); setIsEmpModalOpen(true); }} className="p-2 text-on-surface-variant hover:text-primary hover:bg-primary-container rounded-full transition-colors">
                  <Pencil className="w-5 h-5" />
               </button>
               <button onClick={() => toggleStatus(emp)} className={`p-2 rounded-full transition-colors ${emp.active ? 'text-success hover:bg-success-container' : 'text-outline hover:bg-surface-variant'}`}>
                  {emp.active ? <CheckCircle2 className="w-5 h-5" /> : <XCircle className="w-5 h-5" />}
               </button>
             </div>
          </div>
        ))}
      </div>
      <Modal isOpen={isEmpModalOpen} onClose={() => setIsEmpModalOpen(false)} title={editingEmp.id ? "Editar Colaborador" : "Novo Colaborador"} footer={
         <div className="flex gap-2 w-full justify-end">
           <Button variant="ghost" onClick={() => setIsEmpModalOpen(false)}>Cancelar</Button>
           <Button onClick={handleSaveEmployee}>Salvar</Button>
         </div>
      }>
        <div className="space-y-4 py-2">
          <div>
             <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Nome Completo</label>
             <input className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary" value={editingEmp.name || ''} onChange={e => setEditingEmp({...editingEmp, name: e.target.value})} placeholder="Ex: João da Silva" />
           </div>
           <div>
             <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Setor</label>
