         <Card className="flex items-center justify-between p-5 cursor-pointer hover:bg-surface-variant transition-colors bg-surface border-outline-variant col-span-1 md:col-span-2" onClick={toggleTheme}>
            <div className="flex items-center gap-3">
              <div className="bg-surface-variant p-2 rounded-full"><Moon className="w-5 h-5 text-on-surface-variant" /></div>
              <span className="font-medium text-on-surface">Modo Escuro</span>
            </div>
            <div className={`w-12 h-7 rounded-full p-1 transition-colors ${isDarkMode ? 'bg-primary' : 'bg-surface-variant border border-outline-variant'}`}>
               <div className={`w-5 h-5 bg-white rounded-full shadow-sm transition-transform ${isDarkMode ? 'translate-x-5' : 'translate-x-0'}`} />
            </div>
         </Card>
      </div>

      <Card className="p-5 border-error/50 bg-error-container text-on-error-container">
         <h3 className="font-bold mb-2 flex items-center gap-2"><Trash className="w-4 h-4" /> Zona de Perigo</h3>
         {!confirmReset ? (
            <Button variant="danger" className="w-full bg-surface text-error border border-error/20 hover:bg-surface-variant shadow-sm" onClick={() => setConfirmReset(true)}>Resetar Dados do Sistema</Button>
         ) : (
           <div className="flex gap-2">
             <Button variant="ghost" onClick={() => setConfirmReset(false)} className="flex-1 bg-surface/50">Cancelar</Button>
             <Button variant="danger" onClick={() => { resetData(); setConfirmReset(false); }} className="flex-1">Confirmar Reset</Button>
           </div>
         )}
      </Card>

      <Button variant="outline" className="w-full mt-4 text-on-surface-variant border-outline bg-surface" onClick={logout}>
        <LogOut className="mr-2 h-4 w-4" /> Encerrar Sessão
      </Button>
    </div>
  );
};

const UpdatesTab = () => {
  const { changelog, systemVersion } = useStore();
  const getTypeConfig = (type: string) => {
      switch(type) {
      case 'FIX': return { icon: <Bug className="w-4 h-4" />, color: 'bg-error-container text-on-error-container', label: 'Correção' };
      case 'FEATURE': return { icon: <Star className="w-4 h-4" />, color: 'bg-success-container text-on-success-container', label: 'Nova Função' };
      case 'IMPROVEMENT': return { icon: <Zap className="w-4 h-4" />, color: 'bg-primary-container text-on-primary-container', label: 'Melhoria' };
      case 'MAJOR': return { icon: <Activity className="w-4 h-4" />, color: 'bg-tertiary-container text-on-tertiary-container', label: 'Versão Principal' };
      default: return { icon: <History className="w-4 h-4" />, color: 'bg-surface-variant text-on-surface-variant', label: 'Info' };
      }
  };

  return (
      <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500">
          <h2 className="text-2xl font-normal text-on-background px-1">Atualizações do Sistema</h2>
          <Card className="bg-surface border-outline-variant p-0 overflow-hidden">
              {changelog.length === 0 ? (
                  <div className="p-8 text-center text-on-surface-variant">
                      Nenhum registro de atualização encontrado.
                  </div>
              ) : (
                  <div>
                      {changelog.map((entry, idx) => {
                          const config = getTypeConfig(entry.type);
                          return (
                              <div key={idx} className="p-4 border-b border-outline-variant last:border-0 hover:bg-surface-variant/30 transition-colors">
                                  <div className="flex justify-between items-start mb-2">
                                      <div className="flex items-center gap-3">
                                          <span className="text-xl font-bold text-primary">v{entry.version}</span>
                                          <span className={`flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] uppercase font-bold ${config.color}`}>
                                              {config.icon} {config.label}
                                          </span>
                                      </div>
                                      <span className="text-xs text-on-surface-variant">{new Date(entry.date).toLocaleDateString()}</span>
                                  </div>
                                  <p className="text-on-surface opacity-90 leading-relaxed">
                                      {entry.description}
                                  </p>
                              </div>
                          )
                      })}
                  </div>
              )}
          </Card>
          <div className="text-center text-on-surface-variant text-xs p-4">
              Versão Atual: <span className="font-bold">{systemVersion}</span>
          </div>
      </div>
  );
};

