const DEFAULT_USER_PREFS: Omit<UserPreferences, 'userId'> = {
  darkMode: false,
  notifySystem: true,
  notifyGoals: true,
  notifyPayments: true,
  showFinancials: true,
  showProductionQty: true,
  showGoalsBar: true,
};

export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDarkMode: false,
      supervisorPassword: DEFAULT_SUPERVISOR_PASS,
      currentUser: null,
      currentSector: null,

      // Versioning Defaults
      systemVersion: INITIAL_VERSION,
      changelog: INITIAL_CHANGELOG,

      rawMaterialCostPerKg: 0.26,
      paintingCommissionPercentage: 10, // Default 10%

      employees: INITIAL_EMPLOYEES,
      vaseModels: INITIAL_VASES,
      productionItems: [],
      payments: [],
      drafts: [],
      systemLogs: [],
      goals: [],
      userPreferences: {},

      toggleTheme: () => set((state) => ({ isDarkMode: !state.isDarkMode })),

      setSector: (sector) => set({ currentSector: sector }),

      loginUser: (user) => {
        // Apply user theme preference on login
        const state = get();
        const userPrefs = state.userPreferences[user.id];

        // If user has saved prefs, apply theme. Else default to light (false).
        const themeToApply = userPrefs ? userPrefs.darkMode : false;

        set({ 
          currentUser: user,
          isDarkMode: themeToApply
        });
      },

      logout: () => set((state) => {
        // Log the logout action
        if (state.currentUser) {
           const newLog: SystemLog = {
            id: uuidv4(),
            timestamp: Date.now(),
            action: 'LOGOUT',
            sector: state.currentUser.sector as Sector,
            actorId: state.currentUser.id,
            actorName: state.currentUser.name,
            details: 'Sessão encerrada pelo usuário.',
          };
          return { currentUser: null, currentSector: null, systemLogs: [newLog, ...state.systemLogs] };
        }
        return { currentUser: null, currentSector: null };
      }),

      // --- SETTINGS ACTIONS ---
      updateUserPreferences: (userId, newPrefs) => set((state) => {
        const currentPrefs = state.userPreferences[userId] || { userId, ...DEFAULT_USER_PREFS };
        const updatedPrefs = { ...currentPrefs, ...newPrefs };

        // Generate Audit Log
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'SETTINGS_UPDATE',
          sector: state.currentUser?.sector as Sector || Sector.PRODUCTION, // Fallback
          actorId: userId,
          actorName: state.currentUser?.name || 'User',
          details: 'Alteração nas configurações do perfil.',
        };

        // If theme changed, apply immediately
        let newIsDarkMode = state.isDarkMode;
        if (newPrefs.darkMode !== undefined) {
           newIsDarkMode = newPrefs.darkMode;
        }

        return {
          userPreferences: {
            ...state.userPreferences,
            [userId]: updatedPrefs
          },
          isDarkMode: newIsDarkMode,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      addProductionItems: (items) => set((state) => {
        const hydratedItems = items.map(item => {
          const model = state.vaseModels.find(v => v.id === item.modelId);
          return {
            ...item,
            productionValue: model ? model.costProduction : 0,
            rawMaterialCost: model ? (model.weightKg * state.rawMaterialCostPerKg) : 0
          };
        });

        const currentUser = state.currentUser;
        const totalValue = hydratedItems.reduce((acc, i) => acc + i.productionValue, 0);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PRODUCTION',
          sector: Sector.PRODUCTION,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: hydratedItems[0]?.producedBy,
          details: `Registro de produção: ${hydratedItems.length} itens.`,
          value: totalValue
        };

        return { 
          productionItems: [...state.productionItems, ...hydratedItems],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      processStageItems: (itemIds, workerId, stage, timestamp) => set((state) => {
        let totalProcessedValue = 0;

        const updatedItems = state.productionItems.map((item) => {
          if (itemIds.includes(item.id)) {
            const model = state.vaseModels.find(v => v.id === item.modelId);

            if (stage === 'finishing') {
              const val = model?.costFinishing || 0;
              totalProcessedValue += val;
              return {
                ...item,
                status: ItemStatus.AWAITING_PAINTING,
                updatedAt: timestamp,
                finishedBy: workerId,
                finishingValue: val
              };
            }

            if (stage === 'painting') {
               const salePrice = model?.priceSale || 0;
               // USE DYNAMIC PERCENTAGE from state
               const commission = calculatePaintingCommission(salePrice, state.paintingCommissionPercentage);

               totalProcessedValue += commission;

               return {
                ...item,
                status: ItemStatus.FINISHED,
                updatedAt: timestamp,
                paintedBy: workerId,
                paintingValue: commission
              };
            }
          }
          return item;
        });

        const currentUser = state.currentUser;
        const actionType = stage === 'finishing' ? 'FINISHING' : 'PAINTING';
        const sector = stage === 'finishing' ? Sector.FINISHING : Sector.PAINTING;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: actionType,
          sector: sector,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: workerId,
          details: `Processamento de ${itemIds.length} itens no setor ${sector}.`,
          value: totalProcessedValue
        };

        return { 
          productionItems: updatedItems,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- DRAFT ACTIONS ---
      addDraft: (draft) => set((state) => ({ drafts: [draft, ...state.drafts] })),

      removeDraft: (id) => set((state) => ({ drafts: state.drafts.filter(d => d.id !== id) })),

      confirmDraft: (draftId) => {
        const state = get();
        const draft = state.drafts.find(d => d.id === draftId);
        if (!draft) return;

        if (draft.type === 'PRODUCTION' && draft.productionData) {
          const newItems: ProductionItem[] = [];

          // --- CIP Generation Logic ---
          const draftDate = new Date(draft.selectedDate);

          // Filter existing items for this specific day to calculate the next sequence
          const existingItemsForDay = state.productionItems.filter(item => {
             const itemDate = new Date(item.createdAt);
             return itemDate.getFullYear() === draftDate.getFullYear() &&
                    itemDate.getMonth() === draftDate.getMonth() &&
                    itemDate.getDate() === draftDate.getDate();
          });

          let currentSequence = existingItemsForDay.length;

          // Process items
          for (const { modelId, quantity } of draft.productionData) {
            const model = state.vaseModels.find(v => v.id === modelId);
            if (model) {
               for (let i = 0; i < quantity; i++) {

                // Enforce Daily Limit (99 items max: 00 to 99)
                if (currentSequence > 99) {
                   throw new Error("Limite diário de produção (100 vasos) atingido para esta data. Impossível gerar novo CIP.");
                }

                const cip = generateCIP(draftDate, currentSequence);
                currentSequence++;

                newItems.push({
                  id: uuidv4(),
                  cip: cip,
                  modelId: model.id,
                  modelName: model.name,
                  type: model.type,
                  status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
                  createdAt: draft.selectedDate,
                  updatedAt: draft.selectedDate,
                  producedBy: draft.userId,
                  productionValue: 0,
                  rawMaterialCost: 0
                });
               }
            }
          }

          if (newItems.length > 0) {
            get().addProductionItems(newItems);
          }
        } else if ((draft.type === 'FINISHING' || draft.type === 'PAINTING') && draft.processingIds) {
           const stage = draft.type === 'FINISHING' ? 'finishing' : 'painting';
           get().processStageItems(draft.processingIds, draft.userId, stage, draft.selectedDate);
        }

        get().removeDraft(draftId);
      },

      // --- GOALS ACTIONS ---
      addGoal: (goal) => set((state) => {
        const currentUser = state.currentUser;
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal.employeeId,
          details: `Meta ${goal.period} definida: ${goal.totalQuantityTarget} un. (${new Date(goal.startDate).toLocaleDateString()} - ${new Date(goal.endDate).toLocaleDateString()})`,
        };

        return {
          goals: [...state.goals, goal],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      deleteGoal: (id) => set((state) => {
        const goal = state.goals.find(g => g.id === id);
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal?.employeeId,
          details: `Meta removida.`,
        };

        return {
          goals: state.goals.filter(g => g.id !== id),
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- SUPERVISOR ACTIONS ---
      updateSupervisorPassword: (pass) => set({ supervisorPassword: pass }),

      updateRawMaterialCostPerKg: (value) => set((state) => {
        const prev = state.rawMaterialCostPerKg;
        const currentUser = state.currentUser;

        // Audit Log for Cost Change
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'ADMIN_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          details: `Custo do traço alterado de R$ ${prev.toFixed(2)} para R$ ${value.toFixed(2)}`,
        };

        return { 
           rawMaterialCostPerKg: value,
           systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      updatePaintingCommissionPercentage: (value) => set((state) => {
        const prev = state.paintingCommissionPercentage;
        const currentUser = state.currentUser;

        // Audit Log for Commission Change
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'ADMIN_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          details: `Comissão de pintura alterada de ${prev}% para ${value}%`,
        };

        return {
          paintingCommissionPercentage: value,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      addVaseModel: (model) => set((state) => ({ vaseModels: [...state.vaseModels, model] })),
      updateVaseModel: (model) => set((state) => ({
        vaseModels: state.vaseModels.map((v) => (v.id === model.id ? model : v))
      })),
      deleteVaseModel: (id) => set((state) => ({
        vaseModels: state.vaseModels.filter((v) => v.id !== id)
      })),
      addEmployee: (emp) => set((state) => ({ employees: [...state.employees, emp] })),
      updateEmployee: (emp) => set((state) => ({
        employees: state.employees.map((e) => (e.id === emp.id ? emp : e))
      })),
      addPayment: (payment) => set((state) => {
        const currentUser = state.currentUser;
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PAYMENT',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: payment.employeeId,
          details: `Pagamento registrado para ${payment.employeeName}. Obs: ${payment.observation || '-'}`,
          value: payment.amount
        };

        return { 
          payments: [payment, ...state.payments],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      resetData: () => set({
        productionItems: [],
        payments: [],
        employees: INITIAL_EMPLOYEES,
        vaseModels: INITIAL_VASES,
        supervisorPassword: DEFAULT_SUPERVISOR_PASS,
        rawMaterialCostPerKg: 0.26,
        paintingCommissionPercentage: 10,
        drafts: [],
        systemLogs: [],
        goals: [],
        userPreferences: {},
        systemVersion: INITIAL_VERSION,
        changelog: INITIAL_CHANGELOG
      }),

      // --- VERSION CONTROL ACTIONS ---
      registerSystemUpdate: (type: ChangeType, description: string) => set((state) => {
        const parts = state.systemVersion.split('.').map(Number);
        if (parts.length !== 3) return state;

        let [major, minor, patch] = parts;

        switch (type) {
          case 'MAJOR': major++; minor = 0; patch = 0; break;
          case 'FEATURE': minor++; patch = 0; break;
          case 'IMPROVEMENT': case 'FIX': patch++; break;
        }

        const newVersion = `${major}.${minor}.${patch}`;

        const newEntry: ChangelogEntry = {
          version: newVersion,
          date: Date.now(),
          type,
          description
        };

        if (state.changelog.length > 0 && state.changelog[0].description === description) {
           return state;
        }

        return {
          systemVersion: newVersion,
          changelog: [newEntry, ...state.changelog]
        };
      })
    }),
    {
      name: 'home-pots-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

import React, { useMemo } from 'react';
import { Modal, Badge, Button } from './UI';
import { ProductionItem, VaseModel, PaymentRecord, Sector } from '../types';
import { Calendar, DollarSign, Box, Wallet, Download, Hash } from 'lucide-react';
import { exportProductionReport, exportPaymentReport } from '../utils/csvHelper';

interface HistoryModalProps {
  isOpen: boolean;
  onClose: () => void;
  mode: 'items' | 'financial' | 'payments';
  items: ProductionItem[]; // Production items
  payments?: PaymentRecord[]; // Payment records
  vaseModels: VaseModel[];
  valueKey: 'productionValue' | 'finishingValue' | 'paintingValue';
  title: string;
}

const HistoryModal: React.FC<HistoryModalProps> = ({ 
  isOpen, onClose, mode, items, payments = [], vaseModels, valueKey, title 
}) => {

  // Sort items by date descending
  const sortedItems = useMemo(() => {
    return [...items].sort((a, b) => b.updatedAt - a.updatedAt);
  }, [items]);

  // Sort payments by date descending
  const sortedPayments = useMemo(() => {
    return [...payments].sort((a, b) => b.date - a.date);
  }, [payments]);

  // Calculations
  const totalProduction = items.reduce((acc, curr) => acc + (curr[valueKey] || 0), 0);
  const totalPaid = payments.reduce((acc, curr) => acc + curr.amount, 0);

  // Group for financial view (Daily Production Summary)
  const financialData = useMemo(() => {
    const groups: Record<string, { date: string, count: number, total: number }> = {};

    sortedItems.forEach(item => {
      const date = new Date(item.updatedAt).toLocaleDateString('pt-BR');
      if (!groups[date]) {
        groups[date] = { date, count: 0, total: 0 };
      }
      groups[date].count += 1;
      groups[date].total += (item[valueKey] || 0);
    });

    return Object.values(groups).sort((a, b) => {
      const [d1, m1, y1] = a.date.split('/').map(Number);
      const [d2, m2, y2] = b.date.split('/').map(Number);
      return new Date(y2, m2 - 1, d2).getTime() - new Date(y1, m1 - 1, d1).getTime();
    });
  }, [sortedItems, valueKey]);

  // Determine Sector from ValueKey to restrict export
  const getSectorFromKey = (): Sector | undefined => {
    if (valueKey === 'productionValue') return Sector.PRODUCTION;
    if (valueKey === 'finishingValue') return Sector.FINISHING;
    if (valueKey === 'paintingValue') return Sector.PAINTING;
    return undefined;
  };

  const currentSector = getSectorFromKey();

  const handleExport = () => {
    if (mode === 'payments') {
      exportPaymentReport(sortedPayments, 'historico_pessoal');
    } else {
      // Pass the restricted sector to the export function
      exportProductionReport(sortedItems, 'historico_pessoal', currentSector);
    }
  };

  return (
    <Modal 
      isOpen={isOpen} 
      onClose={onClose} 
      title={title}
      footer={
        <div className="w-full flex flex-col gap-3">
           {currentSector && mode !== 'payments' && (
             <div className="text-xs text-center text-on-surface-variant bg-surface-variant/50 p-2 rounded-lg border border-outline-variant/50">
               Exportação restrita ao setor: <span className="font-bold text-primary">{currentSector.toUpperCase()}</span>
             </div>
           )}
           <div className="flex justify-end w-full">
             <Button variant="outline" size="sm" onClick={handleExport} className="gap-2 border-outline-variant bg-surface w-full sm:w-auto text-on-surface hover:bg-surface-variant">
                <Download className="w-4 h-4" /> Exportar CSV
             </Button>
           </div>
        </div>
      }
    >
      <div className="space-y-4">
        {/* Header Summary - Solid Background */}
        <div className="bg-surface-variant p-4 rounded-2xl border border-outline-variant flex justify-between items-center text-on-surface-variant">
          {mode === 'payments' ? (
             <>
                <div>
                  <p className="text-xs uppercase font-bold">Total Recebido</p>
                  <p className="text-2xl font-bold text-success">R$ {totalPaid.toFixed(2)}</p>
                </div>
                <div className="text-right">
                  <p className="text-xs uppercase font-bold">Pagamentos</p>
                  <p className="text-xl font-medium text-on-surface">{payments.length}</p>
                </div>
             </>
          ) : (
            <>
              <div>
                 <p className="text-xs uppercase font-bold">Total Produzido</p>
                 <p className="text-2xl font-bold text-on-surface">R$ {totalProduction.toFixed(2)}</p>
              </div>
              <div className="text-right">
                 <p className="text-xs uppercase font-bold">Total Itens</p>
                 <p className="text-xl font-medium text-on-surface">{items.length}</p>
              </div>
            </>
          )}
        </div>

        <div className="relative">
          <div className="absolute inset-0 flex items-center" aria-hidden="true">
            <div className="w-full border-t border-outline-variant" />
          </div>
          <div className="relative flex justify-center">
            <span className="bg-surface px-2 text-xs text-on-surface-variant uppercase">
              {mode === 'items' && 'Detalhamento por Item'}
              {mode === 'financial' && 'Produção Diária'}
              {mode === 'payments' && 'Extrato de Pagamentos'}
            </span>
          </div>
        </div>

        {/* List Content */}
        <div className="space-y-2 max-h-[50vh] overflow-y-auto pr-1">

          {/* MODE: ITEMS */}
          {mode === 'items' && sortedItems.map(item => {
              const model = vaseModels.find(v => v.id === item.modelId) || { name: item.modelName };
              const date = new Date(item.updatedAt);
              return (
                <div key={item.id} className="flex flex-col p-3 bg-surface border border-outline-variant rounded-xl hover:bg-surface-variant transition-colors gap-2">
                  <div className="flex justify-between items-start">
                    <div className="flex items-start gap-3">
                        <div className="bg-primary-container p-2 rounded-full text-on-primary-container mt-1">
                        <Box className="w-4 h-4" />
                        </div>
                        <div>
                        <p className="font-medium text-on-surface">{item.modelName}</p>
