// Helper to convert array of objects to CSV string
const convertToCSV = (objArray: any[]) => {
  if (!objArray || objArray.length === 0) return '';

  const array = typeof objArray !== 'object' ? JSON.parse(objArray) : objArray;
  let str = '';

  // Headers
  const headers = Object.keys(array[0]).join(',');
  str += headers + '\r\n';

  // Rows
  for (let i = 0; i < array.length; i++) {
    let line = '';
    for (const index in array[i]) {
      if (line !== '') line += ',';

      let cell = array[i][index];

      // Handle strings containing commas or quotes
      if (typeof cell === 'string') {
        cell = `"${cell.replace(/"/g, '""')}"`;
      }
      // Handle dates (if strictly numbers looking like timestamps, could format, but keeping raw for now or relying on pre-formatted objects)

      line += cell;
    }
    str += line + '\r\n';
  }
  return str;
};

// Helper to download the file
const downloadCSV = (csvContent: string, fileName: string) => {
  // Add Byte Order Mark (BOM) for Excel UTF-8 compatibility
  const bom = '\uFEFF'; 
  const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');

  if (link.download !== undefined) {
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', fileName);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
};

// --- Report Generators ---

export const exportProductionReport = (items: ProductionItem[], context: string, sector?: Sector) => {
  const data = items.map(item => {
    // Campos base comuns a todos
    const baseFields = {
      Data: new Date(item.updatedAt).toLocaleDateString('pt-BR'),
      Hora: new Date(item.updatedAt).toLocaleTimeString('pt-BR'),
      CIP: item.cip || 'N/A', // Código de Identificação de Produção
      Modelo: item.modelName,
      Tipo: item.type,
      Status: item.status,
      ID_Registro: item.id
    };

    // Filtragem de colunas por setor
    if (sector === Sector.PRODUCTION) {
      return {
        ...baseFields,
        Valor_Producao: (item.productionValue || 0).toFixed(2).replace('.', ',')
      };
    }

    if (sector === Sector.FINISHING) {
      return {
        ...baseFields,
        Valor_Acabamento: (item.finishingValue || 0).toFixed(2).replace('.', ',')
      };
    }

    if (sector === Sector.PAINTING) {
      return {
        ...baseFields,
        Valor_Pintura: (item.paintingValue || 0).toFixed(2).replace('.', ',')
      };
    }

    // Caso não tenha setor específico (ou seja Supervisor), exporta tudo
    return {
      ...baseFields,
      Valor_Producao: (item.productionValue || 0).toFixed(2).replace('.', ','),
      Valor_Acabamento: (item.finishingValue || 0).toFixed(2).replace('.', ','),
      Valor_Pintura: (item.paintingValue || 0).toFixed(2).replace('.', ',')
    };
  });

  const csv = convertToCSV(data);
  const sectorLabel = sector ? sector.toLowerCase().replace(/ç|ã/g, 'c') : 'geral';
  downloadCSV(csv, `relatorio_${sectorLabel}_${context}_${new Date().toISOString().split('T')[0]}.csv`);
};

export const exportPaymentReport = (payments: PaymentRecord[], context: string) => {
  const data = payments.map(p => ({
    Data: new Date(p.date).toLocaleDateString('pt-BR'),
    Funcionario: p.employeeName,
    Setor: p.sector,
    Valor: p.amount.toFixed(2).replace('.', ','),
    Observacao: p.observation || '',
    ID_Pagamento: p.id
  }));

  const csv = convertToCSV(data);
  downloadCSV(csv, `relatorio_pagamentos_${context}_${new Date().toISOString().split('T')[0]}.csv`);
};

export const exportFullSupervisorReport = (
  items: ProductionItem[], 
  payments: PaymentRecord[], 
  models: VaseModel[],
  filters: string
) => {
  // We can create a consolidated summary or separate logic. 
  // For supervisor, let's export the raw filtered production list with extra details.

  const data = items.map(item => {
    // Find model to get weight/cost details if needed, though item has snapshots
    return {
      Data_Criacao: new Date(item.createdAt).toLocaleDateString('pt-BR'),
      Data_Atualizacao: new Date(item.updatedAt).toLocaleDateString('pt-BR'),
      CIP: item.cip || 'N/A', // Código de Identificação de Produção
      Modelo: item.modelName,
      Tipo: item.type,
      Status: item.status,
      Produtor_ID: item.producedBy,
      Acabador_ID: item.finishedBy || '-',
      Pintor_ID: item.paintedBy || '-',
      Custo_Materia_Prima: item.rawMaterialCost.toFixed(2).replace('.', ','),
      Custo_Mao_Obra: item.productionValue.toFixed(2).replace('.', ','),
      Custo_Acabamento: (item.finishingValue || 0).toFixed(2).replace('.', ','),
      Custo_Pintura: (item.paintingValue || 0).toFixed(2).replace('.', ','),
      Total_Custo: (item.rawMaterialCost + item.productionValue + (item.finishingValue||0) + (item.paintingValue||0)).toFixed(2).replace('.', ',')
    };
  });

  const csv = convertToCSV(data);
  downloadCSV(csv, `relatorio_geral_supervisor_${filters}_${new Date().toISOString().split('T')[0]}.csv`);
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { VaseType, VaseModel, Draft, DraftItemContent, Sector } from '../types';
import { Button, Modal } from '../components/UI';
import { Plus, Minus, Check, ClipboardList, ArrowLeft, TrendingUp, Wallet, FileText, Trash2, Edit, Send, Calendar, Save, Settings, AlertCircle } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import HistoryModal from '../components/HistoryModal';
import { GoalProgressBar, GoalsDetailView } from '../components/GoalComponents';
import EmployeeSettingsScreen from '../components/EmployeeSettingsScreen';

type ViewMode = 'DASHBOARD' | 'REGISTER' | 'GOALS' | 'SETTINGS';

const ProductionScreen: React.FC = () => {
  const { vaseModels, addDraft, removeDraft, confirmDraft, drafts, currentUser, productionItems, payments, logout, goals, userPreferences } = useStore();

  // View State
  const [viewMode, setViewMode] = useState<ViewMode>('DASHBOARD');

  // Register State
  const [draftItems, setDraftItems] = useState<{model: VaseModel, quantity: number}[]>([]);
  const [selectedType, setSelectedType] = useState<VaseType>(VaseType.WITH_SHELL);
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  // Dashboard & Feedback State
  const [feedback, setFeedback] = useState<string | null>(null);
  const [errorFeedback, setErrorFeedback] = useState<string | null>(null);
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Calculations ---
  const today = new Date().toDateString();

  const myDrafts = useMemo(() => 
    drafts.filter(d => d.type === 'PRODUCTION' && d.userId === currentUser?.id)
          .sort((a,b) => b.createdAt - a.createdAt),
  [drafts, currentUser]);

  const myAllTimeProduction = useMemo(() => 
    productionItems.filter(p => p.producedBy === currentUser?.id),
  [productionItems, currentUser]);

  const myAllTimePayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id),
  [payments, currentUser]);

  const myTodaysProduction = myAllTimeProduction.filter(p => 
    new Date(p.createdAt).toDateString() === today
  );

  const dailyTotalQty = myTodaysProduction.length;
  const dailyEarnings = myTodaysProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);

  const totalProducedValue = myAllTimeProduction.reduce((acc, item) => acc + (item.productionValue || 0), 0);
  const totalReceivedValue = myAllTimePayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  const availableModels = useMemo(() => {
    return vaseModels.filter(v => v.type === selectedType);
  }, [selectedType, vaseModels]);

  // --- Preferences Check ---
  const prefs = useMemo(() => {
     if (!currentUser) return null;
     // Default fallback if not set yet
     return userPreferences[currentUser.id] || {
        showFinancials: true,
        showProductionQty: true,
        showGoalsBar: true
     };
  }, [currentUser, userPreferences]);

  // --- Handlers ---

  const startNewProduction = () => {
    setDraftItems([]);
    setSelectedDate(new Date().toISOString().split('T')[0]);
    setViewMode('REGISTER');
  };

  const addToDraft = (model: VaseModel) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === model.id);
      if (existing) {
        return prev.map(i => i.model.id === model.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { model, quantity: 1 }];
    });
  };

  const removeFromDraft = (modelId: string) => {
    setDraftItems(prev => {
      const existing = prev.find(i => i.model.id === modelId);
      if (existing && existing.quantity > 1) {
        return prev.map(i => i.model.id === modelId ? { ...i, quantity: i.quantity - 1 } : i);
      }
      return prev.filter(i => i.model.id !== modelId);
    });
  };

  const handleSaveAsDraft = () => {
    if (draftItems.length === 0 || !currentUser) return;

    const productionDate = new Date(selectedDate + 'T12:00:00').getTime();

    const productionData: DraftItemContent[] = draftItems.map(d => ({
       modelId: d.model.id,
       quantity: d.quantity
    }));

    const newDraft: Draft = {
       id: uuidv4(),
       type: 'PRODUCTION',
       sector: currentUser.sector as any,
       userId: currentUser.id,
       selectedDate: productionDate,
       createdAt: Date.now(),
       productionData: productionData
    };

    addDraft(newDraft);
    setFeedback('Rascunho salvo!');
    setTimeout(() => setFeedback(null), 2000);
    setViewMode('DASHBOARD');
  };

  const handleEditDraft = (draft: Draft) => {
    if (!draft.productionData) return;

    const reconstructed: {model: VaseModel, quantity: number}[] = [];
    draft.productionData.forEach(item => {
      const model = vaseModels.find(v => v.id === item.modelId);
      if (model) {
        reconstructed.push({ model, quantity: item.quantity });
      }
    });

    setDraftItems(reconstructed);
    setSelectedDate(new Date(draft.selectedDate).toISOString().split('T')[0]);

    if (reconstructed.length > 0) {
      setSelectedType(reconstructed[0].model.type);
    }

    removeDraft(draft.id); // Remove old draft to "update" it
    setViewMode('REGISTER');
  };

  const handleConfirmDraft = (draftId: string) => {
    try {
        confirmDraft(draftId);
        setFeedback('Produção confirmada!');
        setErrorFeedback(null);
        setTimeout(() => setFeedback(null), 2000);
    } catch (e: any) {
        console.error(e);
        setErrorFeedback(e.message || "Erro ao confirmar produção.");
        setTimeout(() => setErrorFeedback(null), 5000);
    }
  };

  // --- RENDERERS ---

  if (viewMode === 'SETTINGS') {
      return <EmployeeSettingsScreen onBack={() => setViewMode('DASHBOARD')} />;
