export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDarkMode: false,
      supervisorPassword: DEFAULT_SUPERVISOR_PASS,
      currentUser: null,
      currentSector: null,

      // Versioning Defaults
      systemVersion: INITIAL_VERSION,
      changelog: INITIAL_CHANGELOG,

      rawMaterialCostPerKg: 0.26,
      paintingCommissionPercentage: 10, // Default 10%

      employees: INITIAL_EMPLOYEES,
      vaseModels: INITIAL_VASES,
      productionItems: [],
      payments: [],
      drafts: [],
      systemLogs: [],
      goals: [],
      userPreferences: {},

      toggleTheme: () => set((state) => ({ isDarkMode: !state.isDarkMode })),

      setSector: (sector) => set({ currentSector: sector }),

      loginUser: (user) => {
        // Apply user theme preference on login
        const state = get();
        const userPrefs = state.userPreferences[user.id];

        // If user has saved prefs, apply theme. Else default to light (false).
        const themeToApply = userPrefs ? userPrefs.darkMode : false;

        set({ 
          currentUser: user,
          isDarkMode: themeToApply
        });
      },

      logout: () => set((state) => {
        // Log the logout action
        if (state.currentUser) {
           const newLog: SystemLog = {
            id: uuidv4(),
            timestamp: Date.now(),
            action: 'LOGOUT',
            sector: state.currentUser.sector as Sector,
            actorId: state.currentUser.id,
            actorName: state.currentUser.name,
            details: 'Sessão encerrada pelo usuário.',
          };
          return { currentUser: null, currentSector: null, systemLogs: [newLog, ...state.systemLogs] };
        }
        return { currentUser: null, currentSector: null };
      }),

      // --- SETTINGS ACTIONS ---
      updateUserPreferences: (userId, newPrefs) => set((state) => {
        const currentPrefs = state.userPreferences[userId] || { userId, ...DEFAULT_USER_PREFS };
        const updatedPrefs = { ...currentPrefs, ...newPrefs };

        // Generate Audit Log
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'SETTINGS_UPDATE',
          sector: state.currentUser?.sector as Sector || Sector.PRODUCTION, // Fallback
          actorId: userId,
          actorName: state.currentUser?.name || 'User',
          details: 'Alteração nas configurações do perfil.',
        };

        // If theme changed, apply immediately
        let newIsDarkMode = state.isDarkMode;
        if (newPrefs.darkMode !== undefined) {
           newIsDarkMode = newPrefs.darkMode;
        }

        return {
          userPreferences: {
            ...state.userPreferences,
            [userId]: updatedPrefs
          },
          isDarkMode: newIsDarkMode,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      addProductionItems: (items) => set((state) => {
        const hydratedItems = items.map(item => {
          const model = state.vaseModels.find(v => v.id === item.modelId);
          return {
            ...item,
            productionValue: model ? model.costProduction : 0,
            rawMaterialCost: model ? (model.weightKg * state.rawMaterialCostPerKg) : 0
          };
        });

        const currentUser = state.currentUser;
        const totalValue = hydratedItems.reduce((acc, i) => acc + i.productionValue, 0);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PRODUCTION',
          sector: Sector.PRODUCTION,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: hydratedItems[0]?.producedBy,
          details: `Registro de produção: ${hydratedItems.length} itens.`,
          value: totalValue
        };

        return { 
          productionItems: [...state.productionItems, ...hydratedItems],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      processStageItems: (itemIds, workerId, stage, timestamp) => set((state) => {
        let totalProcessedValue = 0;

        const updatedItems = state.productionItems.map((item) => {
          if (itemIds.includes(item.id)) {
            const model = state.vaseModels.find(v => v.id === item.modelId);

            // NOTE: CIP is preserved here (not regenerated), maintaining uniqueness.

            if (stage === 'finishing') {
              const val = model?.costFinishing || 0;
              totalProcessedValue += val;
              return {
                ...item,
                status: ItemStatus.AWAITING_PAINTING,
                updatedAt: timestamp,
                finishedBy: workerId,
                finishingValue: val
              };
            }

            if (stage === 'painting') {
               const salePrice = model?.priceSale || 0;
               // USE DYNAMIC PERCENTAGE from state
               const commission = calculatePaintingCommission(salePrice, state.paintingCommissionPercentage);

               totalProcessedValue += commission;

               return {
                ...item,
                status: ItemStatus.FINISHED,
                updatedAt: timestamp,
                paintedBy: workerId,
                paintingValue: commission
              };
            }
          }
          return item;
        });

        const currentUser = state.currentUser;
        const actionType = stage === 'finishing' ? 'FINISHING' : 'PAINTING';
        const sector = stage === 'finishing' ? Sector.FINISHING : Sector.PAINTING;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: actionType,
          sector: sector,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: workerId,
          details: `Processamento de ${itemIds.length} itens no setor ${sector}.`,
          value: totalProcessedValue
        };

        return { 
          productionItems: updatedItems,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- DRAFT ACTIONS ---
      addDraft: (draft) => set((state) => ({ drafts: [draft, ...state.drafts] })),

      removeDraft: (id) => set((state) => ({ drafts: state.drafts.filter(d => d.id !== id) })),

      confirmDraft: (draftId) => {
        const state = get();
        const draft = state.drafts.find(d => d.id === draftId);
        if (!draft) return;

        if (draft.type === 'PRODUCTION' && draft.productionData) {
          const newItems: ProductionItem[] = [];

          // --- CIP Generation Logic ---
          const draftDate = new Date(draft.selectedDate);
          const yearDigit = getYearDigit(draftDate);
          const dayOfYear = getDayOfYear(draftDate);
          const cipPrefix = `${yearDigit}${dayOfYear}`;

          // STRICT SEQUENCE LOGIC: 
          // Find max sequence currently in use for this day to avoid collisions if items were deleted.
          // We assume 'cip' is present on all recent items (for migration, old items without CIP won't collide with new structure).
          const usedSequences = state.productionItems
            .filter(item => item.cip && item.cip.startsWith(cipPrefix))
            .map(item => parseInt(item.cip!.slice(5), 10)) // Extract SS part (last 2 digits)
            .filter(n => !isNaN(n));

          let nextSequence = usedSequences.length > 0 ? Math.max(...usedSequences) + 1 : 0;

          // Process items
          for (const { modelId, quantity } of draft.productionData) {
            const model = state.vaseModels.find(v => v.id === modelId);
            if (model) {
               for (let i = 0; i < quantity; i++) {

                // Enforce Daily Limit (99 items max: 00 to 99)
                if (nextSequence > 99) {
                   throw new Error("Limite diário de produção (100 vasos) atingido para esta data. Impossível gerar novo CIP.");
                }

                const cip = `${cipPrefix}${nextSequence.toString().padStart(2, '0')}`;

                // FINAL SAFETY CHECK: Ensure CIP is globally unique
                if (state.productionItems.some(item => item.cip === cip)) {
                    throw new Error(`Erro de unicidade: O CIP ${cip} já existe no sistema.`);
                }

                nextSequence++;

                newItems.push({
                  id: uuidv4(),
                  cip: cip,
                  modelId: model.id,
                  modelName: model.name,
                  type: model.type,
                  status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
                  createdAt: draft.selectedDate,
                  updatedAt: draft.selectedDate,
                  producedBy: draft.userId,
                  productionValue: 0,
                  rawMaterialCost: 0
                });
               }
            }
          }

          if (newItems.length > 0) {
            get().addProductionItems(newItems);
          }
        } else if ((draft.type === 'FINISHING' || draft.type === 'PAINTING') && draft.processingIds) {
           // Existing items are processed, retaining their original CIP.
           const stage = draft.type === 'FINISHING' ? 'finishing' : 'painting';
           get().processStageItems(draft.processingIds, draft.userId, stage, draft.selectedDate);
        }

        get().removeDraft(draftId);
      },

      // --- GOALS ACTIONS ---
      addGoal: (goal) => set((state) => {
        const currentUser = state.currentUser;
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal.employeeId,
          details: `Meta ${goal.period} definida: ${goal.totalQuantityTarget} un. (${new Date(goal.startDate).toLocaleDateString()} - ${new Date(goal.endDate).toLocaleDateString()})`,
        };

        return {
          goals: [...state.goals, goal],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      deleteGoal: (id) => set((state) => {
        const goal = state.goals.find(g => g.id === id);
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal?.employeeId,
          details: `Meta removida.`,
        };

        return {
          goals: state.goals.filter(g => g.id !== id),
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- SUPERVISOR ACTIONS ---
      updateSupervisorPassword: (pass) => set({ supervisorPassword: pass }),

      updateRawMaterialCostPerKg: (value) => set((state) => {
        const prev = state.rawMaterialCostPerKg;
        const currentUser = state.currentUser;

        // Audit Log for Cost Change
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'ADMIN_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          details: `Custo do traço alterado de R$ ${prev.toFixed(2)} para R$ ${value.toFixed(2)}`,
        };

        return { 
           rawMaterialCostPerKg: value,
           systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      updatePaintingCommissionPercentage: (value) => set((state) => {
        const prev = state.paintingCommissionPercentage;
        const currentUser = state.currentUser;

        // Audit Log for Commission Change
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'ADMIN_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          details: `Comissão de pintura alterada de ${prev}% para ${value}%`,
        };

        return {
          paintingCommissionPercentage: value,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      addVaseModel: (model) => set((state) => ({ vaseModels: [...state.vaseModels, model] })),
      updateVaseModel: (model) => set((state) => ({
        vaseModels: state.vaseModels.map((v) => (v.id === model.id ? model : v))
      })),
      deleteVaseModel: (id) => set((state) => ({
        vaseModels: state.vaseModels.filter((v) => v.id !== id)
      })),
      addEmployee: (emp) => set((state) => ({ employees: [...state.employees, emp] })),
      updateEmployee: (emp) => set((state) => ({
        employees: state.employees.map((e) => (e.id === emp.id ? emp : e))
      })),
      addPayment: (payment) => set((state) => {
        const currentUser = state.currentUser;
        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PAYMENT',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: payment.employeeId,
          details: `Pagamento registrado para ${payment.employeeName}. Obs: ${payment.observation || '-'}`,
          value: payment.amount
        };

        return { 
          payments: [payment, ...state.payments],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      resetData: () => set({
        productionItems: [],
        payments: [],
        employees: INITIAL_EMPLOYEES,
        vaseModels: INITIAL_VASES,
        supervisorPassword: DEFAULT_SUPERVISOR_PASS,
        rawMaterialCostPerKg: 0.26,
        paintingCommissionPercentage: 10,
        drafts: [],
        systemLogs: [],
        goals: [],
        userPreferences: {},
        systemVersion: INITIAL_VERSION,
        changelog: INITIAL_CHANGELOG
      }),

      // --- VERSION CONTROL ACTIONS ---
      registerSystemUpdate: (type: ChangeType, description: string) => set((state) => {
        const parts = state.systemVersion.split('.').map(Number);
        if (parts.length !== 3) return state;

        let [major, minor, patch] = parts;

        switch (type) {
          case 'MAJOR': major++; minor = 0; patch = 0; break;
          case 'FEATURE': minor++; patch = 0; break;
          case 'IMPROVEMENT': case 'FIX': patch++; break;
        }

        const newVersion = `${major}.${minor}.${patch}`;

        const newEntry: ChangelogEntry = {
          version: newVersion,
          date: Date.now(),
          type,
          description
        };

        if (state.changelog.length > 0 && state.changelog[0].description === description) {
           return state;
        }

        return {
          systemVersion: newVersion,
          changelog: [newEntry, ...state.changelog]
        };
      })
    }),
    {
      name: 'home-pots-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

import { ProductionItem, PaymentRecord, VaseModel, Sector } from '../types';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

// Configuração básica de cores e layout
const PRIMARY_COLOR = '#0061a4';
const SECONDARY_COLOR = '#535f70';
const ACCENT_COLOR = '#d1e4ff';

const formatCurrency = (val: number) => `R$ ${val.toFixed(2).replace('.', ',')}`;
const formatDate = (timestamp: number) => new Date(timestamp).toLocaleDateString('pt-BR');

// --- Helper Functions ---

const addHeader = (doc: jsPDF, title: string, subtitle: string, systemVersion: string) => {
    doc.setFillColor(PRIMARY_COLOR);
    doc.rect(0, 0, 210, 20, 'F');

    doc.setTextColor(255, 255, 255);
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text("HOME POTS MANAGER", 105, 13, { align: 'center' });

    doc.setTextColor(0, 0, 0);
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.text(title, 14, 30);

    doc.setFontSize(10);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(80, 80, 80);
    doc.text(subtitle, 14, 36);

    doc.line(14, 40, 196, 40); // Horizontal line
};

const addFooter = (doc: jsPDF, systemVersion: string) => {
    const pageCount = doc.getNumberOfPages();
    for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(150, 150, 150);
        doc.text(
            `Gerado em ${new Date().toLocaleString('pt-BR')} - v${systemVersion} - Página ${i} de ${pageCount}`,
            105,
            290,
            { align: 'center' }
        );
    }
};

// --- Employee Reports ---

export const exportEmployeePDF = (
    items: ProductionItem[],
    payments: PaymentRecord[],
    employeeName: string,
    sector: string,
    systemVersion: string,
    valueKey: 'productionValue' | 'finishingValue' | 'paintingValue'
) => {
    const doc = new jsPDF();
    const title = `Relatório de Produção - ${employeeName}`;
    const subtitle = `Setor: ${sector} | Total de Registros: ${items.length + payments.length}`;

    addHeader(doc, title, subtitle, systemVersion);

    // 1. Tabela de Produção
    const prodTotal = items.reduce((acc, i) => acc + (i[valueKey] || 0), 0);
    const prodBody = items.map(item => [
        formatDate(item.updatedAt),
        item.cip || 'N/A',
        item.modelName,
        item.type,
        formatCurrency(item[valueKey] || 0)
    ]);

    doc.setFontSize(11);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(0, 0, 0);
    doc.text("Histórico de Produção", 14, 48);

    autoTable(doc, {
        startY: 50,
        head: [['Data', 'CIP', 'Modelo', 'Tipo', 'Valor']],
        body: prodBody,
        theme: 'striped',
        headStyles: { fillColor: PRIMARY_COLOR },
        foot: [['', '', '', 'TOTAL', formatCurrency(prodTotal)]],
        footStyles: { fillColor: SECONDARY_COLOR, fontStyle: 'bold' }
    });

    // 2. Tabela de Pagamentos
    const payTotal = payments.reduce((acc, p) => acc + p.amount, 0);
    const payBody = payments.map(p => [
        formatDate(p.date),
        p.observation || '-',
        formatCurrency(p.amount)
    ]);

    let finalY = (doc as any).lastAutoTable.finalY || 50;

    doc.text("Histórico de Pagamentos", 14, finalY + 15);

    autoTable(doc, {
        startY: finalY + 18,
        head: [['Data', 'Observação', 'Valor Recebido']],
        body: payBody,
        theme: 'striped',
        headStyles: { fillColor: [0, 100, 0] }, // Greenish for payments
        foot: [['', 'TOTAL RECEBIDO', formatCurrency(payTotal)]],
        footStyles: { fillColor: SECONDARY_COLOR, fontStyle: 'bold' }
    });

    // 3. Resumo Financeiro
    finalY = (doc as any).lastAutoTable.finalY + 15;

    // Check page break for summary
    if (finalY > 250) {
        doc.addPage();
        finalY = 20;
    }

    const balance = prodTotal - payTotal;

    doc.setFillColor(240, 240, 240);
    doc.roundedRect(14, finalY, 180, 30, 3, 3, 'F');

    doc.setFontSize(12);
    doc.text("RESUMO FINANCEIRO", 105, finalY + 8, { align: 'center' });

    doc.setFontSize(10);
    doc.text(`Total Produzido: ${formatCurrency(prodTotal)}`, 20, finalY + 18);
    doc.text(`Total Pago: ${formatCurrency(payTotal)}`, 20, finalY + 24);

    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(balance >= 0 ? 0 : 200, balance >= 0 ? 100 : 0, 0); // Green if positive, Red if negative
    doc.text(`Saldo a Receber: ${formatCurrency(balance)}`, 180, finalY + 20, { align: 'right' });

    addFooter(doc, systemVersion);
    doc.save(`relatorio_colaborador_${employeeName.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.pdf`);
};

// --- Supervisor Reports ---

export const exportSupervisorPDF = (
    items: ProductionItem[],
    payments: PaymentRecord[],
    filterLabel: string,
    systemVersion: string,
    reportType: 'production' | 'financial'
) => {
    const doc = new jsPDF();
    const title = reportType === 'production' ? "Relatório Geral de Produção" : "Relatório Financeiro Consolidado";
    const subtitle = `Filtros: ${filterLabel}`;

    addHeader(doc, title, subtitle, systemVersion);

    if (reportType === 'production') {
        const body = items.map(item => {
            const totalItemCost = item.productionValue + (item.finishingValue || 0) + (item.paintingValue || 0) + item.rawMaterialCost;
            return [
                formatDate(item.createdAt),
                item.cip || 'N/A',
                item.modelName,
                item.type,
                formatCurrency(item.rawMaterialCost),
                formatCurrency(item.productionValue),
                formatCurrency(item.finishingValue || 0),
                formatCurrency(item.paintingValue || 0),
                formatCurrency(totalItemCost)
            ];
        });

        // Calculate totals
        const totalMat = items.reduce((a, b) => a + b.rawMaterialCost, 0);
        const totalProd = items.reduce((a, b) => a + b.productionValue, 0);
        const totalFin = items.reduce((a, b) => a + (b.finishingValue || 0), 0);
        const totalPaint = items.reduce((a, b) => a + (b.paintingValue || 0), 0);
        const grandTotal = totalMat + totalProd + totalFin + totalPaint;

        autoTable(doc, {
            startY: 45,
            head: [['Data', 'CIP', 'Modelo', 'Tipo', 'Matéria', 'Prod.', 'Acab.', 'Pint.', 'Total']],
            body: body,
            styles: { fontSize: 7 },
            headStyles: { fillColor: PRIMARY_COLOR, fontSize: 8 },
            foot: [['TOTAL', '', '', '', formatCurrency(totalMat), formatCurrency(totalProd), formatCurrency(totalFin), formatCurrency(totalPaint), formatCurrency(grandTotal)]],
            footStyles: { fillColor: SECONDARY_COLOR, fontSize: 8, fontStyle: 'bold' }
        });

    } else {
        // Financial Report (Payments)
        const body = payments.map(p => [
            formatDate(p.date),
            p.employeeName,
            p.sector,
            p.observation || '-',
            formatCurrency(p.amount)
        ]);

        const totalPaid = payments.reduce((a, b) => a + b.amount, 0);

        autoTable(doc, {
            startY: 45,
            head: [['Data', 'Colaborador', 'Setor', 'Obs.', 'Valor']],
            body: body,
            headStyles: { fillColor: PRIMARY_COLOR },
            foot: [['', '', '', 'TOTAL PAGO', formatCurrency(totalPaid)]],
            footStyles: { fillColor: SECONDARY_COLOR, fontStyle: 'bold' }
        });
    }

    addFooter(doc, systemVersion);
    doc.save(`relatorio_supervisor_${reportType}_${new Date().toISOString().split('T')[0]}.pdf`);
};

