     if (!editingModel.name || !editingModel.type || !editingModel.costProduction || !editingModel.weightKg) return;

     if (editingModel.id) {
       updateVaseModel(editingModel as VaseModel);
     } else {
       addVaseModel({ ...editingModel, id: uuidv4() } as VaseModel);
     }
     setIsEditModalOpen(false);
  };

  return (
    <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-500">
