          <Plus className="mr-1 w-4 h-4" /> Novo
        </Button>
      </div>

      <div className="grid gap-3">
        {vaseModels.map(model => (
          <div key={model.id} className="bg-surface p-4 rounded-2xl shadow-sm border border-outline-variant hover:shadow-md transition-shadow">
            <div className="flex justify-between items-start mb-3">
              <div>
                <div className="flex items-center gap-2 mb-1">
