                <div className="flex justify-between">
                  <span className="text-on-surface-variant">Custo Matéria</span>
                  <span className="font-medium text-on-surface">R$ {calculateRawMaterialCost(model.weightKg, rawMaterialCostPerKg).toFixed(2)}</span>
                </div>
                <div className="col-span-2 border-t border-outline-variant my-1"></div>
                <div className="flex justify-between">
                  <span className="text-on-surface-variant">Mão de Obra</span>
                  <span className="font-medium text-on-surface">R$ {model.costProduction.toFixed(2)}</span>
                </div>
                {model.type === VaseType.WITH_SHELL && (
                  <>
                    <div className="flex justify-between">
                      <span className="text-on-surface-variant">Acab.</span>
                      <span className="font-medium text-on-surface">R$ {(model.costFinishing || 0).toFixed(2)}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-on-surface-variant">Pint. ({paintingCommissionPercentage}%)</span>
                      <span className="font-medium text-primary">R$ {calculatePaintingCommission(model.priceSale || 0, paintingCommissionPercentage).toFixed(2)}</span>
                    </div>
                    <div className="flex justify-between col-span-2 pt-2 mt-1 border-t border-outline-variant">
