                       <span className="font-bold text-success">R$ {(model.priceSale || 0).toFixed(2)}</span>
                    </div>
                  </>
                )}
            </div>
          </div>
        ))}
      </div>

      <Modal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} title="Editar Modelo" footer={
