                   Custo: R$ {calculateRawMaterialCost(editingModel.weightKg || 0, rawMaterialCostPerKg).toFixed(2)}
                </div>
             </div>
           </div>
           <div className="grid grid-cols-2 gap-4">
              <div>
                 <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Mão de Obra (Prod.)</label>
                 <input type="number" className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary" value={editingModel.costProduction || ''} onChange={e => setEditingModel({...editingModel, costProduction: parseFloat(e.target.value)})} />
              </div>
              {editingModel.type === VaseType.WITH_SHELL && (
                <>
                  <div>
                    <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Custo Acab.</label>
                    <input type="number" className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary" value={editingModel.costFinishing || ''} onChange={e => setEditingModel({...editingModel, costFinishing: parseFloat(e.target.value)})} />
                  </div>
                  <div className="col-span-2">
                    <label className="text-xs font-bold text-on-surface-variant uppercase tracking-wider mb-1 block">Preço de Venda</label>
                    <input type="number" className="w-full p-3 bg-surface border border-outline-variant rounded-xl text-on-surface focus:outline-none focus:ring-2 focus:ring-primary" value={editingModel.priceSale || ''} onChange={e => setEditingModel({...editingModel, priceSale: parseFloat(e.target.value)})} />
                  </div>
                </>
              )}
           </div>
         </div>
      </Modal>
    </div>
  );
};

