const DEFAULT_USER_PREFS: Omit<UserPreferences, 'userId'> = {
  darkMode: false,
  notifySystem: true,
  notifyGoals: true,
  notifyPayments: true,
  showFinancials: true,
  showProductionQty: true,
  showGoalsBar: true,
