// Helper to get active period
const getActivePeriod = (periods: Period[]) => periods.find(p => p.status === 'ACTIVE');

export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDarkMode: false,
      supervisorPassword: DEFAULT_SUPERVISOR_PASS,
      currentUser: null,
      currentSector: null,

      // Versioning Defaults
      systemVersion: INITIAL_VERSION,
      changelog: INITIAL_CHANGELOG,

      rawMaterialCostPerKg: 0.26,
      paintingCommissionPercentage: 10, // Default 10%

      // Data
      periods: [],
      activePeriodId: null,

      employees: INITIAL_EMPLOYEES,
      vaseModels: INITIAL_VASES,
      productionItems: [],
      payments: [],
      drafts: [],
      systemLogs: [],
      goals: [],
      userPreferences: {},

      toggleTheme: () => set((state) => ({ isDarkMode: !state.isDarkMode })),

      setSector: (sector) => set({ currentSector: sector }),

      loginUser: (user) => {
        const state = get();
        const userPrefs = state.userPreferences[user.id];

        // MIGRATION: Ensure a period exists on login if none exists
        if (state.periods.length === 0) {
           const initialPeriodId = uuidv4();
           const now = new Date();
           const name = `${now.toLocaleString('default', { month: 'short' })}/${now.getFullYear()} (Inicial)`;
           set({
             periods: [{
               id: initialPeriodId,
               name: name,
               startDate: Date.now(),
               status: 'ACTIVE'
             }],
             activePeriodId: initialPeriodId
           });
        }

        const themeToApply = userPrefs ? userPrefs.darkMode : false;

        set({ 
          currentUser: user,
          isDarkMode: themeToApply
        });
      },

      logout: () => set((state) => {
        if (state.currentUser) {
           const newLog: SystemLog = {
            id: uuidv4(),
            timestamp: Date.now(),
            action: 'LOGOUT',
            sector: state.currentUser.sector as Sector,
            actorId: state.currentUser.id,
            actorName: state.currentUser.name,
            details: 'Sessão encerrada pelo usuário.',
          };
          return { currentUser: null, currentSector: null, systemLogs: [newLog, ...state.systemLogs] };
        }
        return { currentUser: null, currentSector: null };
      }),

      // --- PERIOD ACTIONS ---
      closePeriod: (supervisorId) => set((state) => {
        const activePeriod = state.periods.find(p => p.status === 'ACTIVE');
        if (!activePeriod) return state;

        const now = Date.now();
        const newPeriodId = uuidv4();
        const dateObj = new Date();
        // Generate next month name logic or simple sequential
        const nextName = `${dateObj.toLocaleString('default', { month: 'short' })}/${dateObj.getFullYear()} - #${state.periods.length + 1}`;

        const updatedPeriods = state.periods.map(p => 
          p.id === activePeriod.id 
            ? { ...p, status: 'CLOSED' as const, endDate: now, closedBy: supervisorId }
            : p
        );

        const newPeriod: Period = {
          id: newPeriodId,
          name: nextName,
          startDate: now,
          status: 'ACTIVE'
        };

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: now,
          action: 'PERIOD_CLOSE',
          sector: Sector.SUPERVISOR,
          actorId: supervisorId,
          actorName: 'Supervisor',
          details: `Período ${activePeriod.name} fechado. Início de: ${newPeriod.name}`
        };

        return {
          periods: [...updatedPeriods, newPeriod],
          activePeriodId: newPeriodId,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- SETTINGS ACTIONS ---
      updateUserPreferences: (userId, newPrefs) => set((state) => {
        const currentPrefs = state.userPreferences[userId] || { userId, ...DEFAULT_USER_PREFS };
        const updatedPrefs = { ...currentPrefs, ...newPrefs };

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'SETTINGS_UPDATE',
          sector: state.currentUser?.sector as Sector || Sector.PRODUCTION,
          actorId: userId,
          actorName: state.currentUser?.name || 'User',
          details: 'Alteração nas configurações do perfil.',
        };

        let newIsDarkMode = state.isDarkMode;
        if (newPrefs.darkMode !== undefined) {
           newIsDarkMode = newPrefs.darkMode;
        }

        return {
          userPreferences: {
            ...state.userPreferences,
            [userId]: updatedPrefs
          },
          isDarkMode: newIsDarkMode,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      addProductionItems: (items) => set((state) => {
        // Ensure active period ID is attached
        const activeId = state.activePeriodId || (state.periods.find(p => p.status === 'ACTIVE')?.id);

        const hydratedItems = items.map(item => {
          const model = state.vaseModels.find(v => v.id === item.modelId);
          return {
            ...item,
            periodId: activeId, // Bind to current period
            productionValue: model ? model.costProduction : 0,
            rawMaterialCost: model ? (model.weightKg * state.rawMaterialCostPerKg) : 0
          };
        });

        const currentUser = state.currentUser;
        const totalValue = hydratedItems.reduce((acc, i) => acc + i.productionValue, 0);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PRODUCTION',
          sector: Sector.PRODUCTION,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: hydratedItems[0]?.producedBy,
          details: `Registro de produção: ${hydratedItems.length} itens.`,
          value: totalValue
        };

        return { 
          productionItems: [...state.productionItems, ...hydratedItems],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      processStageItems: (itemIds, workerId, stage, timestamp) => set((state) => {
        let totalProcessedValue = 0;
        const activeId = state.activePeriodId || (state.periods.find(p => p.status === 'ACTIVE')?.id);

        const updatedItems = state.productionItems.map((item) => {
          if (itemIds.includes(item.id)) {
            const model = state.vaseModels.find(v => v.id === item.modelId);

            // STRICT FLOW CONTROL: FINISHING -> PAINTING
            if (stage === 'finishing') {
              if (item.status !== ItemStatus.AWAITING_FINISHING) {
                 return item;
              }

              const val = model?.costFinishing || 0;
              totalProcessedValue += val;

              return {
                ...item, 
                status: ItemStatus.AWAITING_PAINTING, 
                updatedAt: timestamp,
                finishedBy: workerId,
                finishedInPeriodId: activeId, // Track when it was finished
                finishingValue: val
              };
            }

            // STRICT FLOW CONTROL: PAINTING -> FINISHED
            if (stage === 'painting') {
               if (item.status !== ItemStatus.AWAITING_PAINTING) {
                  return item;
               }

               const salePrice = model?.priceSale || 0;
               const commission = calculatePaintingCommission(salePrice, state.paintingCommissionPercentage);

               totalProcessedValue += commission;

               return {
                ...item, 
                status: ItemStatus.FINISHED, 
                updatedAt: timestamp,
                paintedBy: workerId,
                paintedInPeriodId: activeId, // Track when it was painted
                paintingValue: commission
              };
            }
          }
          return item;
        });

        const currentUser = state.currentUser;
        const actionType = stage === 'finishing' ? 'FINISHING' : 'PAINTING';
        const sector = stage === 'finishing' ? Sector.FINISHING : Sector.PAINTING;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: actionType,
          sector: sector,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: workerId,
          details: `Processamento de ${itemIds.length} itens no setor ${sector}.`,
          value: totalProcessedValue
        };

        return { 
          productionItems: updatedItems,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- DRAFT ACTIONS ---
      addDraft: (draft) => set((state) => ({ drafts: [draft, ...state.drafts] })),

      removeDraft: (id) => set((state) => ({ drafts: state.drafts.filter(d => d.id !== id) })),

      confirmDraft: (draftId) => {
        const state = get();
        const draft = state.drafts.find(d => d.id === draftId);
        if (!draft) return;

        // Ensure active period exists before confirming
        let activeId = state.activePeriodId;
        if (!activeId && state.periods.length === 0) {
           // Fallback init if empty (should be handled in login, but safe guard)
           const pid = uuidv4();
           set({ periods: [{ id: pid, name: 'Inicial', startDate: Date.now(), status: 'ACTIVE' }], activePeriodId: pid });
           activeId = pid;
        }

        if (draft.type === 'PRODUCTION' && draft.productionData) {
          const newItems: ProductionItem[] = [];

          const draftDate = new Date(draft.selectedDate);
          const yearDigit = getYearDigit(draftDate);
          const dayOfYear = getDayOfYear(draftDate);
          const cipPrefix = `${yearDigit}${dayOfYear}`;

          const usedSequences = state.productionItems
            .filter(item => item.cip && item.cip.startsWith(cipPrefix))
            .map(item => parseInt(item.cip!.slice(5), 10))
            .filter(n => !isNaN(n));

          let nextSequence = usedSequences.length > 0 ? Math.max(...usedSequences) + 1 : 0;

          for (const { modelId, quantity } of draft.productionData) {
            const model = state.vaseModels.find(v => v.id === modelId);
            if (model) {
               for (let i = 0; i < quantity; i++) {

                if (nextSequence > 99) {
                   throw new Error("Limite diário de produção (100 vasos) atingido para esta data. Impossível gerar novo CIP.");
                }

                const cip = `${cipPrefix}${nextSequence.toString().padStart(2, '0')}`;

                if (state.productionItems.some(item => item.cip === cip)) {
                    throw new Error(`Erro de unicidade: O CIP ${cip} já existe no sistema.`);
                }

                nextSequence++;

                newItems.push({
                  id: uuidv4(),
                  cip: cip,
                  modelId: model.id,
                  modelName: model.name,
                  type: model.type,
                  status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
                  createdAt: draft.selectedDate,
                  updatedAt: draft.selectedDate,
                  producedBy: draft.userId,
                  periodId: activeId || undefined, // Bind to active period
                  productionValue: 0,
                  rawMaterialCost: 0
                });
               }
            }
          }

          if (newItems.length > 0) {
            get().addProductionItems(newItems);
          }
        } else if ((draft.type === 'FINISHING' || draft.type === 'PAINTING') && draft.processingIds) {
           const stage = draft.type === 'FINISHING' ? 'finishing' : 'painting';
           get().processStageItems(draft.processingIds, draft.userId, stage, draft.selectedDate);
        }

        get().removeDraft(draftId);
      },

      // --- GOALS ACTIONS ---
      addGoal: (goal) => set((state) => {
        const currentUser = state.currentUser;
        const activeId = state.activePeriodId || (state.periods.find(p => p.status === 'ACTIVE')?.id);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal.employeeId,
          details: `Meta ${goal.period} definida.`,
        };

        return {
          goals: [...state.goals, { ...goal, periodId: activeId }], // Bind goal to period
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      deleteGoal: (id) => set((state) => {
        const goal = state.goals.find(g => g.id === id);
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal?.employeeId,
          details: `Meta removida.`,
        };

        return {
          goals: state.goals.filter(g => g.id !== id),
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- SUPERVISOR ACTIONS ---
      updateSupervisorPassword: (pass) => set({ supervisorPassword: pass }),

      updateRawMaterialCostPerKg: (value) => set((state) => {
        const prev = state.rawMaterialCostPerKg;
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'ADMIN_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          details: `Custo do traço alterado de R$ ${prev.toFixed(2)} para R$ ${value.toFixed(2)}`,
        };

        return { 
           rawMaterialCostPerKg: value,
           systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      updatePaintingCommissionPercentage: (value) => set((state) => {
        const prev = state.paintingCommissionPercentage;
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'ADMIN_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          details: `Comissão de pintura alterada de ${prev}% para ${value}%`,
        };

        return {
          paintingCommissionPercentage: value,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      addVaseModel: (model) => set((state) => ({ vaseModels: [...state.vaseModels, model] })),
      updateVaseModel: (model) => set((state) => ({
        vaseModels: state.vaseModels.map((v) => (v.id === model.id ? model : v))
      })),
      deleteVaseModel: (id) => set((state) => ({
        vaseModels: state.vaseModels.filter((v) => v.id !== id)
      })),
      addEmployee: (emp) => set((state) => ({ employees: [...state.employees, emp] })),
      updateEmployee: (emp) => set((state) => ({
        employees: state.employees.map((e) => (e.id === emp.id ? emp : e))
      })),
      addPayment: (payment) => set((state) => {
        const currentUser = state.currentUser;
        const activeId = state.activePeriodId || (state.periods.find(p => p.status === 'ACTIVE')?.id);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PAYMENT',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: payment.employeeId,
          details: `Pagamento registrado para ${payment.employeeName}. Obs: ${payment.observation || '-'}`,
          value: payment.amount
        };

        return { 
          payments: [ { ...payment, periodId: activeId }, ...state.payments],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // Deprecated in favor of Period System, but logic kept to clear local state if needed manually (dev)
      resetData: () => set({
        productionItems: [],
        payments: [],
        employees: INITIAL_EMPLOYEES,
        vaseModels: INITIAL_VASES,
        supervisorPassword: DEFAULT_SUPERVISOR_PASS,
        rawMaterialCostPerKg: 0.26,
        paintingCommissionPercentage: 10,
        drafts: [],
        systemLogs: [],
        goals: [],
        userPreferences: {},
        periods: [],
        activePeriodId: null,
        systemVersion: INITIAL_VERSION,
        changelog: INITIAL_CHANGELOG
      }),

      // --- VERSION CONTROL ACTIONS ---
      registerSystemUpdate: (type: ChangeType, description: string) => set((state) => {
        const parts = state.systemVersion.split('.').map(Number);
        if (parts.length !== 3) return state;

        let [major, minor, patch] = parts;

        switch (type) {
          case 'MAJOR': major++; minor = 0; patch = 0; break;
          case 'FEATURE': minor++; patch = 0; break;
          case 'IMPROVEMENT': case 'FIX': patch++; break;
        }

        const newVersion = `${major}.${minor}.${patch}`;

        const newEntry: ChangelogEntry = {
          version: newVersion,
          date: Date.now(),
          type,
          description
        };

        if (state.changelog.length > 0 && state.changelog[0].description === description) {
           return state;
        }

        return {
          systemVersion: newVersion,
          changelog: [newEntry, ...state.changelog]
        };
      })
    }),
    {
      name: 'home-pots-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { Button, Card, Modal, cn, Badge } from '../components/UI';
import { 
  Box, Users, Settings, 
  Moon, LogOut, Trash, Plus, Pencil, 
  CheckCircle2, XCircle, DollarSign, Wallet, Scale,
  Calendar as CalendarIcon, PaintBucket, Hammer, Brush, Box as BoxIcon,
  FileDown, Filter, History, Bug, Star, Zap, Activity, FileSearch, Target, Minus, Percent,
  BarChart3, User as UserIcon, ChevronDown, Package, Search, ChevronRight, X, AlertTriangle, RefreshCcw, LayoutList, LayoutGrid
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';
import { VaseType, VaseModel, Sector, Employee, ItemStatus, PaymentRecord, Goal, GoalPeriod, GoalModelTarget, ProductionItem } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { exportSupervisorPDF } from '../utils/csvHelper';
import { calculateRawMaterialCost, calculatePaintingCommission } from '../utils/calculations';

// --- ANALYTICS TAB ---
const AnalyticsTab = () => {
  const { productionItems, employees, goals, activePeriodId, periods } = useStore();
  const [timeRange, setTimeRange] = useState<'day' | 'week' | 'month'>('month');
  const [sectorFilter, setSectorFilter] = useState<'all' | Sector>(Sector.PRODUCTION);
  const [expandedEmployeeId, setExpandedEmployeeId] = useState<string | null>(null);

  const activePeriodName = periods.find(p => p.id === activePeriodId)?.name || 'Desconhecido';

  // 1. Data Filtering
  const filteredData = useMemo(() => {
    // START: Filter by ACTIVE PERIOD first
    let items = productionItems.filter(i => 
       i.periodId === activePeriodId || 
       i.finishedInPeriodId === activePeriodId || 
       i.paintedInPeriodId === activePeriodId
    );

    const now = new Date();
    let startTime = 0;

    if (timeRange === 'day') startTime = new Date(now.setHours(0,0,0,0)).getTime();
    else if (timeRange === 'week') {
      const d = new Date();
      d.setDate(d.getDate() - 7);
      startTime = d.setHours(0,0,0,0);
    } else {
      const d = new Date();
      d.setDate(d.getDate() - 30);
      startTime = d.setHours(0,0,0,0);
    }

    // Secondary Filter: Time Range within the period
    items = items.filter(i => {
      // Use updatedAt for finishing/painting to catch recent activity
      const referenceTime = i.updatedAt; 
      return referenceTime >= startTime;
    });

    return { items, startTime };
  }, [productionItems, timeRange, activePeriodId]);

  // 2. Aggregate Calculations
  const metrics = useMemo(() => {
    const { items } = filteredData;

    // Financials by Sector
    let prodCost = 0, finishCost = 0, paintCost = 0;
    let prodQty = 0, finishQty = 0, paintQty = 0;

    items.forEach(i => {
      // Only count cost if it belongs to this period
      if (i.periodId === activePeriodId) {
         prodCost += i.productionValue || 0;
         prodQty += 1;
      }

      if (i.finishingValue && i.finishedInPeriodId === activePeriodId) {
        finishCost += i.finishingValue;
        finishQty += 1;
      }
      if (i.paintingValue && i.paintedInPeriodId === activePeriodId) {
        paintCost += i.paintingValue;
        paintQty += 1;
      }
    });

    return {
      costs: { production: prodCost, finishing: finishCost, painting: paintCost, total: prodCost + finishCost + paintCost },
      volume: { production: prodQty, finishing: finishQty, painting: paintQty }
    };
  }, [filteredData, activePeriodId]);

  // 3. Employee Performance List
  const employeePerformance = useMemo(() => {
    const { items } = filteredData;
    const activeEmployees = employees.filter(e => e.active && (sectorFilter === 'all' || e.sector === sectorFilter));

    return activeEmployees.map(emp => {
      // Calculate Stats
      let earned = 0;
      let qty = 0;

      items.forEach(i => {
        if (emp.sector === Sector.PRODUCTION && i.producedBy === emp.id && i.periodId === activePeriodId) {
          earned += i.productionValue;
          qty++;
        } else if (emp.sector === Sector.FINISHING && i.finishedBy === emp.id && i.finishedInPeriodId === activePeriodId) {
          earned += i.finishingValue || 0;
          qty++;
        } else if (emp.sector === Sector.PAINTING && i.paintedBy === emp.id && i.paintedInPeriodId === activePeriodId) {
          earned += i.paintingValue || 0;
          qty++;
        }
      });

      // Find active goal
      const empGoals = goals.filter(g => g.employeeId === emp.id && g.periodId === activePeriodId);
      const activeGoal = empGoals.sort((a,b) => b.createdAt - a.createdAt)[0];
      const goalTarget = activeGoal ? activeGoal.totalQuantityTarget : 0;
      const goalPercent = goalTarget > 0 ? Math.round((qty / goalTarget) * 100) : 0;

      return {
        ...emp,
        earned,
        qty,
        goalTarget,
        goalPercent
      };
    }).sort((a, b) => b.earned - a.earned); // Sort by earnings
  }, [employees, filteredData, goals, sectorFilter, activePeriodId]);

  // Chart Data Preparation
  const chartData = [
    { name: 'Produção', custo: metrics.costs.production, volume: metrics.volume.production },
    { name: 'Acabamento', custo: metrics.costs.finishing, volume: metrics.volume.finishing },
    { name: 'Pintura', custo: metrics.costs.painting, volume: metrics.volume.painting },
  ];

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-500 pb-8">
      {/* Top Header & Filters */}
      <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 px-1">
         <div>
            <div className="flex items-center gap-2">
               <h2 className="text-2xl font-normal text-on-background">Relatórios</h2>
               <Badge color="green">{activePeriodName}</Badge>
            </div>
            <p className="text-sm text-on-surface-variant">Análise detalhada do período ativo</p>
         </div>

         <div className="flex flex-wrap gap-2">
            <div className="bg-surface p-1 rounded-xl flex border border-outline-variant">
               {(['day', 'week', 'month'] as const).map((r) => (
                 <button key={r} onClick={() => setTimeRange(r)} className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${timeRange === r ? 'bg-primary text-on-primary shadow-sm' : 'text-on-surface-variant hover:bg-surface-variant'}`}>
                    {r === 'day' ? 'Dia' : r === 'week' ? 'Semana' : 'Mês'}
                 </button>
               ))}
            </div>

            <select 
               value={sectorFilter} 
               onChange={(e) => setSectorFilter(e.target.value as any)}
               className="bg-surface border border-outline-variant text-on-surface text-sm rounded-xl p-2 px-4 focus:ring-2 focus:ring-primary outline-none"
            >
               <option value="all">Todos os Setores</option>
               <option value={Sector.PRODUCTION}>Produção</option>
               <option value={Sector.FINISHING}>Acabamento</option>
               <option value={Sector.PAINTING}>Pintura</option>
            </select>
         </div>
      </div>

      {/* Block 1: General Indicators */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
         <Card className="bg-surface border-outline-variant flex items-center gap-4">
            <div className="bg-primary-container p-3 rounded-full text-on-primary-container">
               <DollarSign className="w-6 h-6" />
            </div>
            <div>
               <p className="text-xs font-bold text-on-surface-variant uppercase">Custo Total (Período)</p>
               <p className="text-2xl font-bold text-on-surface">R$ {metrics.costs.total.toFixed(2)}</p>
            </div>
         </Card>
         <Card className="bg-surface border-outline-variant flex items-center gap-4">
            <div className="bg-secondary-container p-3 rounded-full text-on-secondary-container">
               <BoxIcon className="w-6 h-6" />
            </div>
            <div>
               <p className="text-xs font-bold text-on-surface-variant uppercase">Volume Processado</p>
               <p className="text-2xl font-bold text-on-surface">
                  {metrics.volume.production + metrics.volume.finishing + metrics.volume.painting} <span className="text-sm font-normal text-on-surface-variant">itens</span>
               </p>
            </div>
         </Card>
         <Card className="bg-surface border-outline-variant flex items-center gap-4">
            <div className="bg-tertiary-container p-3 rounded-full text-on-tertiary-container">
               <Target className="w-6 h-6" />
            </div>
            <div>
               <p className="text-xs font-bold text-on-surface-variant uppercase">Média de Metas</p>
               <p className="text-2xl font-bold text-on-surface">
                  {Math.round(employeePerformance.reduce((acc, e) => acc + e.goalPercent, 0) / (employeePerformance.length || 1))}%
               </p>
            </div>
         </Card>
      </div>

      {/* Block 2: Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
         <Card className="h-80 flex flex-col pt-6 px-2 bg-surface border-outline-variant">
            <h3 className="text-sm font-bold text-on-surface-variant uppercase px-4 mb-2 flex items-center gap-2"><BarChart3 className="w-4 h-4" /> Custo por Setor</h3>
            <div className="flex-1 w-full min-h-0">
               <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                     <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--color-outline-variant)" opacity={0.3} />
                     <XAxis dataKey="name" tick={{fontSize: 12, fill: 'var(--color-on-surface-variant)'}} axisLine={false} tickLine={false} />
                     <YAxis tick={{fontSize: 12, fill: 'var(--color-on-surface-variant)'}} axisLine={false} tickLine={false} />
                     <Tooltip 
                        cursor={{fill: 'var(--color-surface-variant)'}}
                        contentStyle={{ borderRadius: '12px', border: '1px solid var(--color-outline-variant)', backgroundColor: 'rgb(var(--color-surface))' }}
                        formatter={(val: number) => `R$ ${val.toFixed(2)}`}
                     />
                     <Bar dataKey="custo" fill="rgb(var(--color-primary))" radius={[4, 4, 0, 0]} barSize={40} />
                  </BarChart>
               </ResponsiveContainer>
            </div>
         </Card>

         <Card className="h-80 flex flex-col pt-6 px-2 bg-surface border-outline-variant">
            <h3 className="text-sm font-bold text-on-surface-variant uppercase px-4 mb-2 flex items-center gap-2"><Activity className="w-4 h-4" /> Volume por Setor</h3>
            <div className="flex-1 w-full min-h-0">
               <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                     <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--color-outline-variant)" opacity={0.3} />
                     <XAxis dataKey="name" tick={{fontSize: 12, fill: 'var(--color-on-surface-variant)'}} axisLine={false} tickLine={false} />
                     <YAxis tick={{fontSize: 12, fill: 'var(--color-on-surface-variant)'}} axisLine={false} tickLine={false} />
                     <Tooltip 
                        cursor={{fill: 'var(--color-surface-variant)'}}
                        contentStyle={{ borderRadius: '12px', border: '1px solid var(--color-outline-variant)', backgroundColor: 'rgb(var(--color-surface))' }}
                     />
                     <Bar dataKey="volume" fill="rgb(var(--color-secondary))" radius={[4, 4, 0, 0]} barSize={40} />
                  </BarChart>
               </ResponsiveContainer>
            </div>
         </Card>
      </div>

      {/* Block 3: Individual Performance */}
      <div>
         <h3 className="text-lg font-bold text-on-surface mb-4 px-1 flex items-center gap-2">
            <Users className="w-5 h-5 text-primary" /> Desempenho Individual
         </h3>

         <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
            {employeePerformance.map(emp => (
               <Card 
                  key={emp.id} 
                  className={`bg-surface border-outline-variant transition-all cursor-pointer hover:shadow-md ${expandedEmployeeId === emp.id ? 'ring-2 ring-primary' : ''}`}
                  onClick={() => setExpandedEmployeeId(expandedEmployeeId === emp.id ? null : emp.id)}
