                           <div className="flex justify-between">
                              <span className="text-on-surface-variant">Status:</span>
                              <span className={`font-bold ${emp.active ? 'text-success' : 'text-error'}`}>{emp.active ? 'Ativo' : 'Inativo'}</span>
