    isDarkMode, toggleTheme, logout, systemVersion 
  } = useStore();

  const [confirmClosePeriod, setConfirmClosePeriod] = useState(false);
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
