export const useStore = create<AppState>()(
  persist(
    (set, get) => ({
      isDarkMode: false,
      supervisorPassword: DEFAULT_SUPERVISOR_PASS,
      currentUser: null,
      currentSector: null,

      // Versioning Defaults
      systemVersion: INITIAL_VERSION,
      changelog: INITIAL_CHANGELOG,

      rawMaterialCostPerKg: 0.26,
      paintingCommissionPercentage: 10, // Default 10%

      // Data
      periods: [],
      activePeriodId: null,

      employees: INITIAL_EMPLOYEES,
      vaseModels: INITIAL_VASES,
      productionItems: [],
      payments: [],
      drafts: [],
      systemLogs: [],
      goals: [],
      userPreferences: {},

      toggleTheme: () => set((state) => ({ isDarkMode: !state.isDarkMode })),

      setSector: (sector) => set({ currentSector: sector }),

      loginUser: (user) => {
        const state = get();
        const userPrefs = state.userPreferences[user.id];

        // MIGRATION: Ensure a period exists on login if none exists
        if (state.periods.length === 0) {
           const initialPeriodId = uuidv4();
           const now = new Date();
           const name = `${now.toLocaleString('default', { month: 'short' })}/${now.getFullYear()} (Inicial)`;
           set({
             periods: [{
               id: initialPeriodId,
               name: name,
               startDate: Date.now(),
               status: 'ACTIVE'
             }],
             activePeriodId: initialPeriodId
           });
        }

        const themeToApply = userPrefs ? userPrefs.darkMode : false;

        set({ 
          currentUser: user,
          isDarkMode: themeToApply
        });
      },

      logout: () => set((state) => {
        if (state.currentUser) {
           const newLog: SystemLog = {
            id: uuidv4(),
            timestamp: Date.now(),
            action: 'LOGOUT',
            sector: state.currentUser.sector as Sector,
            actorId: state.currentUser.id,
            actorName: state.currentUser.name,
            details: 'Sessão encerrada pelo usuário.',
          };
          return { currentUser: null, currentSector: null, systemLogs: [newLog, ...state.systemLogs] };
        }
        return { currentUser: null, currentSector: null };
      }),

      // --- PERIOD ACTIONS ---
      closePeriod: (supervisorId) => set((state) => {
        const activePeriod = state.periods.find(p => p.status === 'ACTIVE');
        if (!activePeriod) return state;

        const now = Date.now();
        const newPeriodId = uuidv4();
        const dateObj = new Date();
        // Generate next month name logic or simple sequential
        const nextName = `${dateObj.toLocaleString('default', { month: 'short' })}/${dateObj.getFullYear()} - #${state.periods.length + 1}`;

        const updatedPeriods = state.periods.map(p => 
          p.id === activePeriod.id 
            ? { ...p, status: 'CLOSED' as const, endDate: now, closedBy: supervisorId }
            : p
        );

        const newPeriod: Period = {
          id: newPeriodId,
          name: nextName,
          startDate: now,
          status: 'ACTIVE'
        };

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: now,
          action: 'PERIOD_CLOSE',
          sector: Sector.SUPERVISOR,
          actorId: supervisorId,
          actorName: 'Supervisor',
          details: `Período ${activePeriod.name} fechado. Início de: ${newPeriod.name}`
        };

        return {
          periods: [...updatedPeriods, newPeriod],
          activePeriodId: newPeriodId,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- SETTINGS ACTIONS ---
      updateUserPreferences: (userId, newPrefs) => set((state) => {
        const currentPrefs = state.userPreferences[userId] || { userId, ...DEFAULT_USER_PREFS };
        const updatedPrefs = { ...currentPrefs, ...newPrefs };

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'SETTINGS_UPDATE',
          sector: state.currentUser?.sector as Sector || Sector.PRODUCTION,
          actorId: userId,
          actorName: state.currentUser?.name || 'User',
          details: 'Alteração nas configurações do perfil.',
        };

        let newIsDarkMode = state.isDarkMode;
        if (newPrefs.darkMode !== undefined) {
           newIsDarkMode = newPrefs.darkMode;
        }

        return {
          userPreferences: {
            ...state.userPreferences,
            [userId]: updatedPrefs
          },
          isDarkMode: newIsDarkMode,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      addProductionItems: (items) => set((state) => {
        // Ensure active period ID is attached
        const activeId = state.activePeriodId || (state.periods.find(p => p.status === 'ACTIVE')?.id);

        const hydratedItems = items.map(item => {
          const model = state.vaseModels.find(v => v.id === item.modelId);
          return {
            ...item,
            periodId: activeId, // Bind to current period
            productionValue: model ? model.costProduction : 0,
            rawMaterialCost: model ? (model.weightKg * state.rawMaterialCostPerKg) : 0
          };
        });

        const currentUser = state.currentUser;
        const totalValue = hydratedItems.reduce((acc, i) => acc + i.productionValue, 0);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PRODUCTION',
          sector: Sector.PRODUCTION,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: hydratedItems[0]?.producedBy,
          details: `Registro de produção: ${hydratedItems.length} itens.`,
          value: totalValue
        };

        return { 
          productionItems: [...state.productionItems, ...hydratedItems],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      processStageItems: (itemIds, workerId, stage, timestamp) => set((state) => {
        let totalProcessedValue = 0;
        const activeId = state.activePeriodId || (state.periods.find(p => p.status === 'ACTIVE')?.id);

        const updatedItems = state.productionItems.map((item) => {
          if (itemIds.includes(item.id)) {
            const model = state.vaseModels.find(v => v.id === item.modelId);

            // STRICT FLOW CONTROL: FINISHING -> PAINTING
            if (stage === 'finishing') {
              if (item.status !== ItemStatus.AWAITING_FINISHING) {
                 return item;
              }

              const val = model?.costFinishing || 0;
              totalProcessedValue += val;

              return {
                ...item, 
                status: ItemStatus.AWAITING_PAINTING, 
                updatedAt: timestamp,
                finishedBy: workerId,
                finishedInPeriodId: activeId, // Track when it was finished
                finishingValue: val
              };
            }

            // STRICT FLOW CONTROL: PAINTING -> FINISHED
            if (stage === 'painting') {
               if (item.status !== ItemStatus.AWAITING_PAINTING) {
                  return item;
               }

               const salePrice = model?.priceSale || 0;
               const commission = calculatePaintingCommission(salePrice, state.paintingCommissionPercentage);

               totalProcessedValue += commission;

               return {
                ...item, 
                status: ItemStatus.FINISHED, 
                updatedAt: timestamp,
                paintedBy: workerId,
                paintedInPeriodId: activeId, // Track when it was painted
                paintingValue: commission
              };
            }
          }
          return item;
        });

        const currentUser = state.currentUser;
        const actionType = stage === 'finishing' ? 'FINISHING' : 'PAINTING';
        const sector = stage === 'finishing' ? Sector.FINISHING : Sector.PAINTING;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: actionType,
          sector: sector,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Sistema',
          targetId: workerId,
          details: `Processamento de ${itemIds.length} itens no setor ${sector}.`,
          value: totalProcessedValue
        };

        return { 
          productionItems: updatedItems,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- DRAFT ACTIONS ---
      addDraft: (draft) => set((state) => ({ drafts: [draft, ...state.drafts] })),

      removeDraft: (id) => set((state) => ({ drafts: state.drafts.filter(d => d.id !== id) })),

      confirmDraft: (draftId) => {
        const state = get();
        const draft = state.drafts.find(d => d.id === draftId);
        if (!draft) return;

        // Ensure active period exists before confirming
        let activeId = state.activePeriodId;
        if (!activeId && state.periods.length === 0) {
           // Fallback init if empty (should be handled in login, but safe guard)
           const pid = uuidv4();
           set({ periods: [{ id: pid, name: 'Inicial', startDate: Date.now(), status: 'ACTIVE' }], activePeriodId: pid });
           activeId = pid;
        }

        if (draft.type === 'PRODUCTION' && draft.productionData) {
          const newItems: ProductionItem[] = [];

          const draftDate = new Date(draft.selectedDate);
          const yearDigit = getYearDigit(draftDate);
          const dayOfYear = getDayOfYear(draftDate);
          const cipPrefix = `${yearDigit}${dayOfYear}`;

          const usedSequences = state.productionItems
            .filter(item => item.cip && item.cip.startsWith(cipPrefix))
            .map(item => parseInt(item.cip!.slice(5), 10))
            .filter(n => !isNaN(n));

          let nextSequence = usedSequences.length > 0 ? Math.max(...usedSequences) + 1 : 0;

          for (const { modelId, quantity } of draft.productionData) {
            const model = state.vaseModels.find(v => v.id === modelId);
            if (model) {
               for (let i = 0; i < quantity; i++) {

                if (nextSequence > 99) {
                   throw new Error("Limite diário de produção (100 vasos) atingido para esta data. Impossível gerar novo CIP.");
                }

                const cip = `${cipPrefix}${nextSequence.toString().padStart(2, '0')}`;

                if (state.productionItems.some(item => item.cip === cip)) {
                    throw new Error(`Erro de unicidade: O CIP ${cip} já existe no sistema.`);
                }

                nextSequence++;

                newItems.push({
                  id: uuidv4(),
                  cip: cip,
                  modelId: model.id,
                  modelName: model.name,
                  type: model.type,
                  status: model.type === VaseType.WITH_SHELL ? ItemStatus.AWAITING_FINISHING : ItemStatus.STOCK_NO_SHELL,
                  createdAt: draft.selectedDate,
                  updatedAt: draft.selectedDate,
                  producedBy: draft.userId,
                  periodId: activeId || undefined, // Bind to active period
                  productionValue: 0,
                  rawMaterialCost: 0
                });
               }
            }
          }

          if (newItems.length > 0) {
            get().addProductionItems(newItems);
          }
        } else if ((draft.type === 'FINISHING' || draft.type === 'PAINTING') && draft.processingIds) {
           const stage = draft.type === 'FINISHING' ? 'finishing' : 'painting';
           get().processStageItems(draft.processingIds, draft.userId, stage, draft.selectedDate);
        }

        get().removeDraft(draftId);
      },

      // --- GOALS ACTIONS ---
      addGoal: (goal) => set((state) => {
        const currentUser = state.currentUser;
        const activeId = state.activePeriodId || (state.periods.find(p => p.status === 'ACTIVE')?.id);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal.employeeId,
          details: `Meta ${goal.period} definida.`,
        };

        return {
          goals: [...state.goals, { ...goal, periodId: activeId }], // Bind goal to period
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      deleteGoal: (id) => set((state) => {
        const goal = state.goals.find(g => g.id === id);
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'GOAL_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: goal?.employeeId,
          details: `Meta removida.`,
        };

        return {
          goals: state.goals.filter(g => g.id !== id),
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // --- SUPERVISOR ACTIONS ---
      updateSupervisorPassword: (pass) => set({ supervisorPassword: pass }),

      updateRawMaterialCostPerKg: (value) => set((state) => {
        const prev = state.rawMaterialCostPerKg;
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'ADMIN_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          details: `Custo do traço alterado de R$ ${prev.toFixed(2)} para R$ ${value.toFixed(2)}`,
        };

        return { 
           rawMaterialCostPerKg: value,
           systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      updatePaintingCommissionPercentage: (value) => set((state) => {
        const prev = state.paintingCommissionPercentage;
        const currentUser = state.currentUser;

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'ADMIN_UPDATE',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          details: `Comissão de pintura alterada de ${prev}% para ${value}%`,
        };

        return {
          paintingCommissionPercentage: value,
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      addVaseModel: (model) => set((state) => ({ vaseModels: [...state.vaseModels, model] })),
      updateVaseModel: (model) => set((state) => ({
        vaseModels: state.vaseModels.map((v) => (v.id === model.id ? model : v))
      })),
      deleteVaseModel: (id) => set((state) => ({
        vaseModels: state.vaseModels.filter((v) => v.id !== id)
      })),
      addEmployee: (emp) => set((state) => ({ employees: [...state.employees, emp] })),
      updateEmployee: (emp) => set((state) => ({
        employees: state.employees.map((e) => (e.id === emp.id ? emp : e))
      })),
      addPayment: (payment) => set((state) => {
        const currentUser = state.currentUser;
        const activeId = state.activePeriodId || (state.periods.find(p => p.status === 'ACTIVE')?.id);

        const newLog: SystemLog = {
          id: uuidv4(),
          timestamp: Date.now(),
          action: 'PAYMENT',
          sector: Sector.SUPERVISOR,
          actorId: currentUser?.id || 'system',
          actorName: currentUser?.name || 'Supervisor',
          targetId: payment.employeeId,
          details: `Pagamento registrado para ${payment.employeeName}. Obs: ${payment.observation || '-'}`,
          value: payment.amount
        };

        return { 
          payments: [ { ...payment, periodId: activeId }, ...state.payments],
          systemLogs: [newLog, ...state.systemLogs]
        };
      }),

      // Deprecated in favor of Period System, but logic kept to clear local state if needed manually (dev)
      resetData: () => set({
        productionItems: [],
        payments: [],
        employees: INITIAL_EMPLOYEES,
        vaseModels: INITIAL_VASES,
        supervisorPassword: DEFAULT_SUPERVISOR_PASS,
        rawMaterialCostPerKg: 0.26,
        paintingCommissionPercentage: 10,
        drafts: [],
        systemLogs: [],
        goals: [],
        userPreferences: {},
        periods: [],
        activePeriodId: null,
        systemVersion: INITIAL_VERSION,
        changelog: INITIAL_CHANGELOG
      }),

      // --- VERSION CONTROL ACTIONS ---
      registerSystemUpdate: (type: ChangeType, description: string) => set((state) => {
        const parts = state.systemVersion.split('.').map(Number);
        if (parts.length !== 3) return state;

        let [major, minor, patch] = parts;

        switch (type) {
          case 'MAJOR': major++; minor = 0; patch = 0; break;
          case 'FEATURE': minor++; patch = 0; break;
          case 'IMPROVEMENT': case 'FIX': patch++; break;
        }

        const newVersion = `${major}.${minor}.${patch}`;

        const newEntry: ChangelogEntry = {
          version: newVersion,
          date: Date.now(),
          type,
          description
        };

        if (state.changelog.length > 0 && state.changelog[0].description === description) {
           return state;
        }

        return {
          systemVersion: newVersion,
          changelog: [newEntry, ...state.changelog]
        };
      })
    }),
    {
      name: 'home-pots-storage',
      storage: createJSONStorage(() => localStorage),
    }
  )
);

/**
 * Centraliza o cálculo do custo de matéria-prima (Custo do Traço) de um vaso.
 * 
 * Regra: Peso do Vaso (Kg) * Custo Global do Traço (R$/Kg)
 * 
 * @param weightKg Peso do modelo em Kg
 * @param costPerKg Custo atual do traço configurado no sistema
 * @returns O custo calculado da matéria-prima
 */
export const calculateRawMaterialCost = (weightKg: number, costPerKg: number): number => {
    if (weightKg <= 0 || costPerKg <= 0) return 0;
    return weightKg * costPerKg;
};

/**
 * Calcula a comissão de pintura baseada no preço de venda e percentual configurado.
 * 
 * Regra: Preço de Venda * (Porcentagem / 100)
 * 
 * @param salePrice Preço de venda do vaso
 * @param percentage Percentual de comissão (ex: 10 para 10%)
 * @returns O valor da comissão
 */
export const calculatePaintingCommission = (salePrice: number, percentage: number): number => {
    if (salePrice <= 0 || percentage < 0) return 0;
    return salePrice * (percentage / 100);
};

/**
 * Calcula o número de dias passados entre uma data e hoje (ou outra data de referência).
 * Retorna inteiro arredondado para baixo.
 */
export const getDaysDiff = (from: number, to: number = Date.now()): number => {
    const msPerDay = 1000 * 60 * 60 * 24;
    return Math.floor((to - from) / msPerDay);
};

// --- CIP GENERATION UTILS ---

/**
 * Obtém o último dígito do ano.
 * Ex: 2025 -> 5
 */
export const getYearDigit = (date: Date): string => {
    return date.getFullYear().toString().slice(-1);
};

/**
 * Obtém o dia do ano (001 a 366).
 */
export const getDayOfYear = (date: Date): string => {
    const start = new Date(date.getFullYear(), 0, 0);
    const diff = date.getTime() - start.getTime();
    const oneDay = 1000 * 60 * 60 * 24;
    const day = Math.floor(diff / oneDay);
    return day.toString().padStart(3, '0');
};

/**
 * Gera o Código de Identificação de Produção (CIP) no formato YDDDSS.
 * 
 * @param date Data de fabricação
 * @param sequence Sequencial do dia (0 a 99)
 * @returns Código formatado string (ex: 722100)
 */
export const generateCIP = (date: Date, sequence: number): string => {
    const y = getYearDigit(date);
    const ddd = getDayOfYear(date);
    const ss = sequence.toString().padStart(2, '0');

    return `${y}${ddd}${ss}`;
};

import React, { useState, useMemo } from 'react';
import { useStore } from '../store';
import { ItemStatus, Draft, Sector } from '../types';
import { Button } from '../components/UI';
import { Check, ArrowLeft, PaintBucket, Brush, TrendingUp, Wallet, Hammer, FileText, Trash2, Edit, Send, Calendar, Save, X, Settings, Clock, AlertTriangle } from 'lucide-react';
import HistoryModal from '../components/HistoryModal';
import { v4 as uuidv4 } from 'uuid';
import { GoalProgressBar, GoalsDetailView } from '../components/GoalComponents';
import EmployeeSettingsScreen from '../components/EmployeeSettingsScreen';
import { calculatePaintingCommission, getDaysDiff } from '../utils/calculations';

interface Props {
  stage: 'finishing' | 'painting';
}

type ViewMode = 'DASHBOARD' | 'REVIEW' | 'GOALS' | 'SETTINGS';

const ProcessingScreen: React.FC<Props> = ({ stage }) => {
  const { productionItems, addDraft, removeDraft, confirmDraft, drafts, currentUser, logout, vaseModels, payments, goals, userPreferences, paintingCommissionPercentage, activePeriodId } = useStore();

  // View State
  const [viewMode, setViewMode] = useState<ViewMode>('DASHBOARD');

  // Selection State
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);

  const [feedback, setFeedback] = useState<string | null>(null);
  const [historyMode, setHistoryMode] = useState<'none' | 'items' | 'financial' | 'payments'>('none');

  // --- Calculations ---
  const today = new Date().toDateString();

  const myDrafts = useMemo(() => {
    const draftType = stage === 'finishing' ? 'FINISHING' : 'PAINTING';
    return drafts.filter(d => d.type === draftType && d.userId === currentUser?.id)
          .sort((a,b) => b.createdAt - a.createdAt);
  }, [drafts, currentUser, stage]);

  const itemsInDrafts = useMemo(() => {
     const ids = new Set<string>();
     myDrafts.forEach(d => d.processingIds?.forEach(id => ids.add(id)));
     return ids;
  }, [myDrafts]);

  // Filter Completed Items by Active Period to reset counters
  const myPeriodItems = useMemo(() => productionItems.filter(p => {
    if (stage === 'finishing') return p.finishedBy === currentUser?.id && p.finishedInPeriodId === activePeriodId;
    if (stage === 'painting') return p.paintedBy === currentUser?.id && p.paintedInPeriodId === activePeriodId;
    return false;
  }), [productionItems, currentUser, stage, activePeriodId]);

  const myPeriodPayments = useMemo(() => 
    payments.filter(p => p.employeeId === currentUser?.id && p.periodId === activePeriodId),
  [payments, currentUser, activePeriodId]);

  const myTodaysItems = myPeriodItems.filter(p => 
     new Date(p.updatedAt).toDateString() === today
  );

  const dailyTotalQty = myTodaysItems.length;
  const dailyEarnings = myTodaysItems.reduce<number>((acc, item) => {
    if (stage === 'finishing') return acc + (item.finishingValue || 0);
    if (stage === 'painting') return acc + (item.paintingValue || 0);
    return acc;
  }, 0);

  const totalProducedValue = myPeriodItems.reduce<number>((acc, item) => {
     if (stage === 'finishing') return acc + (item.finishingValue || 0);
     if (stage === 'painting') return acc + (item.paintingValue || 0);
     return acc;
  }, 0);

  const totalReceivedValue = myPeriodPayments.reduce((acc, pay) => acc + pay.amount, 0);
  const currentBalance = totalProducedValue - totalReceivedValue;

  // Config
  const config = stage === 'finishing' ? {
    inputStatus: ItemStatus.AWAITING_FINISHING,
    title: 'Setor de Acabamento',
    icon: <Brush className="w-6 h-6 text-on-secondary-container" />,
    actionLabel: 'Confirmar Acabamento',
    emptyMsg: 'Sem vasos para acabamento.',
    themeColor: 'secondary',
    alertThreshold: 2 // Days
  } : {
    inputStatus: ItemStatus.AWAITING_PAINTING,
    title: 'Setor de Pintura',
    icon: <PaintBucket className="w-6 h-6 text-on-primary-container" />,
    actionLabel: 'Confirmar Pintura',
    emptyMsg: 'Sem vasos para pintura.',
    themeColor: 'primary',
    alertThreshold: 1 // Days
  };

  // Pending items are NOT filtered by period (work accumulates)
  const pendingItems = useMemo(() => {
    const list = productionItems.filter(i => 
      i.status === config.inputStatus && !itemsInDrafts.has(i.id)
    );

    // Sort by age (Older first - FIFO)
    return list.sort((a,b) => {
       const dateA = stage === 'finishing' ? a.createdAt : a.updatedAt;
       const dateB = stage === 'finishing' ? b.createdAt : b.updatedAt;
       return dateA - dateB;
    });
  }, [productionItems, config.inputStatus, itemsInDrafts, stage]);

  // Earnings for current selection
  const selectionEarnings = Array.from(selectedIds).reduce<number>((acc, id) => {
    const item = pendingItems.find(i => i.id === id);
    if (!item) return acc;
    const model = vaseModels.find(v => v.id === item.modelId);
    if (!model) return acc;

    if (stage === 'finishing') return acc + (model.costFinishing || 0);
    // Use dynamic commission percentage for estimates
    if (stage === 'painting') return acc + calculatePaintingCommission(model.priceSale || 0, paintingCommissionPercentage);
    return acc;
  }, 0);

  // Theme Classes
  const themeClasses = config.themeColor === 'secondary' ? {
     bg: 'bg-secondary',
     container: 'bg-secondary-container',
     text: 'text-secondary',
     border: 'border-secondary',
     onContainer: 'text-on-secondary-container',
     onBg: 'text-on-secondary'
  } : {
     bg: 'bg-primary',
     container: 'bg-primary-container',
     text: 'text-primary',
     border: 'border-primary',
     onContainer: 'text-on-primary-container',
     onBg: 'text-on-primary'
  };

  // --- Preferences Check ---
  const prefs = useMemo(() => {
     if (!currentUser) return null;
     return userPreferences[currentUser.id] || {
        showFinancials: true,
        showProductionQty: true,
        showGoalsBar: true
     };
  }, [currentUser, userPreferences]);

  // --- Handlers ---

  const toggleSelect = (id: string) => {
    const next = new Set(selectedIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setSelectedIds(next);
  };

  const proceedToReview = () => {
    if (selectedIds.size > 0) {
      setViewMode('REVIEW');
    }
  };

  const handleSaveAsDraft = () => {
    if (!currentUser) return;

    const processDate = new Date(selectedDate + 'T12:00:00').getTime();

    const newDraft: Draft = {
        id: uuidv4(),
        type: stage === 'finishing' ? 'FINISHING' : 'PAINTING',
        sector: currentUser.sector as any,
        userId: currentUser.id,
        selectedDate: processDate,
        createdAt: Date.now(),
        processingIds: Array.from(selectedIds)
    };

    addDraft(newDraft);

    setSelectedIds(new Set());
    setViewMode('DASHBOARD');
    setFeedback('Rascunho salvo!');
    setTimeout(() => setFeedback(null), 2000);
  };

  const handleEditDraft = (draft: Draft) => {
      removeDraft(draft.id);
      const restoredIds = new Set<string>(draft.processingIds);
      setSelectedIds(restoredIds);
      setSelectedDate(new Date(draft.selectedDate).toISOString().split('T')[0]);
