                     {/* Time Alert Badge */}
                     {(isLate || isWarning) && !isSelected && (
                        <div className={`flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold uppercase ${isLate ? 'bg-error-container text-on-error-container' : 'bg-amber-100 text-amber-800'}`}>
