                  {/* Expanded Detail View */}
                  {expandedEmployeeId === emp.id && (
                     <div className="mt-4 pt-3 border-t border-outline-variant animate-in slide-in-from-top-2">
                        <div className="space-y-2 text-sm">
                           <div className="flex justify-between">
